const INTERFACE_BYTES: usize = 3 * WORD;
const READ_CHUNK: usize = 1024 * 1024;
const STANDARD_INTERFACE_NAME: &[u8] = b"PKCS 11";
pub(crate) const MAX_TABLE_CANDIDATES: usize = 512;
/// Slots in the 2.x `CK_FUNCTION_LIST` prefix every 3.x layout starts
/// with: the accepted width when a 3.x-labelled table validates only
/// its legacy prefix (a provider mislabelling quirk).
const LEGACY_PREFIX_SLOTS: usize = 68;
/// Slots in a 3.0/3.1 `CK_FUNCTION_LIST_3_0`: a structural failure inside
/// `LEGACY_PREFIX_SLOTS..STANDARD_30_SLOTS` — unmapped memory, file-backed
/// non-executable memory, or anonymous non-executable memory — refutes both
/// the 92-wide and the 104-wide hypotheses, leaving the 68-slot prefix
/// complete. Executable anonymous memory and executable unusable-path
/// mappings prove nothing: they may hold a real extension.
const STANDARD_30_SLOTS: usize = 92;
const MAX_DECODED_TABLE_ENTRIES: usize = 512 * 104;
pub(crate) const MAX_INTERFACE_RECORDS: usize = 512;
const MAX_MAPS_BYTES: u64 = 64 * 1024 * 1024;
const MAX_MAP_ENTRIES: usize = 1_048_576;
const MAX_MOUNTINFO_BYTES: u64 = 64 * 1024 * 1024;
const MAX_MOUNTINFO_ENTRIES: usize = 1_048_576;
// ponytail: this independent ceiling is the calibration knob if real providers hit it.
pub(crate) const DEFAULT_WORK_CEILING: u64 = 16 * 1024 * 1024;
/// Production Inventory per-pass attempted-I/O window. Calibrated 2026-11-09:
/// the trivial nodata harness maps 16.3 MiB of sub-8-MiB objects on Fedora
/// (14.8 MiB on dev) plus ~1 MiB of provider pin and snapshot reads, so the
/// old 16 MiB window tripped from pass 0 there and the fedora cgroup cell
/// attached zero endpoints. 64 MiB fits that closure with margin and covers
/// larger PKCS#11 hosts' closures; identity hashing charges the window
/// only (large providers pin while the window admits them), per-object
/// shortfalls on snapshots and memory reads name themselves without
/// stopping the pass, and the work-units, retained, and deadline bounds
/// still fence worst-case passes. May be raised when measured, never
/// lowered: the closure-fit test below pins the floor.
pub(crate) const INVENTORY_WINDOW_IO_BYTES: u64 = 64 << 20;
/// Production Detailed-capture attempted-I/O total: the whole window a
/// demand-paged export walk is charged to under `DetailedLegacy`
/// (same value as `ScanLimits::default().total_bytes`). Together with
/// [`INVENTORY_WINDOW_IO_BYTES`] this is the refusal threshold for
/// dynamic spans: a span (or walked total) larger than the policy's
/// production window refuses cached per object, without draining.
pub(crate) const DETAILED_CAPTURE_IO_BYTES: u64 = 512 << 20;
pub(crate) const IO_CEILING_REASON: &str =
    "capture attempted-I/O ceiling reached; remaining provider bytes were not read";
/// A single object outgrew its own allowance while the capture window
/// still admits: the object is refused, never the pass. Stays distinct
/// from [`IO_CEILING_REASON`], which stops the whole pass.
pub(crate) const PER_OBJECT_ALLOWANCE_REASON: &str =
    "per-object I/O allowance reached; remaining bytes of this object were not read";
pub(crate) const WORK_CEILING_REASON: &str =
    "capture discovery work ceiling reached; remaining provider bytes were not scanned";
pub(crate) const SCAN_DEADLINE_REASON: &str =
    "capture discovery deadline reached; remaining provider bytes were not scanned";
pub(crate) const SCAN_CLOCK_REASON: &str =
    "monotonic clock read failed; remaining provider bytes were not scanned";
pub(crate) const TABLE_WINDOW_CEILING_REASON: &str =
    "discovery window table decode allowance reached; remaining table data was not decoded";
pub(crate) const INTERFACE_WINDOW_CEILING_REASON: &str =
    "discovery window interface decode allowance reached; remaining interface data was not decoded";
pub(crate) const COLLECTION_STOP_REASON: &str =
    "cgroup collection stopped or shared work allowance exhausted";
/// Stable marker inside the scan's own verified-absence vocabulary. The
/// scan-to-live-candidate completeness boundary (`scan_skip_truncates`)
/// matches these markers — the push sites below must keep using them.
pub(crate) const NO_TABLE_FOUND_MARKER: &str =
    "no function table was found in its file-backed data";
/// Shell-quote a module path for the suggested discover command, so
/// the line stays copy-pasteable when the path carries spaces or shell
/// metacharacters. Paths of letters, digits, `/`, `_`, `-` and `.`
/// pass through byte-identical; anything else is single-quoted with
/// embedded quotes escaped.
fn shell_quote_module_path(module_path: &str) -> String {
    let safe = !module_path.is_empty()
        && module_path
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'/' | b'_' | b'-' | b'.'));
    if safe {
        return module_path.to_string();
    }
    let mut quoted = String::with_capacity(module_path.len() + 2);
    quoted.push('\'');
    let mut first = true;
    for part in module_path.split('\'') {
        if !first {
            quoted.push_str("'\\''");
        }
        first = false;
        quoted.push_str(part);
    }
    quoted.push('\'');
    quoted
}
/// Skip reason for a module whose table the memory scan cannot see: the
/// fixed diagnosis plus the action that observes such a provider. One
/// line; `module_path` is the skipped module's own path.
pub(crate) fn no_table_found_reason(module_path: &str, hinted: bool) -> String {
    let named = if hinted {
        "matched a --module hint; "
    } else {
        ""
    };
    let quoted = shell_quote_module_path(module_path);
    format!(
        "{named}{NO_TABLE_FOUND_MARKER}; a table built at run time in .bss or on the heap is \
         outside the memory scan's reach; to observe it, run p11scope-discover --module \
         {quoted} -o <manifest.json> and pass --manifest <manifest.json>"
    )
}
