pub(crate) const MAPS_ENTRY_CEILING_REASON: &str =
    "capture /proc maps entry ceiling reached; remaining mappings were not read";
pub(crate) const MOUNTINFO_CEILING_REASON: &str =
    "capture mountinfo byte ceiling reached; the incomplete mount table was refused";
pub(crate) const MOUNTINFO_ENTRY_CEILING_REASON: &str =
    "capture mountinfo entry ceiling reached; the incomplete mount table was refused";

pub(crate) fn target_layout(abi: ElfAbi) -> LinuxLayout {
    match abi {
        ElfAbi::Lp64 => LinuxLayout::Lp64,
        ElfAbi::Ilp32 => LinuxLayout::Ilp32,
    }
}

pub(crate) fn read_elf_snapshot(
    file: &File,
    budget: &mut CaptureWorkBudget,
) -> Result<ElfSnapshot, String> {
    read_elf_snapshot_with(
        file,
        budget,
        CaptureWorkBudget::check_deadline_now,
        |file, bytes, offset| file.read_at(bytes, offset),
    )
}

fn read_elf_snapshot_with(
    file: &File,
    budget: &mut CaptureWorkBudget,
    mut deadline: impl FnMut(&mut CaptureWorkBudget) -> Option<&'static str>,
    mut reader: impl FnMut(&File, &mut [u8], u64) -> std::io::Result<usize>,
) -> Result<ElfSnapshot, String> {
    // v0.8.0: no whole-size gate here. The chunked reads below enforce
    // the per-operation and capture allowances incrementally, so a
    // large object degrades through the I/O ceiling's named gap instead
    // of a size refusal, and memory never exceeds the allowance.
    let mut operation_bytes = 0u64;
    ElfSnapshot::read_with_reader(file, |file, bytes, offset| {
        if let Some(reason) = deadline(budget) {
            return Err(std::io::Error::other(reason));
        }
        let allowed = budget.allowed_io(operation_bytes, bytes.len());
        if allowed == 0 {
            let reason = budget.io_shortfall_reason(operation_bytes);
            return Err(std::io::Error::other(reason));
        }
        let read = reader(file, &mut bytes[..allowed], offset)?;
        // One charging rule for file-content reads: bytes debit the
        // inventory window (the per-operation leg is enforced above),
        // while parsed entries charge work through `spend`. Converting
        // the bytes to collection work here too would double-charge a
        // large snapshot against the small cgroup work allowance.
        budget.record_window_io(read);
        operation_bytes += read as u64;
        Ok(read)
    })
}

// v0.8.0: the inventory full-length mapped-byte reservation is retired
// with the other size gates. Unretained export checks map demand-paged
// under both policies and charge the structural table bytes after the
// parse (the Detailed shape below), so a large object is examined for
// the cost of its tables, not refused for the length of its file. File
// growth across the parse stays fenced by the caller's pin-before/after
// bracket; a stop reached during parsing keeps the window/deadline gap.

/// A previously retained file may already be watched by the instance hooks.
/// Read its exports without mapping it in the observer's shared mm. The
/// ordinary byte/deadline limits and the caller's post-read pin check remain.
#[cfg(test)]
fn read_retained_export_facts_budgeted(
    file: &File,
    wanted: &[&str],
    budget: &mut CaptureWorkBudget,
) -> Result<(ElfAbi, Vec<(String, u64)>), String> {
    if matches!(budget.policy(), DiscoveryPolicy::Inventory(_))
        && !budget.pass_owner_ref().has_active_scan()
    {
        return Err("read failed: inventory discovery requires an active scan".into());
    }
    let facts = read_elf_snapshot(file, budget)
        .and_then(|snapshot| Ok((snapshot.abi(), snapshot.exports_matching(wanted)?)));
    if let Some(reason) = budget.check_deadline_now() {
        return Err(format!("read failed: {reason}"));
    }
    facts
}

/// Demand-paged export facts for unretained files; retained files use bounded
/// reads to avoid invalidating the very instances the observer is watching.
/// Both policies share the sparse structural post-read charge.
#[cfg(test)]
fn read_export_facts_budgeted(
    file: &File,
    wanted: &[&str],
    budget: &mut CaptureWorkBudget,
) -> Result<(ElfAbi, Vec<(String, u64)>), String> {
    if budget.retained_mapped_identity(file).is_some() {
        return read_retained_export_facts_budgeted(file, wanted, budget);
    }
    let (abi, exports, charged) = p11scope_manifest::elf::read_export_facts(file, wanted)?;
    let remaining = budget.remaining_window_io().unwrap_or(0);
    if charged > remaining {
        budget.record_io(usize::try_from(remaining).unwrap_or(usize::MAX));
        return Err(format!("read failed: {IO_CEILING_REASON}"));
    }
    budget.record_io(usize::try_from(charged).unwrap_or(usize::MAX));
    Ok((abi, exports))
}

/// Debit window bytes for one export-facts step: a window too small
/// for the step drains its remainder and refuses with the I/O ceiling
/// gap, never a partial debit. Window-only: the demand-paged table
/// walk must not convert bytes to collection work (entries are
/// already charged via `spend`), or one pandoc-sized walk stops the
/// whole cgroup pass against the shared allowance.
fn debit_window_io(budget: &mut CaptureWorkBudget, bytes: u64) -> Result<(), String> {
    let remaining = budget.remaining_window_io().unwrap_or(0);
    if bytes > remaining {
        budget.record_window_io(usize::try_from(remaining).unwrap_or(usize::MAX));
        return Err(format!("read failed: {IO_CEILING_REASON}"));
    }
    budget.record_window_io(usize::try_from(bytes).unwrap_or(usize::MAX));
    Ok(())
}

fn read_raw_scan_facts_budgeted(
    file: &File,
    wanted: &[&str],
    budget: &mut CaptureWorkBudget,
) -> Result<ElfExportFacts, String> {
    let (abi, exports, excluded_anchor_ranges, work_rest, getter_present, witness_fault) =
        if budget.retained_mapped_identity(file).is_some() {
            let snapshot = read_elf_snapshot(file, budget)?;
            // The snapshot read charged the bytes incrementally; spend
            // the table entries before the parse and the remainder after.
            let pre_entries = snapshot.table_bounds().table_entries();
            if pre_entries > 0 {
                budget.spend(pre_entries).map_err(str::to_string)?;
            }
            let facts = snapshot.raw_scan_facts(wanted)?;
            (
                facts.abi,
                facts.exports,
                facts.excluded_anchor_ranges,
                facts.work_units.saturating_sub(pre_entries),
                facts.getter_present,
                facts.witness_fault,
            )
        } else {
            // Both policies bound the tables before the parse and debit
            // the remainder after; no whole-file gate is introduced for
            // sparse objects.
            if matches!(budget.policy(), DiscoveryPolicy::Inventory(_))
                && !budget.pass_owner_ref().has_active_scan()
            {
                return Err("read failed: inventory discovery requires an active scan".into());
            }
            // The header probe refuses over-cap header tables with the named
            // gap before any mapping, charging only the probe bytes it read.
            // Spans are only sized there; they refuse here, against the whole
            // production window the walk would be charged to — never a fixed
            // per-span cap, and never the remaining bytes (a refusal cached
            // under a drained window would skip a real file later). The
            // refusal charges only the probe and caches per object, so a
            // later object in the same pass still scans.
            let (gated, probe_bytes) = p11scope_manifest::elf::read_table_bounds(file);
            let bounds = match gated {
                Ok(bounds) => bounds,
                Err(reason) => {
                    budget.record_io(usize::try_from(probe_bytes).unwrap_or(usize::MAX));
                    return Err(reason);
                }
            };
            let window_bytes = match budget.policy() {
                DiscoveryPolicy::Inventory(_) => INVENTORY_WINDOW_IO_BYTES,
                DiscoveryPolicy::DetailedLegacy => DETAILED_CAPTURE_IO_BYTES,
            };
            if let Some(reason) = bounds.span_refusal(window_bytes) {
                budget.record_io(usize::try_from(probe_bytes).unwrap_or(usize::MAX));
                return Err(reason);
            }
            let pre_bytes = bounds.table_bytes();
            if pre_bytes > 0 {
                debit_window_io(budget, pre_bytes)?;
            }
            let pre_entries = bounds.table_entries();
            if pre_entries > 0 {
                budget.spend(pre_entries).map_err(str::to_string)?;
            }
            let facts =
                p11scope_manifest::elf::read_raw_scan_facts_bounded(file, wanted, u64::MAX)?;
            debit_window_io(budget, facts.structural_bytes.saturating_sub(pre_bytes))?;
            (
                facts.abi,
                facts.exports,
                facts.excluded_anchor_ranges,
                facts.work_units.saturating_sub(pre_entries),
                facts.getter_present,
                facts.witness_fault,
            )
        };
    budget.spend(work_rest).map_err(str::to_string)?;
    if let Some(reason) = budget.check_deadline_now() {
        return Err(reason.into());
    }
    Ok(ElfExportFacts {
        abi,
        exports,
        getter_present,
        witness_fault,
        excluded_anchor_ranges,
    })
}

fn raw_anchor_overlaps_metadata(ranges: &[(u64, u64)], offset: u64, width: usize) -> bool {
    let Some(end) = offset.checked_add(width as u64) else {
        return true;
    };
    let next = ranges.partition_point(|(_, end)| *end <= offset);
    ranges.get(next).is_some_and(|(start, _)| *start < end)
}

pub(crate) fn read_mountinfo<R: Read>(
    reader: R,
    budget: &mut CaptureWorkBudget,
) -> Result<String, String> {
    read_mountinfo_with(
        reader,
        budget,
        READ_CHUNK,
        CaptureWorkBudget::check_deadline_now,
    )
}

pub(crate) fn read_mountinfo_with<R: Read>(
    mut reader: R,
    budget: &mut CaptureWorkBudget,
    chunk_size: usize,
    mut deadline: impl FnMut(&mut CaptureWorkBudget) -> Option<&'static str>,
) -> Result<String, String> {
    // The mount table is per-scan overhead (read once, cached, window-charged):
    // gating it on the per-object leg would make small-but-legitimate legs
    // unusable on mount-heavy hosts, so only the absolute byte cap and the
    // entry cap below bound the read. Worst case is the 64M absolute cap
    // plus the pass window (the 8M per-operation leg no longer applies to
    // this read); realistic tables (kilobytes) are unaffected.
    // A zero per-object leg still refuses: a degenerate leg admits nothing.
    if budget.limits().per_object_bytes == 0 {
        return Err(MOUNTINFO_CEILING_REASON.into());
    }
    let table_cap = MAX_MOUNTINFO_BYTES;

    let mut table = Vec::new();
    let mut observed_lines = 0usize;
    let mut newline_count = 0usize;
    let mut chunk = vec![0; chunk_size.max(1)];
    loop {
        if let Some(reason) = budget.stopped_reason() {
            return Err(reason.into());
        }
        if let Some(reason) = deadline(budget) {
            return Err(reason.into());
        }

        let capture_left = budget.remaining_window_io().unwrap_or(0);
        if capture_left == 0 {
            if matches!(budget.policy(), DiscoveryPolicy::Inventory(_)) {
                budget.pass_owner().set_scan_stop(IO_CEILING_REASON);
            }
            return Err(IO_CEILING_REASON.into());
        }
        let table_bytes = u64::try_from(table.len()).unwrap_or(u64::MAX);
        let table_left = table_cap.saturating_sub(table_bytes);
        let wanted = u64::try_from(chunk.len())
            .unwrap_or(u64::MAX)
            .min(capture_left)
            .min(table_left.saturating_add(1));
        let wanted = usize::try_from(wanted).unwrap_or(chunk.len());
        if wanted == 0 {
            return Err(MOUNTINFO_CEILING_REASON.into());
        }
        budget.spend(1).map_err(str::to_string)?;

        let read = match reader.read(&mut chunk[..wanted]) {
            Ok(read) => read,
            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(error) => return Err(format!("cannot read mount table: {error}")),
        };
        budget.record_io(read);
        if read == 0 {
            if let Some(reason) = deadline(budget) {
                return Err(reason.into());
            }
            return String::from_utf8(table)
                .map_err(|error| format!("mount table is not valid UTF-8: {error}"));
        }

        let next_len = table
            .len()
            .checked_add(read)
            .ok_or_else(|| MOUNTINFO_CEILING_REASON.to_string())?;
        let newlines = chunk[..read].iter().filter(|byte| **byte == b'\n').count();
        let next_newline_count = newline_count
            .checked_add(newlines)
            .ok_or_else(|| MOUNTINFO_ENTRY_CEILING_REASON.to_string())?;
        let next_lines = next_newline_count
            .checked_add(usize::from(chunk[read - 1] != b'\n'))
            .ok_or_else(|| MOUNTINFO_ENTRY_CEILING_REASON.to_string())?;
        let added_lines = next_lines.saturating_sub(observed_lines);
        budget
            .spend(u64::try_from(added_lines).unwrap_or(u64::MAX))
            .map_err(str::to_string)?;
        if u64::try_from(next_len).unwrap_or(u64::MAX) > table_cap {
            return Err(MOUNTINFO_CEILING_REASON.into());
        }
        if next_lines > MAX_MOUNTINFO_ENTRIES {
            return Err(MOUNTINFO_ENTRY_CEILING_REASON.into());
        }
        table.extend_from_slice(&chunk[..read]);
        newline_count = next_newline_count;
        observed_lines = next_lines;
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ScanLimits {
    pub per_object_bytes: u64,
    pub total_bytes: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InventoryWindowLimits {
    pub(crate) io_bytes: u64,
    pub(crate) work_units: u64,
    pub(crate) decoded_tables: usize,
    pub(crate) decoded_entries: usize,
    pub(crate) interfaces: usize,
}

impl InventoryWindowLimits {
    pub fn new(
        io_bytes: u64,
        work_units: u64,
        decoded_tables: usize,
        decoded_entries: usize,
        interfaces: usize,
    ) -> Result<Self, String> {
        if io_bytes == 0
            || work_units == 0
            || decoded_tables == 0
            || decoded_entries == 0
            || interfaces == 0
        {
            return Err("inventory discovery window limits must all be non-zero".into());
        }
        Ok(Self {
            io_bytes,
            work_units,
            decoded_tables,
            decoded_entries,
            interfaces,
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InventoryRetainedLimits {
    table_keys: usize,
    runtime_keys: usize,
    interface_keys: usize,
    inspection_cache_entries: usize,
    export_cache_entries: usize,
    /// Accounted key/value payload bytes. This excludes allocator and BTree
    /// node overhead and is not a heap or RSS measurement.
    cache_bytes: u64,
}

impl InventoryRetainedLimits {
    pub fn new(
        table_keys: usize,
        runtime_keys: usize,
        interface_keys: usize,
        inspection_cache_entries: usize,
        export_cache_entries: usize,
        cache_bytes: u64,
    ) -> Result<Self, String> {
        if table_keys == 0
            || runtime_keys == 0
            || interface_keys == 0
            || inspection_cache_entries == 0
            || export_cache_entries == 0
            || cache_bytes == 0
        {
            return Err("inventory retained discovery limits must all be non-zero".into());
        }
        Ok(Self {
            table_keys,
            runtime_keys,
            interface_keys,
            inspection_cache_entries,
            export_cache_entries,
            cache_bytes,
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InventoryDiscoveryLimits {
    pub(crate) per_operation_bytes: u64,
    pub(crate) window: InventoryWindowLimits,
    retained: InventoryRetainedLimits,
}

impl InventoryDiscoveryLimits {
    /// The retained-file ceilings, for pass-limit reshaping that keeps
    /// the run's retained maps.
    #[cfg(test)]
    pub(crate) fn retained(&self) -> InventoryRetainedLimits {
        self.retained
    }

    pub fn new(
        per_operation_bytes: u64,
        window: InventoryWindowLimits,
        retained: InventoryRetainedLimits,
    ) -> Result<Self, String> {
        if per_operation_bytes == 0 {
            return Err("inventory per-operation byte limit must be non-zero".into());
        }
        if per_operation_bytes > window.io_bytes {
            return Err(format!(
                "inventory per-operation byte limit {per_operation_bytes} exceeds the {}-byte window",
                window.io_bytes
            ));
        }
        Ok(Self {
            per_operation_bytes,
            window,
            retained,
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DiscoveryPolicy {
    DetailedLegacy,
    Inventory(InventoryDiscoveryLimits),
}

