    /// Retains one gate refusal (table-cap or pre-parse format)
    /// under its file identity. Bounded like the export facts (the
    /// same entry-limit value, counted separately so facts-map
    /// fullness can never refuse refusal retention); bytes share the
    /// one retained cache-bytes ceiling with every other retained map.
    pub(crate) fn note_table_cap_refusal(&mut self, key: InspectedFileKey, reason: String) -> bool {
        if !self.may_mutate_retained_state() {
            return false;
        }
        let bytes = table_refusal_cache_bytes(&key, &reason);
        let entry_limit = self
            .pass
            .inventory_limits()
            .map(|limits| limits.retained.export_cache_entries)
            .or(Some(CAPTURE_EXPORT_CACHE_ENTRIES));
        let byte_limit = self.retained_byte_limit();
        FileFactRetention {
            retained_cache_bytes: &mut self.retained_cache_bytes,
            #[cfg(test)]
            eviction_scans: &mut self.eviction_scans,
            byte_limit,
            entry_limit,
            carries_file_facts: self.carries_file_facts,
        }
        .retain(
            &mut self.table_cap_refusals,
            TouchedKeys {
                current: &mut self.touched_inspected_files,
                previous: &self.previous_touched_inspected_files,
            },
            key,
            reason,
            bytes,
            |key, value: &String| table_refusal_cache_bytes(key, value),
        )
    }

    pub(crate) fn note_elf_export_facts(
        &mut self,
        key: InspectedFileKey,
        value: ElfExportFacts,
    ) -> bool {
        if !self.may_mutate_retained_state() {
            return false;
        }
        let bytes = export_cache_bytes(&key, &value);
        let entry_limit = self
            .pass
            .inventory_limits()
            .map(|limits| limits.retained.export_cache_entries)
            .or(Some(CAPTURE_EXPORT_CACHE_ENTRIES));
        let byte_limit = self.retained_byte_limit();
        FileFactRetention {
            retained_cache_bytes: &mut self.retained_cache_bytes,
            #[cfg(test)]
            eviction_scans: &mut self.eviction_scans,
            byte_limit,
            entry_limit,
            carries_file_facts: self.carries_file_facts,
        }
        .retain(
            &mut self.elf_export_facts,
            TouchedKeys {
                current: &mut self.touched_inspected_files,
                previous: &self.previous_touched_inspected_files,
            },
            key,
            value,
            bytes,
            export_cache_bytes,
        )
    }

    /// Take every retained file-derived cache, leaving this budget with
    /// none and its byte counter zeroed. The cgroup collector carries
    /// the bundle into the next pass's fresh budget: each entry keeps its
    /// file identity and pin, so unchanged files are reused with no
    /// reads and changed files miss and are read again. This pass's
    /// touched keys travel with the entries.
    pub(crate) fn take_retained_file_facts(&mut self) -> RetainedFileFacts {
        self.previous_touched_inspected_files.clear();
        self.previous_touched_loader_elf_facts.clear();
        RetainedFileFacts {
            inspected_files: std::mem::take(&mut self.inspected_files),
            elf_export_facts: std::mem::take(&mut self.elf_export_facts),
            table_cap_refusals: std::mem::take(&mut self.table_cap_refusals),
            loader_elf_facts: std::mem::take(&mut self.loader_elf_facts),
            decode_cursors: self.pass.take_decode_cursors(),
            retained_cache_bytes: std::mem::replace(&mut self.retained_cache_bytes, 0),
            touched_inspected_files: std::mem::take(&mut self.touched_inspected_files),
            touched_loader_elf_facts: std::mem::take(&mut self.touched_loader_elf_facts),
        }
    }

    /// Install file facts carried from an earlier pass, before this
    /// budget begins its window and scan. The destination must be a fresh
    /// budget, and every installed count and byte total must already fit
    /// its ceilings: reclamation assumes the carried maps were built
    /// under the same limits. A later changed pin simply misses.
    pub(crate) fn with_retained_file_facts(mut self, facts: RetainedFileFacts) -> Self {
        debug_assert!(
            self.inspected_files.is_empty()
                && self.elf_export_facts.is_empty()
                && self.table_cap_refusals.is_empty()
                && self.loader_elf_facts.is_empty()
                && self.retained_cache_bytes == 0
                && self.previous_touched_inspected_files.is_empty()
                && self.previous_touched_loader_elf_facts.is_empty()
                && !self.carries_file_facts,
            "retained file facts install into a fresh budget"
        );
        if let Some(limits) = self.pass.inventory_limits() {
            debug_assert!(
                facts.inspected_files.len() <= limits.retained.inspection_cache_entries,
                "carried inspection entries exceed the destination ceiling"
            );
            debug_assert!(
                facts.elf_export_facts.len() <= limits.retained.export_cache_entries,
                "carried export entries exceed the destination ceiling"
            );
            debug_assert!(
                facts.table_cap_refusals.len() <= limits.retained.export_cache_entries,
                "carried refusals exceed the destination ceiling"
            );
            debug_assert!(
                facts.loader_elf_facts.len() <= limits.retained.export_cache_entries,
                "carried loader entries exceed the destination ceiling"
            );
            debug_assert!(
                facts.retained_cache_bytes <= limits.retained.cache_bytes,
                "carried bytes exceed the destination ceiling"
            );
        }
        debug_assert!(
            facts.decode_cursors.len() <= super::scan_pass::MAX_DECODE_CURSORS,
            "carried decode cursors exceed the shared cursor cap"
        );
        debug_assert_eq!(
            facts.retained_cache_bytes,
            file_fact_bytes(
                &facts.inspected_files,
                &facts.elf_export_facts,
                &facts.table_cap_refusals,
                &facts.loader_elf_facts,
            )
            .saturating_add(decode_cursor_bytes_total(&facts.decode_cursors)),
            "the carried byte counter matches its entries"
        );
        self.touched_inspected_files.clear();
        self.touched_loader_elf_facts.clear();
        self.carries_file_facts = !(facts.inspected_files.is_empty()
            && facts.elf_export_facts.is_empty()
            && facts.table_cap_refusals.is_empty()
            && facts.loader_elf_facts.is_empty());
        self.previous_touched_inspected_files = facts.touched_inspected_files;
        self.previous_touched_loader_elf_facts = facts.touched_loader_elf_facts;
        self.inspected_files = facts.inspected_files;
        self.elf_export_facts = facts.elf_export_facts;
        self.table_cap_refusals = facts.table_cap_refusals;
        self.loader_elf_facts = facts.loader_elf_facts;
        self.retained_cache_bytes = facts.retained_cache_bytes;
        // Installing arms resume even for an empty bundle: the collector
        // that installs is a multi-pass inventory pass, so progress it
        // makes this pass must carry a cursor for the next one.
        // Single-shot captures and engine native scans never install and
        // keep their exact stop wording.
        self.pass.install_decode_cursors(facts.decode_cursors);
        self
    }

