    /// `ESRCH` from the mem open proves only that the leader's mm is
    /// gone (the leader completed `exit_mm`); with a live member the
    /// group can still run user code, so the refusal stays loud.
    #[test]
    fn mem_esrch_on_dead_leader_with_live_member_stays_unavailable() {
        use crate::process::cold_view_tests::ColdLeaderSubject;
        let mut group = ColdLeaderSubject::spawn(1);
        group.leave_leader();
        let pid = group.pid();
        assert!(
            crate::process::process_is_zombie(pid),
            "the leader really exited"
        );
        let worker = group.tids[0];
        assert!(
            std::fs::metadata(format!("/proc/{pid}/task/{worker}")).is_ok(),
            "the member is live"
        );
        let view = ProcessView::open(ProcessViewId(87), pid)
            .expect("a cold view opens through the live survivor");
        assert_eq!(
            view.original_exited(),
            Ok(false),
            "the pin proves the group alive"
        );
        assert!(
            view.retained_pin().pidfd().is_ok(),
            "a pidfd-backed pin, not the fallback"
        );
        assert!(
            !crate::process::whole_group_proven_exited(&view),
            "a live member keeps the group unproven"
        );
        assert!(
            !mem_open_exited_for_view(&view, pid, &std::io::Error::from_raw_os_error(libc::ESRCH)),
            "ESRCH on a dead-leader/live-member group stays loud"
        );
        group.call_three();
    }

    #[cfg(any(target_env = "gnu", target_env = "uclibc"))]
    type TracedPtraceRequest = libc::c_uint;
    #[cfg(not(any(target_env = "gnu", target_env = "uclibc")))]
    type TracedPtraceRequest = libc::c_int;

    fn traced_wait_tid_within(
        tid: libc::pid_t,
        within: std::time::Duration,
        what: &str,
    ) -> libc::c_int {
        let deadline = std::time::Instant::now() + within;
        loop {
            let mut status: libc::c_int = 0;
            // SAFETY: a writable status word; `tid` is our traced task.
            let rc = unsafe { libc::waitpid(tid, &mut status, libc::__WALL | libc::WNOHANG) };
            if rc == tid {
                return status;
            }
            if rc < 0 {
                let error = std::io::Error::last_os_error();
                if error.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                }
                panic!("waitpid({tid}) for {what} failed: {error}");
            }
            assert!(
                std::time::Instant::now() < deadline,
                "no wait status from {tid} for {what} within {within:?}"
            );
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
    }

    fn traced_ptrace_op(request: TracedPtraceRequest, tid: libc::pid_t, data: usize) {
        // SAFETY: `tid` is stopped under our ptrace; `data` is valid
        // for the request (a flag word or a writable `c_ulong`).
        let rc = unsafe { libc::ptrace(request, tid, 0usize, data) };
        assert!(
            rc >= 0,
            "ptrace({request}, {tid}) failed: {}",
            std::io::Error::last_os_error()
        );
    }

    fn traced_wait_exit_event(tid: libc::pid_t, event: libc::c_int, what: &str) {
        let status = traced_wait_tid_within(tid, std::time::Duration::from_secs(10), what);
        assert!(
            libc::WIFSTOPPED(status)
                && libc::WSTOPSIG(status) == libc::SIGTRAP
                && (status >> 16) & 0xffff == event,
            "{what}: unexpected wait status {status:#x} from {tid}"
        );
    }

    const TRACED_MT_EXIT_SOURCE: &str = r#"
#define _GNU_SOURCE
#include <pthread.h>
#include <stdlib.h>
#include <sys/syscall.h>
#include <unistd.h>

static pthread_mutex_t gate = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t changed = PTHREAD_COND_INITIALIZER;
static unsigned ready = 0;

static void *worker(void *arg) {
    int fd = *(int *)arg;
    if (pthread_mutex_lock(&gate)) _exit(10);
    ready++;
    if (pthread_cond_broadcast(&changed)) _exit(11);
    if (pthread_mutex_unlock(&gate)) _exit(12);
    char byte;
    if (read(fd, &byte, 1) != 1) _exit(13);
    syscall(SYS_exit, 0);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc != 3) return 2;
    static int fds[2];
    fds[0] = atoi(argv[1]);
    fds[1] = atoi(argv[2]);
    pthread_t t0, t1;
    if (pthread_create(&t0, NULL, worker, &fds[0])) return 3;
    if (pthread_create(&t1, NULL, worker, &fds[1])) return 4;
    if (pthread_mutex_lock(&gate)) return 5;
    while (ready != 2)
        if (pthread_cond_wait(&changed, &gate)) return 6;
    if (pthread_mutex_unlock(&gate)) return 7;
    if (write(STDOUT_FILENO, "R", 1) != 1) return 8;
    pthread_exit(NULL);
}
"#;

    struct TracedFinalExitGuard {
        leader: libc::pid_t,
        tids: Vec<libc::pid_t>,
        child: Option<std::process::Child>,
        _temp: tempfile::TempDir,
    }
    impl Drop for TracedFinalExitGuard {
        fn drop(&mut self) {
            let Some(mut child) = self.child.take() else {
                return;
            };
            // SAFETY: signalling our own child's thread group.
            unsafe { libc::kill(self.leader, libc::SIGKILL) };
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
            let leader = self.leader;
            for tid in self.tids.drain(..).chain(std::iter::once(leader)) {
                loop {
                    let mut status: libc::c_int = 0;
                    // SAFETY: a writable status word; reaping our tracee.
                    let rc =
                        unsafe { libc::waitpid(tid, &mut status, libc::__WALL | libc::WNOHANG) };
                    let exited = libc::WIFEXITED(status) || libc::WIFSIGNALED(status);
                    if rc < 0 || (rc == tid && exited) || std::time::Instant::now() >= deadline {
                        break;
                    }
                    if rc == tid {
                        // SAFETY: `tid` is stopped under our ptrace.
                        unsafe { libc::ptrace(libc::PTRACE_CONT, tid, 0usize, 0usize) };
                        continue;
                    }
                    std::thread::sleep(std::time::Duration::from_millis(1));
                }
            }
            while std::time::Instant::now() < deadline && matches!(child.try_wait(), Ok(None)) {
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
        }
    }

    /// Hold a traced 2-worker group in proven final exit: the leader is a
    /// zombie, one worker is reaped, and the last worker is an unreaped
    /// traced zombie, so the pidfd stays unready while the walk proves the
    /// end. The returned view still reads same-generation, so a scan
    /// reaches the mem decision instead of the generation-change refusal.
    /// Every wait is bounded; the guard reaps on drop.
    fn hold_traced_group_in_proven_final_exit(
        view_id: ProcessViewId,
    ) -> (ProcessView, u32, TracedFinalExitGuard) {
        use std::io::{Read as _, Write as _};
        use std::os::unix::io::AsRawFd as _;
        use std::os::unix::process::CommandExt as _;
        use std::time::{Duration, Instant};

        let dir = tempfile::tempdir().unwrap();
        let source = dir.path().join("mt-exit.c");
        let executable = dir.path().join("mt-exit");
        std::fs::write(&source, TRACED_MT_EXIT_SOURCE).unwrap();
        let built = std::process::Command::new("cc")
            .args(["-std=c11", "-Wall", "-Wextra", "-Werror", "-pthread", "-O1"])
            .arg(&source)
            .arg("-o")
            .arg(&executable)
            .status()
            .unwrap();
        assert!(built.success(), "fixture build failed: {built}");

        let (r0, mut w0) = std::io::pipe().unwrap();
        let (r1, mut w1) = std::io::pipe().unwrap();
        let (r0_raw, r1_raw) = (r0.as_raw_fd(), r1.as_raw_fd());
        let mut command = std::process::Command::new(&executable);
        command
            .args([r0_raw.to_string(), r1_raw.to_string()])
            .stdout(std::process::Stdio::piped());
        // SAFETY: only async-signal-safe prctl/fcntl/ptrace before exec.
        unsafe {
            command.pre_exec(move || {
                if libc::prctl(libc::PR_SET_PDEATHSIG, libc::SIGKILL as libc::c_ulong) != 0
                    || libc::fcntl(r0_raw, libc::F_SETFD, 0) != 0
                    || libc::fcntl(r1_raw, libc::F_SETFD, 0) != 0
                    || libc::ptrace(libc::PTRACE_TRACEME, 0, 0usize, 0usize) < 0
                {
                    return Err(std::io::Error::last_os_error());
                }
                Ok(())
            });
        }
        let mut child = command.spawn().unwrap();
        drop((r0, r1));
        let leader = child.id() as libc::pid_t;
        let mut stdout = child.stdout.take().unwrap();
        let mut guard = TracedFinalExitGuard {
            leader,
            tids: Vec::new(),
            child: Some(child),
            _temp: dir,
        };

        let exec_stop = traced_wait_tid_within(leader, Duration::from_secs(10), "the exec stop");
        assert!(
            libc::WIFSTOPPED(exec_stop) && libc::WSTOPSIG(exec_stop) == libc::SIGTRAP,
            "exec stop {exec_stop:#x}"
        );
        traced_ptrace_op(
            libc::PTRACE_SETOPTIONS,
            leader,
            (libc::PTRACE_O_TRACECLONE | libc::PTRACE_O_TRACEEXIT | libc::PTRACE_O_EXITKILL)
                as usize,
        );
        traced_ptrace_op(libc::PTRACE_CONT, leader, 0);
        for _ in 0..2 {
            traced_wait_exit_event(leader, libc::PTRACE_EVENT_CLONE, "a worker clone");
            let mut new_tid: libc::c_ulong = 0;
            traced_ptrace_op(
                libc::PTRACE_GETEVENTMSG,
                leader,
                std::ptr::from_mut(&mut new_tid) as usize,
            );
            let tid = new_tid as libc::pid_t;
            guard.tids.push(tid);
            let stop =
                traced_wait_tid_within(tid, Duration::from_secs(10), "the worker start stop");
            assert!(
                libc::WIFSTOPPED(stop) && libc::WSTOPSIG(stop) == libc::SIGSTOP,
                "worker start {stop:#x}"
            );
            traced_ptrace_op(libc::PTRACE_CONT, tid, 0);
            traced_ptrace_op(libc::PTRACE_CONT, leader, 0);
        }
        let (tid0, tid1) = (guard.tids[0], guard.tids[1]);

        let mut poll = libc::pollfd {
            fd: stdout.as_raw_fd(),
            events: libc::POLLIN,
            revents: 0,
        };
        // SAFETY: one valid pollfd.
        assert_eq!(unsafe { libc::poll(&mut poll, 1, 10_000) }, 1, "ready byte");
        let mut ready = [0u8; 1];
        stdout.read_exact(&mut ready).unwrap();
        assert_eq!(ready, *b"R");

        // The scan view opens while the group is live; its pin retains
        // the pidfd and the leader birth across the exits below.
        let pid = leader as u32;
        let view = ProcessView::open(view_id, pid).expect("a view opens on the live traced group");
        assert!(view.retained_pin().pidfd().is_ok(), "a pidfd-backed pin");

        traced_wait_exit_event(leader, libc::PTRACE_EVENT_EXIT, "the leader exit");
        traced_ptrace_op(libc::PTRACE_CONT, leader, 0);
        let deadline = Instant::now() + Duration::from_secs(10);
        while !crate::process::process_is_zombie(pid) {
            assert!(
                Instant::now() < deadline,
                "the leader never became a zombie"
            );
            std::thread::sleep(Duration::from_millis(1));
        }

        w0.write_all(&[1]).unwrap();
        traced_wait_exit_event(tid0, libc::PTRACE_EVENT_EXIT, "worker 0 exit");
        traced_ptrace_op(libc::PTRACE_CONT, tid0, 0);
        let status0 = traced_wait_tid_within(tid0, Duration::from_secs(10), "worker 0 reap");
        assert!(libc::WIFEXITED(status0), "worker 0 {status0:#x}");
        guard.tids.retain(|tid| *tid != tid0);

        // The last worker runs on to an unreaped traced zombie: past
        // user mode, still on the thread list, pidfd still unready.
        w1.write_all(&[1]).unwrap();
        traced_wait_exit_event(tid1, libc::PTRACE_EVENT_EXIT, "worker 1 exit");
        traced_ptrace_op(libc::PTRACE_CONT, tid1, 0);
        let stat = format!("/proc/{pid}/task/{tid1}/stat");
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            let text = std::fs::read_to_string(&stat).unwrap_or_default();
            let state = text
                .rfind(')')
                .and_then(|end| text[end + 1..].split_whitespace().next())
                .unwrap_or("");
            if state == "Z" {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "worker 1 never became a zombie: {text:?}"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            view.original_exited(),
            Ok(false),
            "an unreaped worker keeps the pidfd unready"
        );
        assert!(
            crate::process::whole_group_proven_exited(&view),
            "the /proc walk proves the final exit before the pidfd is ready"
        );
        assert!(
            view.still_the_same(),
            "the proven final exit still reads same-generation"
        );
        (view, pid, guard)
    }

    /// Scan-level positive for the final-exit arm: a traced group with
    /// every thread past user mode (a zombie leader, the last worker
    /// an unreaped traced zombie) keeps its pidfd unready, yet the
    /// /proc walk proves the end — so a zero-byte read names the exit
    /// and errno'd mem refusals take the silent path. Every wait is
    /// bounded; the drop guard reaps the traced group on any failure.
    #[test]
    fn final_exit_without_pidfd_ready_renames_zero_reads_and_silences_mem_refusals() {
        use std::io::{Read as _, Write as _};
        use std::os::unix::io::AsRawFd as _;
        use std::os::unix::process::CommandExt as _;
        use std::time::{Duration, Instant};

        fn wait_tid_within(tid: libc::pid_t, within: Duration, what: &str) -> libc::c_int {
            let deadline = Instant::now() + within;
            loop {
                let mut status: libc::c_int = 0;
                // SAFETY: a writable status word; `tid` is our traced task.
                let rc = unsafe { libc::waitpid(tid, &mut status, libc::__WALL | libc::WNOHANG) };
                if rc == tid {
                    return status;
                }
                if rc < 0 {
                    let error = std::io::Error::last_os_error();
                    if error.kind() == std::io::ErrorKind::Interrupted {
                        continue;
                    }
                    panic!("waitpid({tid}) for {what} failed: {error}");
                }
                assert!(
                    Instant::now() < deadline,
                    "no wait status from {tid} for {what} within {within:?}"
                );
                std::thread::sleep(Duration::from_millis(1));
            }
        }

        #[cfg(any(target_env = "gnu", target_env = "uclibc"))]
        type PtraceRequest = libc::c_uint;
        #[cfg(not(any(target_env = "gnu", target_env = "uclibc")))]
        type PtraceRequest = libc::c_int;

        fn ptrace_op(request: PtraceRequest, tid: libc::pid_t, data: usize) {
            // SAFETY: `tid` is stopped under our ptrace; `data` is valid
            // for the request (a flag word or a writable `c_ulong`).
            let rc = unsafe { libc::ptrace(request, tid, 0usize, data) };
            assert!(
                rc >= 0,
                "ptrace({request}, {tid}) failed: {}",
                std::io::Error::last_os_error()
            );
        }

        fn wait_exit_event(tid: libc::pid_t, event: libc::c_int, what: &str) {
            let status = wait_tid_within(tid, Duration::from_secs(10), what);
            assert!(
                libc::WIFSTOPPED(status)
                    && libc::WSTOPSIG(status) == libc::SIGTRAP
                    && (status >> 16) & 0xffff == event,
                "{what}: unexpected wait status {status:#x} from {tid}"
            );
        }

        struct TracedGroup {
            leader: libc::pid_t,
            tids: Vec<libc::pid_t>,
            child: Option<std::process::Child>,
        }
        impl Drop for TracedGroup {
            fn drop(&mut self) {
                let Some(mut child) = self.child.take() else {
                    return;
                };
                // SAFETY: signalling our own child's thread group.
                unsafe { libc::kill(self.leader, libc::SIGKILL) };
                let deadline = Instant::now() + Duration::from_secs(10);
                let leader = self.leader;
                for tid in self.tids.drain(..).chain(std::iter::once(leader)) {
                    loop {
                        let mut status: libc::c_int = 0;
                        // SAFETY: a writable status word; reaping our tracee.
                        let rc = unsafe {
                            libc::waitpid(tid, &mut status, libc::__WALL | libc::WNOHANG)
                        };
                        let exited = libc::WIFEXITED(status) || libc::WIFSIGNALED(status);
                        if rc < 0 || (rc == tid && exited) || Instant::now() >= deadline {
                            break;
                        }
                        if rc == tid {
                            // SAFETY: `tid` is stopped under our ptrace.
                            unsafe { libc::ptrace(libc::PTRACE_CONT, tid, 0usize, 0usize) };
                            continue;
                        }
                        std::thread::sleep(Duration::from_millis(1));
                    }
                }
                while Instant::now() < deadline && matches!(child.try_wait(), Ok(None)) {
                    std::thread::sleep(Duration::from_millis(1));
                }
            }
        }

        // One traced two-worker shape for the module: the shared
        // helper builds this same fixture.
        const MT_EXIT_SOURCE: &str = TRACED_MT_EXIT_SOURCE;

        let dir = tempfile::tempdir().unwrap();
        let source = dir.path().join("mt-exit.c");
        let executable = dir.path().join("mt-exit");
        std::fs::write(&source, MT_EXIT_SOURCE).unwrap();
        let built = std::process::Command::new("cc")
            .args(["-std=c11", "-Wall", "-Wextra", "-Werror", "-pthread", "-O1"])
            .arg(&source)
            .arg("-o")
            .arg(&executable)
            .status()
            .unwrap();
        assert!(built.success(), "fixture build failed: {built}");

        let (r0, mut w0) = std::io::pipe().unwrap();
        let (r1, mut w1) = std::io::pipe().unwrap();
        let (r0_raw, r1_raw) = (r0.as_raw_fd(), r1.as_raw_fd());
        let mut command = std::process::Command::new(&executable);
        command
            .args([r0_raw.to_string(), r1_raw.to_string()])
            .stdout(std::process::Stdio::piped());
        // SAFETY: only async-signal-safe prctl/fcntl/ptrace before exec.
        unsafe {
            command.pre_exec(move || {
                if libc::prctl(libc::PR_SET_PDEATHSIG, libc::SIGKILL as libc::c_ulong) != 0
                    || libc::fcntl(r0_raw, libc::F_SETFD, 0) != 0
                    || libc::fcntl(r1_raw, libc::F_SETFD, 0) != 0
                    || libc::ptrace(libc::PTRACE_TRACEME, 0, 0usize, 0usize) < 0
                {
                    return Err(std::io::Error::last_os_error());
                }
                Ok(())
            });
        }
        let mut child = command.spawn().unwrap();
        drop((r0, r1));
        let leader = child.id() as libc::pid_t;
        let mut stdout = child.stdout.take().unwrap();
        let mut group = TracedGroup {
            leader,
            tids: Vec::new(),
            child: Some(child),
        };

        let exec_stop = wait_tid_within(leader, Duration::from_secs(10), "the exec stop");
        assert!(
            libc::WIFSTOPPED(exec_stop) && libc::WSTOPSIG(exec_stop) == libc::SIGTRAP,
            "exec stop {exec_stop:#x}"
        );
        ptrace_op(
            libc::PTRACE_SETOPTIONS,
            leader,
            (libc::PTRACE_O_TRACECLONE | libc::PTRACE_O_TRACEEXIT | libc::PTRACE_O_EXITKILL)
                as usize,
        );
        ptrace_op(libc::PTRACE_CONT, leader, 0);
        for _ in 0..2 {
            wait_exit_event(leader, libc::PTRACE_EVENT_CLONE, "a worker clone");
            let mut new_tid: libc::c_ulong = 0;
            ptrace_op(
                libc::PTRACE_GETEVENTMSG,
                leader,
                std::ptr::from_mut(&mut new_tid) as usize,
            );
            let tid = new_tid as libc::pid_t;
            group.tids.push(tid);
            let stop = wait_tid_within(tid, Duration::from_secs(10), "the worker start stop");
            assert!(
                libc::WIFSTOPPED(stop) && libc::WSTOPSIG(stop) == libc::SIGSTOP,
                "worker start {stop:#x}"
            );
            ptrace_op(libc::PTRACE_CONT, tid, 0);
            ptrace_op(libc::PTRACE_CONT, leader, 0);
        }
        let (tid0, tid1) = (group.tids[0], group.tids[1]);

        let mut poll = libc::pollfd {
            fd: stdout.as_raw_fd(),
            events: libc::POLLIN,
            revents: 0,
        };
        // SAFETY: one valid pollfd.
        assert_eq!(unsafe { libc::poll(&mut poll, 1, 10_000) }, 1, "ready byte");
        let mut ready = [0u8; 1];
        stdout.read_exact(&mut ready).unwrap();
        assert_eq!(ready, *b"R");

        // The scan view opens while the group is live; its pin retains
        // the pidfd and the leader birth across the exits below.
        let pid = leader as u32;
        let view = ProcessView::open(ProcessViewId(88), pid)
            .expect("a view opens on the live traced group");
        assert!(view.retained_pin().pidfd().is_ok(), "a pidfd-backed pin");

        wait_exit_event(leader, libc::PTRACE_EVENT_EXIT, "the leader exit");
        ptrace_op(libc::PTRACE_CONT, leader, 0);
        let deadline = Instant::now() + Duration::from_secs(10);
        while !crate::process::process_is_zombie(pid) {
            assert!(
                Instant::now() < deadline,
                "the leader never became a zombie"
            );
            std::thread::sleep(Duration::from_millis(1));
        }

        w0.write_all(&[1]).unwrap();
        wait_exit_event(tid0, libc::PTRACE_EVENT_EXIT, "worker 0 exit");
        ptrace_op(libc::PTRACE_CONT, tid0, 0);
        let status0 = wait_tid_within(tid0, Duration::from_secs(10), "worker 0 reap");
        assert!(libc::WIFEXITED(status0), "worker 0 {status0:#x}");
        group.tids.retain(|tid| *tid != tid0);

        // The last worker runs on to an unreaped traced zombie: past
        // user mode, still on the thread list, pidfd still unready.
        w1.write_all(&[1]).unwrap();
        wait_exit_event(tid1, libc::PTRACE_EVENT_EXIT, "worker 1 exit");
        ptrace_op(libc::PTRACE_CONT, tid1, 0);
        let stat = format!("/proc/{pid}/task/{tid1}/stat");
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            let text = std::fs::read_to_string(&stat).unwrap_or_default();
            let state = text
                .rfind(')')
                .and_then(|end| text[end + 1..].split_whitespace().next())
                .unwrap_or("");
            if state == "Z" {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "worker 1 never became a zombie: {text:?}"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(
            view.original_exited(),
            Ok(false),
            "an unreaped worker keeps the pidfd unready"
        );
        assert!(
            crate::process::whole_group_proven_exited(&view),
            "the /proc walk proves the final exit before the pidfd is ready"
        );
        assert!(
            zero_read_names_exit(&view),
            "a proven final exit names the exit"
        );
        for (name, errno) in [
            ("EACCES", libc::EACCES),
            ("ENOENT", libc::ENOENT),
            ("ESRCH", libc::ESRCH),
        ] {
            assert!(
                mem_open_exited_for_view(&view, pid, &std::io::Error::from_raw_os_error(errno)),
                "{name} in proven final exit takes the exited path"
            );
        }

        let status1 = wait_tid_within(tid1, Duration::from_secs(10), "worker 1 reap");
        assert!(libc::WIFEXITED(status1), "worker 1 {status1:#x}");
        group.tids.clear();
        let mut child = group.child.take().unwrap();
        let deadline = Instant::now() + Duration::from_secs(10);
        let status = loop {
            if let Some(status) = child.try_wait().unwrap() {
                break status;
            }
            assert!(Instant::now() < deadline, "the leader was never reapable");
            std::thread::sleep(Duration::from_millis(1));
        };
        assert!(status.success(), "{status}");
        assert_eq!(view.original_exited(), Ok(true));
    }

    /// The whole group can still exit between the mem open and the
    /// post-check: that race takes the generation-change refusal,
    /// never the silent exited path and never a global latch.
    #[test]
    fn mem_open_generation_change_takes_refused_not_silent() {
        use crate::fixture_guard::DieWithParent as _;
        use std::process::Command;
        let child = Command::new("sleep")
            .arg("30")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .die_with_parent()
            .spawn()
            .expect("a sleeper spawns");
        let pid = child.id();
        let view =
            ProcessView::open(ProcessViewId(82), pid).expect("a view opens on the live child");
        let maps = b"00400000-00401000 r--p 00000000 08:01 1234 /bin/true\n".to_vec();
        let mut io = MemKillFixture {
            maps,
            child: Some(child),
        };
        let result = scan_process_view_with_io(
            &ScanRequest {
                pid,
                hints: &[],
                hooks: &HookRegistry::builtin(),
            },
            &view,
            &mut CaptureWorkBudget::default(),
            &mut io,
        );
        let outcome = result.expect("a mid-open exit refuses, never the silent Err path");
        assert!(
            outcome
                .skipped()
                .iter()
                .any(|skip| skip.reason.contains(SCAN_GENERATION_CHANGED_REASON)),
            "a mid-open exit names the generation change: {:?}",
            outcome.skipped()
        );
        assert!(
            outcome.modules().is_empty(),
            "a refused scan decodes nothing: {:?}",
            outcome.modules()
        );
    }

    /// `mem_open_exited` decides from the strongest proof available: the
    /// open errno first, then a fresh pid read. `u32::MAX` never names a
    /// process, so it stands in for a dead pid deterministically.
    #[test]
    fn mem_open_exited_proves_exit_from_errno_or_fresh_pid_read() {
        use std::io::Error;
        let live = std::process::id();
        let dead = u32::MAX;
        // Errno proof needs no pid read: `ESRCH`/`ENOENT` mean gone even
        // for a pid that is alive now (reuse after the open failed).
        assert!(mem_open_exited(
            live,
            &Error::from_raw_os_error(libc::ESRCH)
        ));
        assert!(mem_open_exited(
            live,
            &Error::from_raw_os_error(libc::ENOENT)
        ));
        // Wrapped validation failures (cold-filesystem exit churn) carry
        // no errno: the fresh pid read decides.
        let churn = "cold process task census contains an unproven or exiting member";
        assert!(mem_open_exited(dead, &Error::other(churn)));
        assert!(!mem_open_exited(live, &Error::other(churn)));
        // Ordinary refusals on a live pid stay loud, and prove exit on a
        // dead one (the refusal fired microseconds before the exit).
        assert!(!mem_open_exited(
            live,
            &Error::from_raw_os_error(libc::EACCES)
        ));
        assert!(!mem_open_exited(live, &Error::from_raw_os_error(libc::EIO)));
        assert!(mem_open_exited(
            dead,
            &Error::from_raw_os_error(libc::EACCES)
        ));
        assert!(mem_open_exited(dead, &Error::from_raw_os_error(libc::EIO)));
    }

    #[test]
    fn only_walkable_version_words_become_candidates() {
        // 67 / 68 / 92 / 104 slots + the version word, in bytes. Future
        // minors walk their known prefix (owner-approved 2026-09-27), so
        // [2,41] and [3,9] size exactly like the layouts they prefix.
        for (word, expected) in [
            (0x0002u64, Some(((2u8, 0u8), 8 + 67 * 8))),
            (0x2802, Some(((2, 40), 8 + 68 * 8))),
            (0x2902, Some(((2, 41), 8 + 68 * 8))),
            (0x0003, Some(((3, 0), 8 + 92 * 8))),
            (0x0203, Some(((3, 2), 8 + 104 * 8))),
            (0x0903, Some(((3, 9), 8 + 104 * 8))),
        ] {
            let (version, spans, _) = spans_for(word).expect("walkable");
            assert_eq!(
                Some((version, span_bytes(LinuxLayout::Lp64, spans).unwrap())),
                expected
            );
        }
        // Padding bytes set, unknown major, all-zero word.
        for word in [0x1_2802u64, 0x0304, 0x0004, 0] {
            assert!(spans_for(word).is_none(), "{word:#x} must not be a table");
        }
    }

    /// Package F (E08/E15/E21): the explicit known ABI bounds. Only
    /// these version words walk a full table; any other minor of a known
    /// major walks the known prefix with an explicit marker (owner-approved
    /// 2026-09-27: the scan follows the helper's versioning rule, so 3.x
    /// past 3.2 prefixes the 104-slot 3.2 layout like the manifest path);
    /// only a new major refuses. The exhaustive low-word sweep proves the
    /// full set is exactly this — bounded total work, no panic on any input.
    #[test]
    fn f_package_known_abi_bounds_walk_full_only_for_supported_shapes() {
        for (word, version, slots) in [
            (0x2802u64, (2u8, 40u8), 68usize),
            (0x0003, (3, 0), 92),
            (0x0103, (3, 1), 92),
            (0x0203, (3, 2), 104),
        ] {
            let (decoded, spans, walk) = spans_for(word).expect("supported shape walks");
            assert_eq!((decoded, walk), (version, "full"));
            assert_eq!(
                spans.iter().map(|span| span.fields().len()).sum::<usize>(),
                slots,
                "{version:?} walks its exact slot count"
            );
        }
        let (_, _, walk) = spans_for(0x2702).expect("a 2.39 prefix decodes");
        assert_eq!(
            walk, "known_prefix",
            "non-listed minors stay explicitly bounded"
        );
        for (word, version, slots) in [
            (0x2902u64, (2u8, 41u8), 68usize),
            (0x0303, (3, 3), 104),
            (0x0903, (3, 9), 104),
        ] {
            let (decoded, spans, walk) = spans_for(word).expect("future minor walks");
            assert_eq!((decoded, walk), (version, "known_prefix"));
            assert_eq!(
                spans.iter().map(|span| span.fields().len()).sum::<usize>(),
                slots,
                "{version:?} walks its known-prefix slot count"
            );
        }
        for word in [0x0004u64, 0x0204, 0x0000, 0xffff, 0x1_0000, u64::MAX] {
            assert!(spans_for(word).is_none(), "{word:#x} must not be a table");
        }
        let mut full = Vec::new();
        for word in 0..=0xffffu64 {
            if let Some(((major, minor), _, walk)) = spans_for(word)
                && walk == "full"
            {
                full.push((major, minor));
            }
        }
        full.sort();
        full.dedup();
        assert_eq!(
            full,
            vec![
                (2, 0),
                (2, 1),
                (2, 10),
                (2, 11),
                (2, 20),
                (2, 30),
                (2, 40),
                (3, 0),
                (3, 1),
                (3, 2),
            ],
            "the full-walk set is exactly the known ABI bounds"
        );
    }

    /// One group from maps text: the group's entries in map order, as
    /// the scan loop sees them.
    fn group_of(text: &[u8], inode: u64) -> Vec<MapEntry> {
        let maps = parse_maps(text).unwrap();
        let groups = candidate_groups(&maps);
        assert_eq!(groups.len(), 1);
        groups
            .iter()
            .find(|(key, _)| key.inode == inode)
            .unwrap_or_else(|| panic!("missing group for inode {inode}"))
            .1
            .iter()
            .map(|entry| (*entry).clone())
            .collect()
    }

    fn group_refs(entries: &[MapEntry]) -> Vec<&MapEntry> {
        entries.iter().collect()
    }

    #[test]
    fn double_load_detector_fires_only_on_duplicate_executable_coverage() {
        // One load: each segment once — no duplicate.
        let single = group_of(
            b"1000-2000 r--p 00000000 08:01 7 /lib/provider.so\n\
              2000-3000 r-xp 00001000 08:01 7 /lib/provider.so\n\
              3000-4000 r--p 00002000 08:01 7 /lib/provider.so\n\
              4000-5000 rw-p 00003000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert!(!duplicate_exec_coverage(&group_refs(&single)));
        // A dlmopen double-load: the r-x file range mapped twice at
        // different addresses (shape observed from a real double-load).
        let double = group_of(
            b"a000-a100 r--p 00000000 08:01 7 /lib/provider.so\n\
              a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              b000-b100 r--p 00000000 08:01 7 /lib/provider.so\n\
              b100-b200 r-xp 00001000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert!(duplicate_exec_coverage(&group_refs(&double)));
        // Disjoint executable ranges (two segments, one load each).
        let disjoint = group_of(
            b"a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              b100-b200 r-xp 00002000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert!(!duplicate_exec_coverage(&group_refs(&disjoint)));
        // Data-only duplicates: no call surface, no evidence.
        let data = group_of(
            b"a000-a100 r--p 00000000 08:01 7 /lib/provider.so\n\
              a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              b000-b100 r--p 00000000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert!(!duplicate_exec_coverage(&group_refs(&data)));
        // Partial executable overlap still shares offsets.
        let overlap = group_of(
            b"a100-a300 r-xp 00001000 08:01 7 /lib/provider.so\n\
              b100-b300 r-xp 00001100 08:01 7 /lib/provider.so\n",
            7,
        );
        assert!(duplicate_exec_coverage(&group_refs(&overlap)));
        // The same mapping listed twice is the one mapping, never a
        // duplicate (defensive: real maps never repeat a line).
        let repeated = group_of(
            b"a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert!(!duplicate_exec_coverage(&group_refs(&repeated)));
    }

    #[test]
    fn same_file_load_count_counts_distinct_executable_instances() {
        // One load: each offset mapped once.
        let single = group_of(
            b"1000-2000 r--p 00000000 08:01 7 /lib/provider.so\n\
              2000-3000 r-xp 00001000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert_eq!(duplicate_exec_load_count(&group_refs(&single)), 1);
        // A dlmopen double-load: the r-x file range mapped twice at
        // different addresses.
        let double = group_of(
            b"a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              b100-b200 r-xp 00001000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert_eq!(duplicate_exec_load_count(&group_refs(&double)), 2);
        // A third same-file load: the same r-x file range at a third
        // address. The boolean detector stays true here too, so only
        // the count sees the new instance.
        let triple = group_of(
            b"a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              b100-b200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              c100-c200 r-xp 00001000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert_eq!(duplicate_exec_load_count(&group_refs(&triple)), 3);
        assert!(duplicate_exec_coverage(&group_refs(&triple)));
        // Disjoint executable ranges: two segments, one load each.
        let disjoint = group_of(
            b"a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              b100-b200 r-xp 00002000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert_eq!(duplicate_exec_load_count(&group_refs(&disjoint)), 1);
        // Data-only duplicates: no call surface, still one load.
        let data = group_of(
            b"a000-a100 r--p 00000000 08:01 7 /lib/provider.so\n\
              a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              b000-b100 r--p 00000000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert_eq!(duplicate_exec_load_count(&group_refs(&data)), 1);
        // Partial executable overlap still shares offsets: two loads.
        let overlap = group_of(
            b"a100-a300 r-xp 00001000 08:01 7 /lib/provider.so\n\
              b100-b300 r-xp 00001100 08:01 7 /lib/provider.so\n",
            7,
        );
        assert_eq!(duplicate_exec_load_count(&group_refs(&overlap)), 2);
        // The same mapping listed twice is the one mapping.
        let repeated = group_of(
            b"a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n\
              a100-a200 r-xp 00001000 08:01 7 /lib/provider.so\n",
            7,
        );
        assert_eq!(duplicate_exec_load_count(&group_refs(&repeated)), 1);
    }

    #[test]
    fn ilp32_tables_use_four_byte_words_and_ignore_adjacent_poison() {
        let maps = parse_maps(b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n").unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        for (version, fields) in [(0x0002u32, 67), (0x2802, 68), (0x0003, 92), (0x0203, 104)] {
            let mut snapshot = vec![0xa5; 4 + fields * 4 + 3];
            snapshot[..4].copy_from_slice(&version.to_le_bytes());
            for ordinal in 0..fields {
                let offset = 4 + ordinal * 4;
                snapshot[offset..offset + 4].copy_from_slice(&0x1500u32.to_le_bytes());
            }
            assert_eq!(
                exact_table_bytes(&snapshot[..4], LinuxLayout::Ilp32),
                Some(4 + fields * 4)
            );
            let (tables, skipped) = detect_tables_for_layout(
                LinuxLayout::Ilp32,
                &snapshot,
                0x7000,
                &map_index,
                &mut CaptureWorkBudget::default(),
            );
            assert!(skipped.is_empty(), "{version:#x}: {skipped:?}");
            assert_eq!(tables.len(), 1, "{version:#x}");
            assert_eq!(tables[0].entries.len(), fields, "{version:#x}");

            snapshot.truncate(4 + fields * 4 - 1);
            let truncated = detect_tables_for_layout(
                LinuxLayout::Ilp32,
                &snapshot,
                0x7000,
                &map_index,
                &mut CaptureWorkBudget::default(),
            )
            .0;
            if fields > 68 {
                assert_eq!(truncated.len(), 1, "the legacy prefix is complete");
                assert_eq!(truncated[0].walk, "known_prefix");
                assert_eq!(truncated[0].entries.len(), 68);
                snapshot.truncate(4 + 68 * 4 - 1);
            } else {
                assert!(truncated.is_empty(), "an incomplete legacy layout refuses");
            }
            assert!(
                detect_tables_for_layout(
                    LinuxLayout::Ilp32,
                    &snapshot,
                    0x7000,
                    &map_index,
                    &mut CaptureWorkBudget::default(),
                )
                .0
                .is_empty(),
                "a truncated final legacy target word is never decoded"
            );
        }
    }

    #[test]
    fn a_shorter_match_inside_a_longer_one_is_dropped() {
        let maps = parse_maps(b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n").unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        // A 3.2 table (104 slots) whose 68th..104th slots also start with a word that
        // reads as a valid 2.40 header would otherwise be reported twice.
        let mut snapshot = vec![0u8; 8 + 104 * 8];
        snapshot[..8].copy_from_slice(&0x0203u64.to_ne_bytes());
        for slot in 0..104 {
            let at = 8 + slot * 8;
            snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_ne_bytes());
        }
        let inner = 8 + 30 * 8;
        snapshot[inner..inner + 8].copy_from_slice(&0x2802u64.to_ne_bytes());
        let (tables, truncated) = detect_tables(
            &snapshot,
            0x7000,
            &map_index,
            &mut CaptureWorkBudget::default(),
        );
        assert_eq!(tables.len(), 1);
        assert_eq!(tables[0].version, (3, 2));
        assert_eq!(tables[0].address, 0x7000);
        // The 2.40 header word is a NULL-looking non-pointer, so it is recorded as an
        // entry of the 3.2 table pointing into the provider's executable mapping.
        assert_eq!(tables[0].entries.len(), 104);
        assert!(truncated.is_empty(), "{truncated:?}");
    }

    #[test]
    fn a_header_whose_body_runs_past_the_snapshot_is_not_a_candidate() {
        let maps = parse_maps(b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n").unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        // A 2.40 header with only 10 of its 68 slots inside the snapshot: exactly the
        // shape of a table whose .bss has spilled into an anonymous mapping.
        let mut snapshot = vec![0u8; 8 + 10 * 8];
        snapshot[..8].copy_from_slice(&0x2802u64.to_ne_bytes());
        for slot in 0..10 {
            let at = 8 + slot * 8;
            snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_ne_bytes());
        }
        let (tables, truncated) = detect_tables(
            &snapshot,
            0x7000,
            &map_index,
            &mut CaptureWorkBudget::default(),
        );
        assert!(tables.is_empty(), "an incomplete table is never decoded");
        assert!(truncated.is_empty(), "a version word alone is not evidence");
        // Ordinary data must not generate this diagnostic.
        assert!(
            detect_tables(
                &vec![0u8; 4096],
                0x7000,
                &map_index,
                &mut CaptureWorkBudget::default()
            )
            .1
            .is_empty()
        );
    }

    /// Fixture maps for the mislabelled-table tests: an executable
    /// provider mapping for valid slots, a file-backed data mapping for
    /// unrelated tail words, and a readable mapping holding the snapshot.
    fn mislabelled_fixture_maps() -> Vec<MapEntry> {
        parse_maps(
            b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n\
              4000-5000 rw-p 00001000 08:01 7 /lib/provider.so\n\
              7000-9000 r--p 00002000 08:01 7 /lib/provider.so\n",
        )
        .unwrap()
    }

    /// A table image with `head` valid executable slots followed by `tail`
    /// file-backed data words under the given version word.
    fn mislabelled_snapshot(word: u64, head: usize, tail: usize) -> Vec<u8> {
        let mut snapshot = vec![0u8; 8 + (head + tail) * 8];
        snapshot[..8].copy_from_slice(&word.to_le_bytes());
        for slot in 0..head {
            let at = 8 + slot * 8;
            snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_le_bytes());
        }
        for slot in 0..tail {
            let at = 8 + (head + slot) * 8;
            snapshot[at..at + 8].copy_from_slice(&0x4500u64.to_le_bytes());
        }
        snapshot
    }

    #[test]
    fn genuine_tables_decode_their_declared_slot_count() {
        let maps = mislabelled_fixture_maps();
        let map_index = MapIndex::new(&maps).unwrap();
        for (word, version, slots) in [
            (0x2802u64, (2u8, 40u8), 68usize),
            (0x0003, (3, 0), 92),
            (0x0103, (3, 1), 92),
            (0x0203, (3, 2), 104),
        ] {
            let snapshot = mislabelled_snapshot(word, slots, 0);
            let table = decode_exact_table(
                &snapshot,
                0x7000,
                LinuxLayout::Lp64,
                &map_index,
                &mut CaptureWorkBudget::default(),
                None,
            )
            .expect("budget must admit the table")
            .unwrap_or_else(|| panic!("{version:?} must decode"));
            assert_eq!(table.version, version);
            assert_eq!(table.walk, "full");
            assert_eq!(table.entries.len(), slots, "{version:?}");
            assert!(table.null_entries.is_empty(), "{version:?}");
        }
    }

    #[test]
    fn mislabelled_3x_prefix_decodes_without_an_extended_snapshot() {
        let maps = mislabelled_fixture_maps();
        let map_index = MapIndex::new(&maps).unwrap();
        for layout in [LinuxLayout::Lp64, LinuxLayout::Ilp32] {
            let width = layout.word_bytes();
            for minor in [0u8, 1, 2, 255] {
                let mut snapshot = vec![0u8; 69 * width];
                snapshot[0] = 3;
                snapshot[1] = minor;
                for slot in snapshot[width..].chunks_exact_mut(width) {
                    slot.copy_from_slice(&0x1500u64.to_le_bytes()[..width]);
                }
                let (table, len) = decode_candidate(
                    layout,
                    &snapshot,
                    0,
                    0x7000,
                    &map_index,
                    &mut CaptureWorkBudget::default(),
                    DecodeContext {
                        runtime_view: None,
                        strict_tail: true,
                    },
                )
                .expect("the prefix fits the budget")
                .expect("a complete legacy prefix does not need extended bytes");
                assert_eq!(table.version, (3, minor));
                assert_eq!(table.walk, "known_prefix");
                assert_eq!(table.entries.len(), 68);
                assert_eq!(table.decoded_slot_count(), 68);
                assert_eq!(len, 69 * width);
                let declared_slots = if minor < 2 { 92 } else { 104 };
                for extra in [1, width, (declared_slots - 68) * width - 1] {
                    let mut partial_tail = snapshot.clone();
                    partial_tail.resize(snapshot.len() + extra, 0xa5);
                    let partial = decode_exact_table(
                        &partial_tail,
                        0x7000,
                        layout,
                        &map_index,
                        &mut CaptureWorkBudget::default(),
                        None,
                    )
                    .unwrap()
                    .expect("an unproven partial extension cannot discard the legacy prefix");
                    assert_eq!(partial.walk, "known_prefix");
                    assert_eq!(partial.entries, table.entries);
                    assert_eq!(partial.decoded_slot_count(), 68);
                }
                assert_eq!(
                    exact_table_addresses_n(&snapshot, layout, table.decoded_slot_count()),
                    Some(vec![0x1500; 68])
                );
                let mut dependencies = ScanDependencies::default();
                dependencies.retain_tables(
                    std::slice::from_ref(&table),
                    &snapshot,
                    0x7000,
                    layout,
                    &map_index,
                    &mut CaptureWorkBudget::default(),
                );
                assert!(!dependencies.invalid_span);
                assert_eq!(
                    dependencies.targets.keys().copied().collect::<Vec<_>>(),
                    [0x1000]
                );
                let identity = interface_identity(&table, "null", &None, 0, &map_index, None)
                    .expect("the prefix has its file identity");
                let InterfaceTableKey::File(identity) = identity.table else {
                    panic!("the table is file-backed");
                };
                assert_eq!(identity.usable, 68);
            }
        }
    }

    #[test]
    fn mislabelled_3x_short_snapshots_refuse_incomplete_or_invalid_legacy_prefixes() {
        let maps = mislabelled_fixture_maps();
        let map_index = MapIndex::new(&maps).unwrap();
        for layout in [LinuxLayout::Lp64, LinuxLayout::Ilp32] {
            let width = layout.word_bytes();
            let mut snapshot = vec![0u8; 69 * width];
            snapshot[0] = 3;
            snapshot[1] = 2;
            for slot in snapshot[width..].chunks_exact_mut(width) {
                slot.copy_from_slice(&0x1500u64.to_le_bytes()[..width]);
            }
            for len in 0..snapshot.len() {
                assert!(
                    decode_exact_table(
                        &snapshot[..len],
                        0x7000,
                        layout,
                        &map_index,
                        &mut CaptureWorkBudget::default(),
                        None,
                    )
                    .unwrap()
                    .is_none(),
                    "{layout:?}: incomplete legacy prefix at {len} bytes"
                );
            }
            for broken in [0usize, 67] {
                for pointer in [0x4500u64, 0x6000, u64::MAX] {
                    let mut invalid = snapshot.clone();
                    let at = width + broken * width;
                    invalid[at..at + width].copy_from_slice(&pointer.to_le_bytes()[..width]);
                    assert!(
                        decode_exact_table(
                            &invalid,
                            0x7000,
                            layout,
                            &map_index,
                            &mut CaptureWorkBudget::default(),
                            None,
                        )
                        .unwrap()
                        .is_none(),
                        "{layout:?}: invalid legacy slot {broken} ({pointer:#x})"
                    );
                }
            }
            snapshot[0] = 4;
            assert!(
                decode_exact_table(
                    &snapshot,
                    0x7000,
                    layout,
                    &map_index,
                    &mut CaptureWorkBudget::default(),
                    None,
                )
                .unwrap()
                .is_none(),
                "unknown major versions remain refused"
            );
        }
    }

    /// Fedora's stock SoftHSM labels its 68-slot 2.x table {3,2}. The scan
    /// accepts the complete 68-slot prefix instead of rejecting the table
    /// for its unusable 3.x tail.
    #[test]
    fn mislabelled_3x_table_with_complete_68_prefix_decodes_as_68() {
        let maps = mislabelled_fixture_maps();
        let map_index = MapIndex::new(&maps).unwrap();
        for (word, version, tail) in [
            (0x0203u64, (3u8, 2u8), 36usize),
            (0x0003, (3, 0), 24),
            (0x0103, (3, 1), 24),
        ] {
            let snapshot = mislabelled_snapshot(word, 68, tail);
            let table = decode_exact_table(
                &snapshot,
                0x7000,
                LinuxLayout::Lp64,
                &map_index,
                &mut CaptureWorkBudget::default(),
                None,
            )
            .expect("budget must admit the table")
            .unwrap_or_else(|| panic!("{version:?} with a complete 68 prefix must decode"));
            assert_eq!(table.version, version, "the declared version stays visible");
            assert_eq!(table.walk, "known_prefix", "{version:?}");
            assert_eq!(table.entries.len(), 68, "{version:?}");
            assert!(table.null_entries.is_empty(), "{version:?}");
            assert!(
                table.entries.iter().all(|entry| entry.file_offset < 0x2000),
                "{version:?}: every entry resolves into the executable mapping"
            );
        }
        // The Fedora tail starts with an executable word (the personality
        // routine) before the unrelated data: the prefix decision waits
        // for the first unusable slot instead of stopping at slot 68.
        let mut snapshot = mislabelled_snapshot(0x0203, 68, 36);
        for slot in 68..71 {
            let at = 8 + slot * 8;
            snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_le_bytes());
        }
        let table = decode_exact_table(
            &snapshot,
            0x7000,
            LinuxLayout::Lp64,
            &map_index,
            &mut CaptureWorkBudget::default(),
            None,
        )
        .expect("budget must admit the table")
        .expect("an executable-led tail still decodes the 68 prefix");
        assert_eq!((table.version, table.walk), ((3, 2), "known_prefix"));
        assert_eq!(table.entries.len(), 68);
    }

    #[test]
    fn mislabelled_3x_table_with_incomplete_68_prefix_is_rejected() {
        let maps = mislabelled_fixture_maps();
        let map_index = MapIndex::new(&maps).unwrap();
        // 67 of the first 68 slots valid, one data word inside the prefix.
        for broken in [0usize, 67] {
            let mut snapshot = mislabelled_snapshot(0x0203, 68, 36);
            let at = 8 + broken * 8;
            snapshot[at..at + 8].copy_from_slice(&0x4500u64.to_le_bytes());
            assert!(
                decode_exact_table(
                    &snapshot,
                    0x7000,
                    LinuxLayout::Lp64,
                    &map_index,
                    &mut CaptureWorkBudget::default(),
                    None,
                )
                .expect("budget must admit the attempt")
                .is_none(),
                "slot {broken} breaks the 68 prefix"
            );
        }
        // An all-NULL 68 prefix is data, not a table.
        let mut snapshot = vec![0u8; 8 + 104 * 8];
        snapshot[..8].copy_from_slice(&0x0203u64.to_le_bytes());
        for slot in 68..104 {
            let at = 8 + slot * 8;
            snapshot[at..at + 8].copy_from_slice(&0x4500u64.to_le_bytes());
        }
        assert!(
            decode_exact_table(
                &snapshot,
                0x7000,
                LinuxLayout::Lp64,
                &map_index,
                &mut CaptureWorkBudget::default(),
                None,
            )
            .expect("budget must admit the attempt")
            .is_none(),
            "an all-NULL 68 prefix is not a table"
        );
        // The complete legacy prefix must be present, independently of
        // the declared extended layout. A 67-slot prefix stays refused.
        let snapshot = mislabelled_snapshot(0x0203, 67, 0);
        assert!(
            decode_exact_table(
                &snapshot,
                0x7000,
                LinuxLayout::Lp64,
                &map_index,
                &mut CaptureWorkBudget::default(),
                None,
            )
            .expect("budget must admit the attempt")
            .is_none(),
            "an incomplete legacy prefix is not a table"
        );
    }

    #[test]
    fn mislabelled_3x_table_sweep_finds_single_68_slot_table() {
        let maps = mislabelled_fixture_maps();
        let map_index = MapIndex::new(&maps).unwrap();
        let snapshot = mislabelled_snapshot(0x0203, 68, 36);
        let (tables, skipped) = detect_tables(
            &snapshot,
            0x7000,
            &map_index,
            &mut CaptureWorkBudget::default(),
        );
        assert!(skipped.is_empty(), "{skipped:?}");
        assert_eq!(tables.len(), 1, "the sweep finds the mislabelled table");
        assert_eq!(tables[0].version, (3, 2));
        assert_eq!(tables[0].walk, "known_prefix");
        assert_eq!(tables[0].address, 0x7000);
        assert_eq!(tables[0].entries.len(), 68);
        // The decoded extent is the 68-slot prefix: overlap handling
        // must not swallow the 36 tail bytes as table.
        let (_, len) = decode_candidate(
            LinuxLayout::Lp64,
            &snapshot,
            0,
            0x7000,
            &map_index,
            &mut CaptureWorkBudget::default(),
            DecodeContext {
                runtime_view: None,
                strict_tail: true,
            },
        )
        .expect("budget must admit the table")
        .expect("offset 0 must decode");
        assert_eq!(len, 8 + 68 * 8);
    }

    /// A full-extent 3.2-labelled image: valid executable entries at
    /// `entries`, NULL holes elsewhere in the legacy prefix, file-backed
    /// data words across the whole extension. The sweep must refuse the
    /// single-entry shape (a BSS lookalike); the getter path decodes it
    /// (the provider's own address rules out a lookalike).
    fn sparse_3x_snapshot(entries: &[usize]) -> Vec<u8> {
        let mut snapshot = vec![0u8; 8 + 104 * 8];
        snapshot[..8].copy_from_slice(&0x0203u64.to_le_bytes());
        for &ordinal in entries {
            let at = 8 + ordinal * 8;
            snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_le_bytes());
        }
        for ordinal in 68..104 {
            let at = 8 + ordinal * 8;
            snapshot[at..at + 8].copy_from_slice(&0x4500u64.to_le_bytes());
        }
        snapshot
    }

    #[test]
    fn sweep_refuses_single_entry_and_zero_entry_3x_lookalikes() {
        let maps = mislabelled_fixture_maps();
        let map_index = MapIndex::new(&maps).unwrap();
        for entries in [&[0][..], &[][..]] {
            let snapshot = sparse_3x_snapshot(entries);
            let (tables, skipped) = detect_tables(
                &snapshot,
                0x7000,
                &map_index,
                &mut CaptureWorkBudget::default(),
            );
            assert!(skipped.is_empty(), "{entries:?}: {skipped:?}");
            assert!(
                tables.is_empty(),
                "{entries:?}: the sweep must refuse a lookalike with fewer than two prefix entries"
            );
        }
        // Positive control: the same tail behind a complete 68-entry
        // prefix still decodes on the sweep, so the refusal above pins
        // the entry count, not the tail shape.
        let full = mislabelled_snapshot(0x0203, 68, 36);
        let (tables, skipped) =
            detect_tables(&full, 0x7000, &map_index, &mut CaptureWorkBudget::default());
        assert!(skipped.is_empty(), "{skipped:?}");
        assert_eq!(tables.len(), 1, "the full prefix still decodes");
        assert_eq!(tables[0].entries.len(), 68);
    }

    #[test]
    fn exact_decode_accepts_a_getter_returned_single_entry_3x_table() {
        let maps = mislabelled_fixture_maps();
        let map_index = MapIndex::new(&maps).unwrap();
        let snapshot = sparse_3x_snapshot(&[0]);
        let table = decode_exact_table(
            &snapshot,
            0x7000,
            LinuxLayout::Lp64,
            &map_index,
            &mut CaptureWorkBudget::default(),
            None,
        )
        .expect("budget must admit the attempt")
        .expect("one validated entry at a provider-returned address decodes");
        assert_eq!(table.version, (3, 2));
        assert_eq!(table.walk, "known_prefix");
        assert_eq!(table.entries.len(), 1);
        assert_eq!(table.decoded_slot_count(), 68);
        // Zero entries stay refused on the getter path too: no validated
        // slot, no table.
        let empty = sparse_3x_snapshot(&[]);
        assert!(
            decode_exact_table(
                &empty,
                0x7000,
                LinuxLayout::Lp64,
                &map_index,
                &mut CaptureWorkBudget::default(),
                None,
            )
            .expect("budget must admit the attempt")
            .is_none(),
            "an all-NULL prefix is not a table on any path"
        );
    }

    /// A decoded mislabelled table: version {3,2}, walk `known_prefix`,
    /// 68 entries at the fixture snapshot base.
    fn short_prefix_table() -> ScannedTable {
        let device = Device { major: 8, minor: 1 };
        ScannedTable {
            version: (3, 2),
            walk: "known_prefix",
            entries: (0..68)
                .map(|_| ScannedEntry {
                    name: "C_Initialize",
                    object: ObjectKey { device, inode: 7 },
                    object_path: "/lib/provider.so".to_string(),
                    file_offset: 0x500,
                })
                .collect(),
            null_entries: Vec::new(),
            unpinned: Vec::new(),
            address: 0x7000,
            file_offset: Some(0x2000),
            live_return: false,
            manifest_supported: false,
            extension_impossible: false,
        }
    }

    #[test]
    fn interface_identity_charges_a_short_prefix_under_its_decoded_count() {
        let maps = mislabelled_fixture_maps();
        let map_index = MapIndex::new(&maps).unwrap();
        let device = Device { major: 8, minor: 1 };
        let table = short_prefix_table();
        let identity = interface_identity(&table, "null", &None, 0, &map_index, None)
            .expect("a file-backed table always has an identity");
        assert_eq!(
            identity.table,
            InterfaceTableKey::File(TableIdentity {
                device,
                inode: 7,
                file_offset: 0x2000,
                version_word: 0x0203,
                usable: 68,
            }),
            "the repeat key charges what the decode admitted"
        );
    }

    #[test]
    fn own_export_corroboration_does_not_depend_on_the_declared_table_label() {
        let mut table = short_prefix_table();
        table.entries.truncate(1);
        table.null_entries = (1..68)
            .map(|ordinal| function_name(ordinal).unwrap())
            .collect();
        let symbols = [("C_Initialize".to_string(), 0x500)];
        let exports = ObjectExports {
            object: table.entries[0].object,
            symbols: &symbols,
            getter_present: false,
            witness_fault: false,
        };
        for version in [(2, 40), (3, 0), (3, 1), (3, 2)] {
            table.version = version;
            table.walk = if version == (2, 40) {
                "full"
            } else {
                "known_prefix"
            };
            let score =
                table_evidence_score(0, std::slice::from_ref(&table), &[], &[], &[], &exports);
            assert!(
                score.exports,
                "{version:?}: identical observed positions and exports"
            );
            assert!(table_name_authorized(&score));
            assert!(
                !table_evidence_score(
                    0,
                    std::slice::from_ref(&table),
                    &[],
                    &[],
                    &[],
                    &ObjectExports::NONE
                )
                .exports
            );
        }
    }

    #[test]
    fn observed_runtime_identity_distinguishes_invalid_words_from_null_and_each_other() {
        let maps = parse_maps(
            b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n6000-7000 rw-p 00000000 00:00 0\n",
        )
        .unwrap();
        let index = MapIndex::new(&maps).unwrap();
        let mut budget = CaptureWorkBudget::default();
        let view = ProcessViewId(77);
        let mut words = vec![0x1500u64; 68];
        for invalid in [1u64, 2, 0] {
            words[5] = invalid;
            let table = decode_observed_words(
                (7, 231),
                &words,
                68,
                0x6000,
                &index,
                &mut budget,
                Some(view),
            )
            .unwrap()
            .unwrap();
            assert_eq!(table.unpinned.len(), usize::from(invalid != 0));
            assert_eq!(table.null_entries.len(), usize::from(invalid == 0));
            let identity =
                observed_interface_identity(&table, "null", &None, 0, &index, Some(view), &budget)
                    .unwrap();
            let InterfaceTableKey::Runtime(key) = identity.table else {
                panic!("anonymous table");
            };
            assert!(budget.runtime_table_already_admitted(&key));
        }
        assert_eq!(budget.admitted_runtime_tables.len(), 3);
        assert_eq!(budget.runtime_table_contents.len(), 1);
        assert_eq!(budget.table_candidates_count(), 3);
    }

