    /// Busy-host guard twin for the zero-run skip: a version table
    /// and an export anchor after a long zero run (the BSS shape of
    /// real provider data pages) still decode exactly, with no
    /// skipped evidence lost or invented.
    #[test]
    fn tables_after_a_long_zero_run_still_decode() {
        let maps = mislabelled_fixture_maps();
        let index = MapIndex::new(&maps).unwrap();
        let symbols = [("C_Initialize".to_string(), 0x500)];
        let exports = ObjectExports {
            object: ObjectKey {
                device: Device { major: 8, minor: 1 },
                inode: 7,
            },
            symbols: &symbols,
            getter_present: false,
            witness_fault: false,
        };
        let gap_words = 20_000usize;
        let mut snapshot = vec![0u8; (gap_words + 105) * 8];
        let at = gap_words * 8;
        snapshot[at..at + 8].copy_from_slice(&0x2802u64.to_le_bytes());
        snapshot[at + 8..at + 16].copy_from_slice(&0x1500u64.to_le_bytes());
        let (tables, skipped) = detect_tables_with_clock(
            LinuxLayout::Lp64,
            &snapshot,
            0x7000,
            &index,
            &mut CaptureWorkBudget::default(),
            Some(&exports),
            &[],
            || Some(0),
        );
        assert!(skipped.is_empty(), "no evidence invented: {skipped:?}");
        let table = tables
            .iter()
            .find(|table| table.address == 0x7000 + at as u64)
            .expect("the table after the zero run still decodes");
        assert_eq!(table.entries.len(), 1);
        assert_eq!(table.entries[0].name, "C_Initialize");
        // The same run without anchor rescue: two valid but
        // unexported pointers (0x1508 sits in the fixture's r-xp
        // mapping but names no export) still decode at the exact
        // address. Only the header visit finds them, so a skip that
        // overshoots the header loses the table.
        let mut snapshot = vec![0u8; (gap_words + 105) * 8];
        let at = gap_words * 8;
        snapshot[at..at + 8].copy_from_slice(&0x2802u64.to_le_bytes());
        snapshot[at + 8..at + 16].copy_from_slice(&0x1508u64.to_le_bytes());
        snapshot[at + 16..at + 24].copy_from_slice(&0x1508u64.to_le_bytes());
        let (tables, skipped) = detect_tables_with_clock(
            LinuxLayout::Lp64,
            &snapshot,
            0x7000,
            &index,
            &mut CaptureWorkBudget::default(),
            Some(&exports),
            &[],
            || Some(0),
        );
        assert!(skipped.is_empty(), "no evidence invented: {skipped:?}");
        let table = tables
            .iter()
            .find(|table| table.address == 0x7000 + at as u64)
            .expect("the unanchored table after the zero run still decodes");
        assert_eq!(table.entries.len(), 2);
    }

    #[test]
    fn same_base_extension_anchor_preserves_known_prefix_and_extra_targets() {
        let maps = mislabelled_fixture_maps();
        let index = MapIndex::new(&maps).unwrap();
        let symbols = [
            ("C_Initialize".to_string(), 0x500),
            (function_name(103).unwrap().to_string(), 0x700),
        ];
        let exports = ObjectExports {
            object: ObjectKey {
                device: Device { major: 8, minor: 1 },
                inode: 7,
            },
            symbols: &symbols,
            getter_present: false,
            witness_fault: false,
        };
        for word in [0x2802u64, 0x0003, 0x0103] {
            let mut snapshot = vec![0u8; 105 * 8];
            snapshot[..8].copy_from_slice(&word.to_le_bytes());
            snapshot[8..16].copy_from_slice(&0x1500u64.to_le_bytes());
            snapshot[93 * 8..94 * 8].copy_from_slice(&0x1600u64.to_le_bytes());
            snapshot[104 * 8..105 * 8].copy_from_slice(&0x1700u64.to_le_bytes());
            let (tables, skipped) = detect_tables_with_clock(
                LinuxLayout::Lp64,
                &snapshot,
                0x7000,
                &index,
                &mut CaptureWorkBudget::default(),
                Some(&exports),
                &[],
                || Some(0),
            );
            assert!(skipped.is_empty());
            let targets: BTreeSet<_> = tables
                .iter()
                .filter(|table| table.address == 0x7000)
                .flat_map(|table| table.entries.iter().map(|entry| entry.file_offset))
                .collect();
            assert_eq!(
                targets,
                [0x500, 0x600, 0x700].into_iter().collect(),
                "{word:#x}: a shorter strict shape must not erase independently anchored targets"
            );
            assert!(
                tables
                    .iter()
                    .enumerate()
                    .any(|(at, table)| table.address == 0x7000
                        && table.decoded_slot_count() <= 92
                        && table_evidence_score(at, &tables, &[], &[], &[], &exports).exports),
                "the known prefix retains its exact own-export name evidence"
            );
            assert!(
                tables
                    .iter()
                    .enumerate()
                    .any(|(at, table)| table.address == 0x7000
                        && table.decoded_slot_count() == 104
                        && !table_name_authorized(&table_evidence_score(
                            at,
                            &tables,
                            &[],
                            &[],
                            &[],
                            &exports
                        ))),
                "unproven extension callbacks remain unknown/count-only"
            );
        }
    }

    #[test]
    fn runtime_fingerprint_is_not_reused_for_a_different_decoded_shape() {
        let maps = parse_maps(
            b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n6000-7000 rw-p 00000000 00:00 0\n",
        )
        .unwrap();
        let index = MapIndex::new(&maps).unwrap();
        let mut budget = CaptureWorkBudget::default();
        let view = ProcessViewId(78);
        let mut table = decode_observed_words(
            (2, 40),
            &[0x1500; 68],
            68,
            0x6000,
            &index,
            &mut budget,
            Some(view),
        )
        .unwrap()
        .unwrap();
        let before =
            observed_interface_identity(&table, "null", &None, 0, &index, Some(view), &budget)
                .unwrap();
        table.entries[0].file_offset += 1;
        let after =
            observed_interface_identity(&table, "null", &None, 0, &index, Some(view), &budget)
                .unwrap();
        assert_ne!(
            before, after,
            "a stale raw fingerprint cannot replace a changed current table shape"
        );
    }

