    /// Busy-host guard twin for the interface zero-run skip: one
    /// valid triple immediately after a multi-window zero run still
    /// decodes exactly once, pinning the skip landing.
    #[test]
    fn interfaces_after_a_long_zero_run_still_decode() {
        let maps = parse_maps(
            b"0-1000 r--p 00000000 08:01 7 /lib/provider.so\n\
              1000-3000 r-xp 00001000 08:01 7 /lib/provider.so\n",
        )
        .unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let table = ScannedTable {
            version: (2, 40),
            walk: "full",
            entries: Vec::new(),
            null_entries: Vec::new(),
            unpinned: Vec::new(),
            address: 0x7000,
            file_offset: Some(0),
            live_return: false,
            manifest_supported: false,
            extension_impossible: false,
        };
        let gap_words = 20_000usize;
        let mut snapshot = vec![0u8; (gap_words + 3) * WORD];
        snapshot[gap_words * WORD + WORD..gap_words * WORD + 2 * WORD]
            .copy_from_slice(&0x7000u64.to_ne_bytes());
        let mem = tempfile::tempfile().unwrap();
        let mut operation_bytes = 0;
        let (interfaces, skipped) = scan_interfaces(
            &snapshot,
            &mem,
            std::slice::from_ref(&table),
            &map_index,
            ObjectKey::of(&maps[0]),
            &mut CaptureWorkBudget::default(),
            &mut operation_bytes,
        );
        assert!(skipped.is_empty(), "no evidence invented: {skipped:?}");
        assert_eq!(
            interfaces.len(),
            1,
            "the triple after the zero run still decodes"
        );
        assert_eq!(interfaces[0].table, Some(0));
        assert_eq!(interfaces[0].name_class, "null");
        assert_eq!(interfaces[0].flags, 0);
    }

    /// A hint naming a path that exists only inside the target's mount namespace has no
    /// local identity, so an exact path match must bypass observer-side opening. The
    /// inode-alias branch has the opposite rule and requires two opened-file identities.
    #[test]
    fn alias_hint_requires_same_opened_file_identity() {
        let directory = tempfile::tempdir().unwrap();
        let provider = directory.path().join("provider.so");
        let alias = directory.path().join("provider-alias.so");
        let foreign = directory.path().join("foreign.so");
        std::fs::write(&provider, b"provider bytes").unwrap();
        std::fs::hard_link(&provider, &alias).unwrap();
        std::fs::write(&foreign, b"provider bytes").unwrap();
        let target = open_object(&provider).unwrap();

        // Two simultaneously opened names for the same object are one alias.
        assert_eq!(hint_gate(HintMatch::Inode, &alias, &target), Ok(()));

        // Two equal-size files are not aliases, even on one filesystem.
        let refused = hint_gate(HintMatch::Inode, &foreign, &target).unwrap_err();
        assert!(
            refused.contains("physical identity") && refused.contains("another filesystem"),
            "{refused}"
        );

        // The device comparison is material: equal inode and size from another
        // opened-device domain must still be rejected. The privileged scan fixture
        // supplies the corresponding real cross-mount pair.
        let target_identity = opened_hint_identity(&target).unwrap();
        let foreign_device = OpenedHintIdentity {
            device: target_identity.device.wrapping_add(1),
            ..target_identity
        };
        assert!(opened_hint_identity_gate(foreign_device, target_identity).is_err());

        // Exact path match with no local identity (containerized target): accepted.
        let absent = directory.path().join("target-namespace-only.so");
        assert_eq!(hint_gate(HintMatch::Path, &absent, &target), Ok(()));
    }

    /// M2: the narrowing's attribution names a verbatim path match without
    /// consulting observer identity (the container case the old
    /// identity-first matcher dropped).
    #[test]
    fn first_attributable_hint_names_a_verbatim_hint_without_observer_resolution() {
        let directory = tempfile::tempdir().unwrap();
        let mapped = directory.path().join("libclosure.so.0");
        std::fs::write(&mapped, b"fake").unwrap();
        let file = open_object(&mapped).unwrap();
        let hint = PathBuf::from("/target-namespace-only/libclosure.so.0");
        let matched = [(0, HintMatch::Path)];
        assert_eq!(
            first_attributable_hint(&matched, std::slice::from_ref(&hint), &file),
            (Some(hint), None),
            "verbatim attribution names without observer resolution"
        );
    }

    /// M2: an inode match confirmed against the opened files attributes its
    /// hint; an unconfirmed one attributes nothing and carries the gate's
    /// refusal, as the narrowing reported it.
    #[test]
    fn first_attributable_hint_confirms_an_inode_alias_before_naming() {
        let directory = tempfile::tempdir().unwrap();
        let provider = directory.path().join("provider.so");
        let alias = directory.path().join("provider-alias.so");
        let foreign = directory.path().join("foreign.so");
        std::fs::write(&provider, b"provider bytes").unwrap();
        std::fs::hard_link(&provider, &alias).unwrap();
        std::fs::write(&foreign, b"provider bytes").unwrap();
        let target = open_object(&provider).unwrap();

        let matched = [(0, HintMatch::Inode)];
        assert_eq!(
            first_attributable_hint(&matched, std::slice::from_ref(&alias), &target),
            (Some(alias.clone()), None),
            "the confirmed alias names"
        );

        let (named, refusal) =
            first_attributable_hint(&matched, std::slice::from_ref(&foreign), &target);
        assert_eq!(named, None, "the foreign file names nothing");
        let refusal = refusal.expect("the gate refusal is carried");
        assert!(
            refusal.contains("physical identity") && refusal.contains("another filesystem"),
            "{refusal}"
        );
    }

    /// M2: attribution takes the first passing hint in hint order and keeps
    /// the last gate refusal seen, exactly as the narrowing's `any` did.
    #[test]
    fn first_attributable_hint_takes_the_first_passing_hint_in_order() {
        let directory = tempfile::tempdir().unwrap();
        let provider = directory.path().join("provider.so");
        let foreign = directory.path().join("foreign.so");
        std::fs::write(&provider, b"provider bytes").unwrap();
        std::fs::write(&foreign, b"provider bytes").unwrap();
        let target = open_object(&provider).unwrap();
        let hints = [foreign, provider.clone()];
        let matched = [(0, HintMatch::Inode), (1, HintMatch::Path)];
        let (named, refusal) = first_attributable_hint(&matched, &hints, &target);
        assert_eq!(named, Some(provider), "the first passing hint wins");
        let refusal = refusal.expect("the earlier refusal is carried");
        assert!(
            refusal.contains("physical identity"),
            "the narrowing still reports why the first hint failed: {refusal}"
        );
    }

    #[test]
    fn scan_accepts_a_real_hardlink_alias() {
        let mut fixture = BracketFixture::new(8, true);
        let alias = fixture._dir.path().join("provider-alias.so");
        std::fs::hard_link(&fixture.path, &alias).unwrap();
        let view = ProcessView::open(fixture.view.id(), fixture.view.pid()).unwrap();
        let hints = [alias];
        let outcome = scan_process_view_with_io(
            &ScanRequest {
                pid: view.pid(),
                hints: &hints,
                hooks: &HookRegistry::builtin(),
            },
            &view,
            &mut CaptureWorkBudget::default(),
            &mut fixture,
        )
        .unwrap();
        assert_eq!(outcome.modules().len(), 1, "{:#?}", outcome.skipped());
    }

    #[test]
    #[ignore = "requires a root-owned target with two private cross-device mounts"]
    fn privileged_cross_device_same_inode_alias_is_refused_on_scan_path() {
        let pid = std::env::var("P11SCOPE_ALIAS_COLLISION_PID")
            .expect("fixture target pid")
            .parse::<u32>()
            .expect("numeric fixture target pid");
        let hint = PathBuf::from(
            std::env::var_os("P11SCOPE_ALIAS_COLLISION_HINT").expect("fixture hint path"),
        );
        let target = PathBuf::from(
            std::env::var_os("P11SCOPE_ALIAS_COLLISION_TARGET").expect("fixture target path"),
        );
        let hardlink = PathBuf::from(
            std::env::var_os("P11SCOPE_ALIAS_COLLISION_HARDLINK")
                .expect("fixture target hardlink path"),
        );
        let hint_metadata = std::fs::metadata(&hint).expect("stat fixture hint");
        let target_metadata = std::fs::metadata(&target).expect("stat fixture target");
        let hardlink_metadata = std::fs::metadata(&hardlink).expect("stat fixture hardlink");
        assert_ne!(hint_metadata.dev(), target_metadata.dev());
        assert_eq!(hint_metadata.ino(), target_metadata.ino());
        assert_eq!(hint_metadata.len(), target_metadata.len());
        assert_eq!(hardlink_metadata.dev(), target_metadata.dev());
        assert_eq!(hardlink_metadata.ino(), target_metadata.ino());

        let view = ProcessView::open(ProcessViewId(0), pid).expect("retain fixture target");
        let scan = |hint: PathBuf| {
            let hints = [hint];
            scan_process_view_without_memory(
                &ScanRequest {
                    pid,
                    hints: &hints,
                    hooks: &HookRegistry::builtin(),
                },
                &view,
                &mut CaptureWorkBudget::default(),
            )
            .expect("scan fixture target")
        };

        let exact = scan(target);
        assert_eq!(
            exact.modules().len(),
            1,
            "valid provider was not found by exact target path: {:#?}",
            exact.skipped()
        );
        let alias = scan(hardlink);
        assert_eq!(
            alias.modules().len(),
            1,
            "valid provider was not found by its physical hardlink: {:#?}",
            alias.skipped()
        );

        let outcome = scan(hint);
        assert!(outcome.modules().is_empty(), "foreign alias was admitted");
        assert!(
            outcome
                .skipped()
                .iter()
                .any(|skip| skip.reason.contains("physical identity")),
            "missing physical-identity refusal: {:#?}",
            outcome.skipped()
        );
    }

    fn foreign_failure(subject: &str, reason: &str, root: &str) -> ForeignOpenFailure {
        ForeignOpenFailure {
            subject: subject.into(),
            reason: reason.into(),
            root: root.into(),
        }
    }

    /// Foreign-root open failures stay per-object (JSON and `-v` keep
    /// every object; concise folds): only the retained-root prefix
    /// gains the target-root suffix, grouped per distinct reason by the
    /// renderers. A non-retained refusal keeps its exact producer
    /// wording, and a precondition refusal keeps its own record too.
    #[test]
    fn foreign_root_skips_keep_every_object_with_its_root() {
        let enoent =
            "opening object within retained target root: No such file or directory (os error 2)";
        let not_regular = "target-root object is not a regular file";
        let skips = foreign_root_skips(vec![
            foreign_failure("/lib/a.so", enoent, "/etc/avahi"),
            foreign_failure("/lib/b.so", enoent, "/etc/avahi"),
            foreign_failure("/lib/data.so", not_regular, "/etc/avahi"),
            foreign_failure(
                "relative/path.so",
                "target-root object requires an absolute path without parent traversal",
                "/etc/avahi",
            ),
        ]);
        assert_eq!(skips.len(), 4, "no per-object record is merged: {skips:#?}");
        for skip in &skips[0..2] {
            assert!(
                skip.reason.starts_with(enoent)
                    && skip
                        .reason
                        .contains("(target root /etc/avahi differs from the observer root)"),
                "a retained-root failure names its target root: {skip:#?}"
            );
        }
        assert_eq!(skips[0].subject, "/lib/a.so");
        assert_eq!(skips[1].subject, "/lib/b.so");
        assert_eq!(
            skips[2].reason, not_regular,
            "a non-retained refusal keeps its exact wording: {:#?}",
            skips[2]
        );
        assert_eq!(
            skips[3].reason,
            "target-root object requires an absolute path without parent traversal",
            "a precondition refusal keeps its own record: {:#?}",
            skips[3]
        );
    }

    /// Every preflight miss fails with its named reason; nothing skips.
    /// Unprivileged this observes the root gate; privileged it observes
    /// the pass (or a later named probe).
    #[test]
    fn nschroot_preflight_fails_named_never_skips() {
        match nschroot_preflight() {
            Ok(()) => {
                assert_eq!(
                    unsafe { libc::geteuid() },
                    0,
                    "preflight passes only with privilege"
                );
            }
            Err(reason) => {
                assert!(
                    reason.starts_with("NSCHROOT-PREFLIGHT "),
                    "named reason, never a skip: {reason}"
                );
            }
        }
    }

    /// Re-exec channel for the self-chrooting scan fixture below. The parent
    /// half respawns this same test binary with these variables set; the child
    /// half enters the new root and sleeps until the parent kills it. Its
    /// mappings keep their pre-chroot host paths, exactly like avahi-daemon
    /// after it chroots to `/etc/avahi`. The fresh mount namespace for
    /// `nschroot` comes from the `unshare(1)` launch: an in-process unshare on
    /// a libtest worker thread would diverge only that thread, leaving the
    /// process view (what the scan reads) behind.
    const CHROOT_SCAN_MODE_ENV: &str = "P11SCOPE_CHROOT_SCAN_MODE";
    const CHROOT_SCAN_DIR_ENV: &str = "P11SCOPE_CHROOT_SCAN_DIR";
    const CHROOT_SCAN_PARENT_NS_ENV: &str = "P11SCOPE_CHROOT_SCAN_PARENT_NS";

    fn chroot_scan_child_main() {
        let mode = std::env::var(CHROOT_SCAN_MODE_ENV).unwrap();
        let dir = std::env::var(CHROOT_SCAN_DIR_ENV).unwrap();
        if mode == "nschroot" {
            let parent = std::env::var(CHROOT_SCAN_PARENT_NS_ENV).unwrap();
            let own = std::fs::read_link("/proc/self/ns/mnt")
                .unwrap()
                .display()
                .to_string();
            assert_ne!(
                own, parent,
                "the nschroot child must run in a fresh mount namespace"
            );
        }
        let dir_c = std::ffi::CString::new(dir).unwrap();
        // SAFETY: a NUL-terminated path; chroot affects only this child.
        assert_eq!(
            unsafe { libc::chroot(dir_c.as_ptr()) },
            0,
            "chroot scan child cannot chroot"
        );
        let slash = std::ffi::CString::new("/").unwrap();
        // SAFETY: a NUL-terminated path; chdir affects only this child.
        assert_eq!(
            unsafe { libc::chdir(slash.as_ptr()) },
            0,
            "chroot scan child cannot chdir after chroot"
        );
        // Bounded sleep: the parent kills this child once scanned; the bound
        // only reaps orphans if the parent dies first.
        std::thread::sleep(std::time::Duration::from_secs(120));
    }

    /// A live child held inside an empty root directory. Killed and reaped on
    /// drop, on every exit path.
    struct ChrootScanChild {
        child: std::process::Child,
        dir: tempfile::TempDir,
    }

    /// Named-precondition gate for the `nschroot` collapse cell: root
    /// (chroot), `unshare(1)` and a mintable mount namespace. Any miss
    /// FAILS with its name; nothing here ever skips.
    fn nschroot_preflight() -> Result<(), String> {
        // SAFETY: geteuid takes no arguments and has no side effects.
        if unsafe { libc::geteuid() } != 0 {
            return Err("NSCHROOT-PREFLIGHT root: chroot and mount namespaces need root".into());
        }
        match std::process::Command::new("unshare")
            .args(["-m", "true"])
            .output()
        {
            Ok(output) if output.status.success() => Ok(()),
            Ok(output) => {
                let stderr = String::from_utf8_lossy(&output.stderr);
                if stderr.contains("Operation not permitted") {
                    Err(format!(
                        "NSCHROOT-PREFLIGHT mountns: the kernel refused the fixture mount namespace: {}",
                        stderr.trim()
                    ))
                } else {
                    // Anything else proceeds so a real failure surfaces
                    // loudly at the launch below.
                    Ok(())
                }
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Err(format!(
                "NSCHROOT-PREFLIGHT mountns: unshare(1) is unavailable: {error}"
            )),
            Err(error) => Err(format!(
                "NSCHROOT-PREFLIGHT mountns: cannot probe mount namespaces: {error}"
            )),
        }
    }

    impl ChrootScanChild {
        /// Spawn the child half of `test`: `"chroot"` re-runs this binary
        /// directly (shared mount namespace), `"nschroot"` launches it via
        /// `unshare -m` so the whole child process starts in a fresh mount
        /// namespace. The `"nschroot"` caller passes [`nschroot_preflight`]
        /// first; a missing precondition fails there with its name, never
        /// here.
        fn spawn(mode: &str, test: &str) -> Self {
            // SAFETY: geteuid takes no arguments and has no side effects.
            assert_eq!(
                unsafe { libc::geteuid() },
                0,
                "this cell needs root (chroot)"
            );
            let dir = tempfile::tempdir().unwrap();
            let canonical = dir.path().canonicalize().unwrap();
            let parent_ns = std::fs::read_link("/proc/self/ns/mnt")
                .unwrap()
                .display()
                .to_string();
            let exe = std::env::current_exe().unwrap();
            let mut command = if mode == "nschroot" {
                let mut command = std::process::Command::new("unshare");
                command.arg("-m").arg(&exe).args([
                    "--exact",
                    test,
                    "--ignored",
                    "--nocapture",
                    "--test-threads=1",
                ]);
                command
            } else {
                let mut command = std::process::Command::new(exe);
                command.args([
                    "--exact",
                    test,
                    "--ignored",
                    "--nocapture",
                    "--test-threads=1",
                ]);
                command
            };
            command
                .env(CHROOT_SCAN_MODE_ENV, mode)
                .env(CHROOT_SCAN_DIR_ENV, dir.path())
                .env(CHROOT_SCAN_PARENT_NS_ENV, &parent_ns);
            let mut child = command.spawn().expect("spawn chroot scan child");
            let pid = child.id();
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(15);
            loop {
                if std::fs::read_link(format!("/proc/{pid}/root"))
                    .is_ok_and(|link| link == canonical)
                {
                    break;
                }
                if let Some(status) = child.try_wait().unwrap() {
                    panic!("chroot scan child exited early: {status:?}");
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "chroot scan child never entered {}",
                    dir.path().display()
                );
                std::thread::sleep(std::time::Duration::from_millis(20));
            }
            Self { child, dir }
        }

        fn pid(&self) -> u32 {
            self.child.id()
        }
    }

    impl Drop for ChrootScanChild {
        fn drop(&mut self) {
            // SAFETY: signal a known child pid; failure means it already exited.
            unsafe {
                libc::kill(self.child.id() as libc::pid_t, libc::SIGKILL);
            }
            let _ = self.child.wait();
        }
    }

    /// The chrooted-daemon observability bug: a process that mapped its
    /// objects before chroot (avahi-daemon, named, sshd privsep) keeps
    /// host-absolute paths in `/proc/<pid>/maps`, but every mapped object
    /// was opened inside the retained target root (`/proc/<pid>/root`), so
    /// every object failed with ENOENT on every pass and `--system` never
    /// converged. Mappings that verify against the host root must resolve.
    #[test]
    #[ignore = "root: self-chrooting scan child (chroot, process scan)"]
    fn privileged_chrooted_process_scan_resolves_host_mappings() {
        if std::env::var_os(CHROOT_SCAN_MODE_ENV).is_some() {
            chroot_scan_child_main();
            return;
        }
        let subject = ChrootScanChild::spawn(
            "chroot",
            "discovery::scan::tests::privileged_chrooted_process_scan_resolves_host_mappings",
        );
        let pid = subject.pid();
        // Fixture proof: the child really is chrooted, its maps still name
        // host paths, and those paths exist on the host but not under the
        // child's root.
        let exe = std::env::current_exe().unwrap();
        let maps = std::fs::read_to_string(format!("/proc/{pid}/maps")).unwrap();
        assert!(
            maps.lines()
                .any(|line| line.ends_with(exe.to_str().unwrap())),
            "the chrooted child must map its host executable: {exe:?}"
        );
        let relative = exe.strip_prefix("/").unwrap();
        assert!(
            exe.exists(),
            "the mapped executable must exist on the host: {exe:?}"
        );
        assert!(
            !subject.dir.path().join(relative).exists(),
            "the mapped executable must not exist under the chroot"
        );
        let view = ProcessView::open(ProcessViewId(71), pid).expect("retain chrooted child");
        assert!(view.still_the_same());
        let mut budget = CaptureWorkBudget::default();
        // Primitive-level precondition, unchanged by the fix: opening a
        // mapped path inside the retained target root fails, because maps
        // paths render host-absolute to the observer.
        view.with_filesystem(&mut budget, |filesystem, _| {
            let error = filesystem
                .open_rooted_detailed(&exe)
                .expect_err("target-root open must fail inside the chroot")
                .reason;
            assert!(
                error.contains("opening object within retained target root"),
                "unexpected primitive error: {error}"
            );
            Ok::<(), String>(())
        })
        .unwrap();
        let hooks = HookRegistry::builtin();
        let request = ScanRequest {
            pid,
            hints: &[],
            hooks: &hooks,
        };
        let (outcome, examined, _, _) =
            scan_process_view_examined(&request, &view, &mut budget).expect("scan chrooted child");
        assert!(view.still_the_same());
        assert!(
            outcome.mapping_scan_completed(),
            "the chrooted scan must complete its mapping bracket: {:#?}",
            outcome.skipped()
        );
        // Every retained-root failure must at least attempt the gated host
        // fallback (this test binary itself exceeds the shared object size
        // cap, so its own mapping keeps a fallback-attempted row while the
        // libraries resolve).
        let unattempted: Vec<_> = outcome
            .skipped()
            .iter()
            .filter(|skip| {
                skip.reason
                    .contains("opening object within retained target root")
                    && !skip.reason.contains("(host-root fallback:")
            })
            .collect();
        assert!(
            unattempted.is_empty(),
            "chrooted mappings must resolve via the gated host-root fallback: {unattempted:#?}"
        );
        assert!(
            !examined.is_empty(),
            "the chrooted child's libraries must be examined: {:#?}",
            outcome.skipped()
        );
        // The positive check names real libraries: libc and ld-linux from
        // the child's own maps (host paths, no hard-coded location) must
        // resolve to examined keys, and no examined file may hide an
        // identity mismatch or a missing mount-table row.
        let maps_after = std::fs::read_to_string(format!("/proc/{pid}/maps")).unwrap();
        for want in ["libc.so.6", "ld-linux"] {
            let path = maps_after
                .lines()
                .filter(|line| line.contains(want))
                .filter_map(|line| line.split_whitespace().last())
                .find(|path| path.starts_with('/'))
                .unwrap_or_else(|| panic!("the chrooted child must map {want}"));
            let file =
                std::fs::File::open(path).unwrap_or_else(|_| panic!("host must open {path}"));
            let key = p11scope_manifest::identity::mapping_file_key(&file)
                .unwrap_or_else(|_| panic!("host must key {path}"));
            assert!(
                examined.iter().any(|object| {
                    object.key.device.major == key.device_major
                        && object.key.device.minor == key.device_minor
                        && object.key.inode == key.inode
                }),
                "the chrooted child's {want} ({path}) must be examined: {examined:#?}"
            );
        }
        for skip in outcome.skipped() {
            assert!(
                !skip.reason.contains("does not match mapped object")
                    && !skip.reason.contains("missing from the mount table"),
                "no examined file hides a mismatch or missing mount: {skip:#?}"
            );
        }
    }

    /// Twin: when the target root is foreign AND the mount namespace differs
    /// (a container-like view), the host root must not be trusted at all:
    /// no host-root fallback is attempted. The VMA's own file still opens
    /// through the kernel's `map_files` link and proves like-for-like, so
    /// the child's libraries examine exactly like the same-namespace
    /// twin's — only the host-root fallback stays refused. (Before the
    /// `map_files` join this cell pinned per-object retained-root gaps
    /// that concise folded; the rendering of such gaps stays pinned by
    /// `foreign_root_skips_keep_every_object_with_its_root` and
    /// `concise_folds_foreign_root_gaps_by_reason_and_keeps_json_complete`.)
    #[test]
    #[ignore = "root: self-chrooting scan child in a fresh mount namespace"]
    fn privileged_foreign_mount_namespace_scan_collapses_unopenable_objects() {
        if std::env::var_os(CHROOT_SCAN_MODE_ENV).is_some() {
            chroot_scan_child_main();
            return;
        }
        nschroot_preflight().expect("nschroot preconditions hold");
        let subject = ChrootScanChild::spawn(
            "nschroot",
            "discovery::scan::tests::privileged_foreign_mount_namespace_scan_collapses_unopenable_objects",
        );
        let pid = subject.pid();
        let maps = std::fs::read_to_string(format!("/proc/{pid}/maps")).unwrap();
        assert!(
            !maps.is_empty(),
            "the foreign-root child must have mappings to examine"
        );
        let view = ProcessView::open(ProcessViewId(72), pid).expect("retain foreign-root child");
        let hooks = HookRegistry::builtin();
        let request = ScanRequest {
            pid,
            hints: &[],
            hooks: &hooks,
        };
        let mut budget = CaptureWorkBudget::default();
        // Trigger premise, mirrored from the same-namespace twin: the
        // child really is chrooted into the empty fixture dir with a
        // foreign mount namespace, the raw target-root open fails, and
        // the gated open still fails — without a host attempt — with
        // the foreign ENOENT the `map_files` trigger needs. Without
        // this block a successful forbidden host fallback would be
        // invisible below (it examines with no record at all).
        let exe = std::env::current_exe().unwrap();
        let canonical = subject.dir.path().canonicalize().unwrap();
        assert_eq!(
            std::fs::read_link(format!("/proc/{pid}/root")).unwrap(),
            canonical,
            "the foreign-root child must be chrooted into the fixture dir"
        );
        assert_ne!(
            std::fs::read_link(format!("/proc/{pid}/ns/mnt")).unwrap(),
            std::fs::read_link("/proc/self/ns/mnt").unwrap(),
            "the foreign-root child must run in another mount namespace"
        );
        view.with_filesystem(&mut budget, |filesystem, _| {
            let error = filesystem
                .open_rooted_detailed(&exe)
                .expect_err("target-root open must fail inside the chroot")
                .reason;
            assert!(
                error.contains("opening object within retained target root"),
                "unexpected primitive error: {error}"
            );
            let gated = filesystem
                .open_mapped_object(&exe)
                .expect_err("the gated open must refuse the foreign namespace");
            assert!(
                gated
                    .reason
                    .contains("opening object within retained target root"),
                "unexpected gated error: {}",
                gated.reason
            );
            assert!(
                !gated.reason.contains("(host-root fallback:"),
                "the gated open must not attempt the host fallback: {}",
                gated.reason
            );
            assert!(
                map_files_fallback_triggered(&gated),
                "the gated failure must trigger the map_files fallback: {gated:?}"
            );
            Ok::<(), String>(())
        })
        .unwrap();
        let (outcome, examined, _, _) = scan_process_view_examined(&request, &view, &mut budget)
            .expect("scan foreign-root child");
        assert!(view.still_the_same());
        assert!(
            outcome.mapping_scan_completed(),
            "the foreign-root scan must complete its mapping bracket: {:#?}",
            outcome.skipped()
        );
        assert!(
            outcome.modules().is_empty(),
            "no provider can be proven from the fixture's mappings: {:#?}",
            outcome.modules()
        );
        assert!(
            outcome.skipped().iter().all(|skip| {
                !skip.subject.contains("unopenable in foreign target root")
                    && !skip.reason.contains("mapped objects unopenable")
            }),
            "remaining skips stay per-object, never a merged row: {:#?}",
            outcome.skipped()
        );
        assert!(
            outcome
                .skipped()
                .iter()
                .all(|skip| !skip.reason.contains("(host-root fallback:")),
            "a foreign mount namespace never attempts the host fallback: {:#?}",
            outcome.skipped()
        );
        // The `map_files` join resolves every triggered foreign-ENOENT
        // failure: no retained-root gap may remain (a served stranger or
        // the oversized test binary refuses on its own evidence instead).
        assert!(
            outcome.skipped().iter().all(|skip| {
                !skip
                    .reason
                    .contains("opening object within retained target root")
            }),
            "no retained-root gap survives the map_files join: {:#?}",
            outcome.skipped()
        );
        assert!(
            !examined.is_empty(),
            "the foreign-root child's libraries must be examined: {:#?}",
            outcome.skipped()
        );
        // The positive check names real libraries: libc and ld-linux from
        // the child's own maps (host paths, no hard-coded location) must
        // resolve to examined keys.
        let maps_after = std::fs::read_to_string(format!("/proc/{pid}/maps")).unwrap();
        for want in ["libc.so.6", "ld-linux"] {
            let path = maps_after
                .lines()
                .filter(|line| line.contains(want))
                .filter_map(|line| line.split_whitespace().last())
                .find(|path| path.starts_with('/'))
                .unwrap_or_else(|| panic!("the foreign-root child must map {want}"));
            let file =
                std::fs::File::open(path).unwrap_or_else(|_| panic!("host must open {path}"));
            let key = p11scope_manifest::identity::mapping_file_key(&file)
                .unwrap_or_else(|_| panic!("host must key {path}"));
            assert!(
                examined.iter().any(|object| {
                    object.key.device.major == key.device_major
                        && object.key.device.minor == key.device_minor
                        && object.key.inode == key.inode
                }),
                "the foreign-root child's {want} ({path}) must be examined: {examined:#?}"
            );
        }
    }

    /// H-3 regression: one scan read its view's `/proc/<pid>/mountinfo` once
    /// per mapped executable object — a full kernel render and parse of the
    /// mount table each time, charged to the capture's non-renewable I/O
    /// allowance. On a container host with hundreds of objects and a thousand
    /// mounts that is tens of megabytes per scan. One scan reads it once while
    /// it stays unchanged.
    #[test]
    fn one_scan_reads_its_mount_table_once() {
        let view = ProcessView::open(ProcessViewId(0), std::process::id()).unwrap();
        let maps = parse_maps(&std::fs::read("/proc/self/maps").unwrap()).unwrap();
        let objects = candidate_groups(&maps).len();
        assert!(
            objects >= 3,
            "this test process maps several objects: {objects}"
        );
        let hooks = HookRegistry::default();
        let request = ScanRequest {
            pid: std::process::id(),
            hints: &[],
            hooks: &hooks,
        };
        let witness = crate::process::MountChangeWitness::new();
        let before = crate::process::mountinfo_reads_for_test();

        scan_process_view_without_memory(&request, &view, &mut CaptureWorkBudget::default())
            .unwrap();

        let reads = crate::process::mountinfo_reads_for_test() - before;
        // A mount change elsewhere on the host during the scan must be read
        // again; only an unchanged table has to be read exactly once.
        if !witness.changed() {
            assert_eq!(
                reads, 1,
                "one mount-table read for {objects} mapped objects"
            );
        }
    }

    #[test]
    fn opened_file_identity_rejects_same_size_inode_before_hint_matching() {
        let directory = tempfile::tempdir().unwrap();
        let original_path = directory.path().join("provider.so");
        let replacement_path = directory.path().join("replacement.so");
        std::fs::write(&original_path, b"same-size provider bytes").unwrap();
        std::fs::copy(&original_path, &replacement_path).unwrap();

        let original_file = p11scope_manifest::identity::open_object(&original_path).unwrap();
        let original_identity =
            p11scope_manifest::identity::mapping_file_key(&original_file).unwrap();
        let captured = ObjectKey {
            device: p11scope_manifest::maps::Device {
                major: original_identity.device_major,
                minor: original_identity.device_minor,
            },
            inode: original_identity.inode,
        };
        let replacement_file = p11scope_manifest::identity::open_object(&replacement_path).unwrap();
        let replacement_identity =
            p11scope_manifest::identity::mapping_file_key(&replacement_file).unwrap();
        assert_eq!(
            original_file.metadata().unwrap().len(),
            replacement_file.metadata().unwrap().len(),
            "the replacement must be the same size"
        );
        assert_ne!(captured.inode, replacement_identity.inode);
        let view = ProcessView::open(ProcessViewId(0), std::process::id()).unwrap();
        assert!(
            opened_file_identity_guard(
                &view,
                &replacement_file,
                captured,
                &mut crate::process::MountTableCache::default(),
                &mut CaptureWorkBudget::default(),
            )
            .is_err(),
            "a same-size replacement inode must be refused before hint matching"
        );

        let scan_body = &include_str!("scan.rs")[include_str!("scan.rs")
            .find("pub fn scan_process_view(")
            .expect("scan entry")..];
        let scan_lines = scan_body.lines().map(str::trim).collect::<Vec<_>>();
        let guard = scan_lines
            .iter()
            .position(|line| {
                *line
                    == "if let Err(reason) = opened_file_identity_guard(view, &file, key, &mut mounts, budget) {"
            })
            .expect("the shared identity guard must run in the scan");
        // The guard decision immediately follows every successful target
        // open; only a map_files-proven file under a kernel-empty mount
        // table skips the guard itself (the sandbox-maps exemption,
        // accepted on its merits by the controller ruling of 2026-11-10
        // 16:00: the like-for-like map_files proof passed AND the target
        // mountinfo read OK and empty — a sandboxed target's dangling
        // root breaks table rendering, so resolution is impossible rather
        // than failed — the VMA proof already bound that fd, and the
        // range guard plus the maps bracket still run).
        assert_eq!(
            scan_lines[guard - 1],
            "if !guard_exempt {",
            "only the proven map_files exemption skips the identity guard"
        );
        assert_eq!(
            scan_lines[guard - 2],
            "#[allow(clippy::collapsible_if)]",
            "the exemption keeps the guard call on its own pinnable line"
        );
        assert_eq!(
            scan_lines[guard - 4],
            "};",
            "the guard decision must immediately follow every successful target open"
        );
        // The exemption's two halves stay narrow: root opens never exempt,
        // and the fallback exempts only on a kernel-empty mount-table read
        // (an unreadable or nonempty table keeps the guard). The fallback
        // lives above the scan entry, so these pin against the whole file.
        for exemption_line in [
            "Ok(file) => (file, false),",
            "guard_exempt: mountinfo_empty,",
            "Ok(((), text)) if text.is_empty()",
        ] {
            include_str!("scan.rs")
                .lines()
                .map(str::trim)
                .position(|line| line == exemption_line)
                .expect("the map_files exemption keeps its narrow shape");
        }
        // Narrowed-out mappings stay silent on pre-exclusion failures (the
        // exclusion-before-narrowing contract); only in-scope mismatches
        // record a skip.
        assert_eq!(
            &scan_lines[guard + 1..guard + 4],
            [
                "if !narrowed_out {",
                "skipped.push(Skipped { subject, reason });",
                "}"
            ],
            "identity mismatch skips the opened object unless narrowed out"
        );
        // Hint attribution lives in its helper now (the proven lower
        // file re-attributes through the same gates); the call site
        // still orders it after the guard.
        let attribution = scan_lines
            .iter()
            .position(|line| {
                *line == "attribute_module_hint(&matched, request.hints, &file, &mut hint_matched);"
            })
            .expect("hint-specific attribution must remain after the guard");
        assert!(
            guard < attribution,
            "identity must be checked before hint gating"
        );
        // The alias gate lives in the attribution helper now; it still
        // compares both opened files.
        include_str!("scan.rs")
            .lines()
            .map(str::trim)
            .position(|line| line == "match hint_gate(*kind, &hints[*index], actual) {")
            .expect("attribution must gate aliases using both opened files");
        // The moved helpers keep their contracts: the attribution helper
        // still gates aliases, the facts helper still brackets its read
        // with the pin, and the offer helper still records the held
        // identity it examined.
        for helper_line in [
            "let (named_hint, refusal) = first_attributable_hint(matched, hints, file);",
            "let before = pin_of(file)?;",
            "check_pin_after_read(pin_of(file), &before)?;",
            "identity: mapped.identity,",
            "key_is_identity: mapped.key_is_identity(key),",
        ] {
            include_str!("scan.rs")
                .lines()
                .map(str::trim)
                .position(|line| line == helper_line)
                .expect("the moved helper keeps its contract");
        }
        // ELF facts live in their helper now (the proven lower file
        // re-reads through the same pin bracket); the call site still
        // orders the read after attribution.
        let elf_pin = scan_lines
            .iter()
            .position(|line| {
                *line == "let mut facts = match provider_facts_for(&file, key, &wanted, budget) {"
            })
            .expect("ELF inspection pin");
        assert!(
            guard < attribution && attribution < elf_pin,
            "alias rejection must happen after maps identity and before ELF/table work"
        );
        let guard_body = &include_str!("scan.rs")[include_str!("scan.rs")
            .find("fn opened_file_identity_guard(")
            .expect("identity guard")..];
        assert!(guard_body.contains(
            "crate::discovery::identity::retained_object_key_cached(view, file, mounts, budget)"
        ));
        // The examined push lives in its offer helper now (the proven
        // lower file offers through the same census); the call site
        // still offers the opened file.
        for decision in [
            "if narrowed_out && !excludes_present {\n            continue;\n        }",
            "if hinted && !attributable {",
            "if request.hints.is_empty() && exports.is_empty() {",
            "offer_examined_file(&mut examined, &mut custody, key, held, file, budget);",
        ] {
            assert!(
                scan_body.contains(decision),
                "missing scan decision: {decision}"
            );
        }
    }

    /// A memfd's mount (`mnt_id` 0) is absent from every mount
    /// table, so resolving it fails exactly the way a foreign,
    /// root-filtered table fails a join: the guard's missing-mount
    /// arm, unprivileged.
    fn unresolvable_memfd(name: &std::ffi::CStr) -> File {
        use std::os::unix::io::FromRawFd as _;
        // SAFETY: memfd_create with a NUL-terminated name takes no fd input.
        let fd = unsafe { libc::memfd_create(name.as_ptr(), libc::MFD_CLOEXEC) };
        assert!(
            fd >= 0,
            "memfd_create failed: {}",
            std::io::Error::last_os_error()
        );
        // SAFETY: memfd_create returned a fresh owned descriptor.
        unsafe { File::from_raw_fd(fd) }
    }

    /// The arm-entry premise both missing-mount twins share: the fd
    /// must fail resolution with the missing-mount error, or the
    /// twins below would silently test another path.
    fn assert_missing_mount_unresolvable(view: &ProcessView, file: &File) {
        let error = crate::discovery::identity::retained_object_key_cached(
            view,
            file,
            &mut crate::process::MountTableCache::default(),
            &mut CaptureWorkBudget::default(),
        )
        .expect_err("a memfd mount stays unresolvable, forcing the guard arm");
        assert!(
            p11scope_manifest::identity::is_missing_mount_id_error(&error),
            "the guard arm needs the missing-mount error, got {error:?}"
        );
    }

    /// The missing-mount arm's accept half, at the guard itself: an
    /// unresolvable fd at its own key accepts without the mount
    /// table. Fails on an unconditional refusal in the arm.
    #[test]
    fn opened_file_identity_guard_accepts_a_missing_mount_match() {
        let view = ProcessView::open(ProcessViewId(0), std::process::id()).unwrap();
        let file = unresolvable_memfd(c"guard-missing-mount-match");
        assert_missing_mount_unresolvable(&view, &file);
        let metadata = file.metadata().unwrap();
        let expected = ObjectKey {
            device: Device {
                major: u64::from(libc::major(metadata.dev())),
                minor: u64::from(libc::minor(metadata.dev())),
            },
            inode: metadata.ino(),
        };
        assert!(
            opened_file_identity_guard(
                &view,
                &file,
                expected,
                &mut crate::process::MountTableCache::default(),
                &mut CaptureWorkBudget::default(),
            )
            .is_ok(),
            "an unresolvable fd at its own key must be accepted"
        );
    }

    /// The missing-mount arm's stranger half, at the guard itself: an
    /// unresolvable fd under another key refuses with the shared
    /// mismatch wording. Fails on an unconditional accept in the arm.
    #[test]
    fn opened_file_identity_guard_refuses_a_missing_mount_stranger() {
        let view = ProcessView::open(ProcessViewId(0), std::process::id()).unwrap();
        let file = unresolvable_memfd(c"guard-missing-mount-stranger");
        assert_missing_mount_unresolvable(&view, &file);
        let expected = ObjectKey {
            device: Device { major: 8, minor: 1 },
            inode: 999,
        };
        let error = opened_file_identity_guard(
            &view,
            &file,
            expected,
            &mut crate::process::MountTableCache::default(),
            &mut CaptureWorkBudget::default(),
        )
        .expect_err("an unresolvable stranger must be refused");
        assert!(
            error.contains("does not match mapped object"),
            "the stranger refuses with the shared wording, got {error:?}"
        );
    }

    #[test]
    fn lower_elf_facts_cache_under_the_lower_files_own_key() {
        // The proven lower file's ELF facts must cache under the
        // lower file's own mapping key — never under the upper's
        // maps key with the lower fd (the pin carries no device, so
        // that key collides across lower files). Line-pinned like
        // the ELF inspection pin above.
        let lines: Vec<&str> = include_str!("scan.rs").lines().map(str::trim).collect();
        assert!(
            lines.contains(&"match provider_facts_for(&proof.file, lower_key, &wanted, budget) {"),
            "lower facts keyed by the lower file's mapping key"
        );
        assert!(
            !lines.contains(&"match provider_facts_for(&proof.file, key, &wanted, budget) {"),
            "lower facts never cached under the upper's maps key"
        );
    }

    #[test]
    fn a_short_read_returns_what_it_got_and_says_why_it_stopped() {
        let file = tempfile::NamedTempFile::new().unwrap();
        std::fs::write(file.path(), vec![7u8; 64]).unwrap();
        let mem = File::open(file.path()).unwrap();
        let entry = &parse_maps(b"0-1000 rw-p 00000000 08:01 7 /lib/provider.so\n").unwrap()[0];
        let (bytes, short, exhausted) =
            read_mapping(&mem, entry, &mut CaptureWorkBudget::default(), &mut 0);
        assert!(!exhausted);
        assert_eq!(bytes, vec![7u8; 64], "what was read is kept");
        let short = short.expect("a short snapshot must say so");
        assert!(
            short.contains("read 64 of 4096 bytes") && short.contains("no bytes"),
            "{short}"
        );
    }

    /// A scan whose target exits between the object open and the data
    /// snapshot: production `/proc/<pid>/mem` reads return `Ok(0)` once the
    /// target's mm is gone (an unmapped VMA in a live process fails with
    /// EIO instead), so every data mapping snapshots zero bytes against a
    /// dead pin. Models the alive-time open/proof with the default open and
    /// scripted matching identities, then kills the child on the first
    /// memory read — exactly the busy-host dlopen/dlclose-churn shape.
    struct ExitMidScanFixture {
        _dir: tempfile::TempDir,
        _reap: ReapOnDrop,
        child: std::rc::Rc<std::cell::RefCell<std::process::Child>>,
        pin: std::sync::Arc<crate::process::PidPin>,
        pid: u32,
        path: PathBuf,
        maps: String,
        identity: crate::discovery::identity::FileIdentity,
        killed: std::rc::Rc<std::cell::Cell<bool>>,
        weak_pin: bool,
    }

    struct ReapOnDrop(std::rc::Rc<std::cell::RefCell<std::process::Child>>);
    impl Drop for ReapOnDrop {
        fn drop(&mut self) {
            let mut child = self.0.borrow_mut();
            let _ = child.kill();
            let _ = child.wait();
        }
    }

    struct ExitMidScanMemory {
        child: std::rc::Rc<std::cell::RefCell<std::process::Child>>,
        pin: std::sync::Arc<crate::process::PidPin>,
        pid: u32,
        killed: std::rc::Rc<std::cell::Cell<bool>>,
        weak_pin: bool,
    }

    impl ScanMemory for ExitMidScanMemory {
        fn read_memory_at(&self, _bytes: &mut [u8], _offset: u64) -> std::io::Result<usize> {
            if !self.killed.get() {
                self.killed.set(true);
                self.child
                    .borrow_mut()
                    .kill()
                    .expect("the mid-scan exit must be deliverable");
                let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
                if self.weak_pin {
                    // A start-time fallback pin never flips for an
                    // unreaped zombie, so the zombie state itself is the
                    // wait condition; the test asserts the pin blindness.
                    while !crate::process::process_is_zombie(self.pid) {
                        assert!(
                            std::time::Instant::now() < deadline,
                            "the killed scan target must become a zombie promptly"
                        );
                        std::thread::sleep(std::time::Duration::from_millis(1));
                    }
                } else {
                    while self.pin.still_the_same() {
                        assert!(
                            std::time::Instant::now() < deadline,
                            "the killed scan target must exit promptly"
                        );
                        std::thread::sleep(std::time::Duration::from_millis(1));
                    }
                    assert!(
                        crate::process::process_is_zombie(self.pid),
                        "the mid-scan target exits, it is not reused"
                    );
                }
            }
            // Post-exit `/proc/<pid>/mem` reads: the kernel returns 0 once
            // the target's mm is gone.
            Ok(0)
        }
    }

    impl ScanIo for ExitMidScanFixture {
        type Memory = ExitMidScanMemory;
        fn open_maps(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<Box<dyn Read>> {
            Ok(Box::new(std::io::Cursor::new(
                self.maps.as_bytes().to_vec(),
            )))
        }
        fn open_mem(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<ExitMidScanMemory> {
            Ok(ExitMidScanMemory {
                child: self.child.clone(),
                pin: self.pin.clone(),
                pid: self.pid,
                killed: self.killed.clone(),
                weak_pin: self.weak_pin,
            })
        }
        fn held_identity(
            &mut self,
            _file: &File,
        ) -> Option<crate::discovery::identity::MappedFile> {
            Some(crate::discovery::identity::MappedFile {
                identity: self.identity,
                fs_magic: Some(0xef53),
            })
        }
        fn range_identity(
            &mut self,
            _view: &ProcessView,
            _start: u64,
            _end: u64,
            _: &mut CaptureWorkBudget,
        ) -> Result<std::io::Result<crate::discovery::identity::FileIdentity>, String> {
            Ok(Ok(self.identity))
        }
        fn final_generation(
            &mut self,
            view: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> Result<(), String> {
            view.run_while_same(|| ())
        }
    }

    impl ExitMidScanFixture {
        fn new(weak_pin: bool) -> (Self, ProcessView) {
            use crate::fixture_guard::DieWithParent as _;
            let dir = tempfile::tempdir().unwrap();
            let path = dir.path().join("provider.so");
            std::fs::write(&path, BracketFixture::minimal_provider_elf(8)).unwrap();
            let child = std::rc::Rc::new(std::cell::RefCell::new(
                std::process::Command::new("sleep")
                    .arg("60")
                    .die_with_parent()
                    .spawn()
                    .unwrap(),
            ));
            let pid = child.borrow().id();
            let view = if weak_pin {
                crate::process::start_time_pinned_process_view_for_test(ProcessViewId(75), pid)
                    .unwrap()
            } else {
                ProcessView::open(ProcessViewId(74), pid).unwrap()
            };
            assert!(view.still_the_same());
            let pin = view.retained_pin_arc().clone();
            let key_view = ProcessView::open(ProcessViewId(73), std::process::id()).unwrap();
            let file = File::open(&path).unwrap();
            let key = crate::discovery::identity::retained_object_key(
                &key_view,
                &file,
                &mut CaptureWorkBudget::default(),
            )
            .unwrap();
            let identity = format!(
                "{:x}:{:x} {} {}",
                key.device.major,
                key.device.minor,
                key.inode,
                path.display()
            );
            let maps = format!(
                "1000-2000 r-xp 00000000 {identity}\n\
                 4000-6000 rw-p 00002000 {identity}\n\
                 7000-8000 r--p 00004000 {identity}\n"
            );
            let identity = crate::discovery::identity::FileIdentity { dev: 37, ino: 9 };
            (
                Self {
                    _dir: dir,
                    _reap: ReapOnDrop(child.clone()),
                    child,
                    pin,
                    pid,
                    path,
                    maps,
                    identity,
                    killed: std::rc::Rc::new(std::cell::Cell::new(false)),
                    weak_pin,
                },
                view,
            )
        }
    }

    /// Exit twin: zero-byte data snapshots against a dead pin name the
    /// exit exactly, and the module — zero bytes examined — keeps no
    /// verified-absence no-table row.
    #[test]
    fn zero_byte_snapshot_of_an_exited_process_names_the_exit_exactly() {
        let (mut fixture, view) = ExitMidScanFixture::new(false);
        let hooks = HookRegistry::builtin();
        let hints = [fixture.path.clone()];
        let (outcome, _, _, _) = scan_view_with_examined(
            &ScanRequest {
                pid: view.pid(),
                hints: &hints,
                hooks: &hooks,
            },
            &view,
            &mut CaptureWorkBudget::default(),
            &mut fixture,
            true,
        )
        .expect("a mid-scan exit names its gaps, it does not error");
        assert!(!view.still_the_same(), "the mid-scan exit really happened");
        let reasons: Vec<&str> = outcome
            .skipped()
            .iter()
            .map(|skip| skip.reason.as_str())
            .collect();
        assert_eq!(
            reasons
                .iter()
                .filter(|reason| reason.contains("read 0 of"))
                .count(),
            2,
            "both data mappings name their zero-byte snapshot: {reasons:?}"
        );
        assert!(
            reasons
                .iter()
                .any(|reason| reason.contains("the process exited during the snapshot")),
            "the exit is named exactly: {reasons:?}"
        );
        assert!(
            reasons
                .iter()
                .all(|reason| !reason.contains(NO_TABLE_FOUND_MARKER)),
            "zero examined bytes claim no verified absence: {reasons:?}"
        );
    }

    /// Live twin: a zero-byte snapshot against a live pin keeps the
    /// established read wording, but — like the exit twin — zero examined
    /// bytes still claim no verified-absence no-table row.
    #[test]
    fn zero_byte_snapshot_of_a_live_process_keeps_the_read_wording() {
        let mut fixture = BracketFixture::new(8, false);
        fixture.mem.set_len(0).unwrap();
        let identity = crate::discovery::identity::FileIdentity { dev: 37, ino: 9 };
        fixture.mapped = Some((identity, identity));
        let outcome = fixture
            .run(&mut CaptureWorkBudget::default())
            .expect("a live scan names its gaps, it does not error");
        let reasons: Vec<&str> = outcome
            .skipped()
            .iter()
            .map(|skip| skip.reason.as_str())
            .collect();
        assert!(
            reasons.iter().any(|reason| reason.contains("read 0 of")
                && reason.contains("the read returned no bytes")),
            "the live zero-byte read keeps its wording: {reasons:?}"
        );
        assert!(
            !outcome.modules().is_empty(),
            "the live scan keeps its module: {outcome:?}"
        );
        assert!(
            reasons
                .iter()
                .all(|reason| !reason.contains(NO_TABLE_FOUND_MARKER)),
            "zero examined bytes claim no verified absence: {reasons:?}"
        );
    }

    /// No-table suppression, data-empty arm: a module with only executable
    /// mappings (no data pages to snapshot) keeps its no-table row — there
    /// are no per-mapping rows to carry the gap.
    #[test]
    fn module_with_only_executable_mappings_keeps_its_no_table_row() {
        let mut f = BracketFixture::new(8, false);
        let executable_only: String = f
            .maps_a
            .lines()
            .filter(|line| line.contains(" r-xp "))
            .map(|line| format!("{line}\n"))
            .collect();
        assert!(
            executable_only.contains("provider.so"),
            "the filtered maps still name the provider: {executable_only:?}"
        );
        assert!(
            !executable_only.contains(" r--p ") && !executable_only.contains(" rw-p "),
            "the filtered maps carry no data pages: {executable_only:?}"
        );
        f.maps_a = executable_only.clone();
        f.maps_b = executable_only;
        let outcome = f
            .run(&mut CaptureWorkBudget::default())
            .expect("an r-xp-only scan completes");
        assert!(
            outcome
                .skipped()
                .iter()
                .any(|skip| skip.reason.contains(NO_TABLE_FOUND_MARKER)),
            "the data-empty module keeps its no-table row: {:?}",
            outcome.skipped()
        );
    }

    /// Fallback-pin twin: the target exits mid-scan under a start-time
    /// fallback pin, which reads the unreaped zombie as alive. Tier-3
    /// review I1 (`opus-rv-zero-byte-snapshot-t3`): a fallback pin cannot
    /// prove a whole-group exit — a zombie leader with live members reads
    /// identically — so the zero-byte snapshots keep the read wording
    /// instead of naming an exit they cannot prove. No vacuous no-table
    /// row either way.
    #[test]
    fn zero_byte_snapshot_of_a_fallback_pinned_zombie_keeps_the_read_wording() {
        let (mut fixture, view) = ExitMidScanFixture::new(true);
        let hooks = HookRegistry::builtin();
        let hints = [fixture.path.clone()];
        let (outcome, _, _, _) = scan_view_with_examined(
            &ScanRequest {
                pid: view.pid(),
                hints: &hints,
                hooks: &hooks,
            },
            &view,
            &mut CaptureWorkBudget::default(),
            &mut fixture,
            true,
        )
        .expect("a mid-scan exit names its gaps, it does not error");
        assert!(
            view.still_the_same(),
            "the fallback pin reads the zombie as alive"
        );
        assert!(
            crate::process::process_is_zombie(view.pid()),
            "the mid-scan exit really happened"
        );
        let reasons: Vec<&str> = outcome
            .skipped()
            .iter()
            .map(|skip| skip.reason.as_str())
            .collect();
        assert_eq!(
            reasons
                .iter()
                .filter(|reason| reason.contains("read 0 of"))
                .count(),
            2,
            "both data mappings name their zero-byte snapshot: {reasons:?}"
        );
        assert!(
            reasons.iter().any(|reason| reason.contains("read 0 of")
                && reason.contains("the read returned no bytes")),
            "the unproven exit keeps the read wording: {reasons:?}"
        );
        assert!(
            reasons
                .iter()
                .all(|reason| !reason.contains("the process exited during the snapshot")),
            "a fallback pin never names an exit it cannot prove: {reasons:?}"
        );
        assert!(
            reasons
                .iter()
                .all(|reason| !reason.contains(NO_TABLE_FOUND_MARKER)),
            "zero examined bytes claim no verified absence: {reasons:?}"
        );
    }

    /// Tier-3 review I1 helper twin ("leader exiting, member live"): a
    /// pidfd-pinned group whose leader released its mm mid-exit (state R
    /// with `PF_EXITING`, TGID maps empty) while a member stays live
    /// keeps the read wording. The old live-member observation needs leader Z,
    /// so it answers Unresolved on this shape and fails open. The scripted
    /// empty maps stand in for the leader's released mm — a live leader
    /// reads the same decision inputs (birth matches, state is not Z) —
    /// while the pidfd pin, the retained birth and the live member are
    /// real.
    #[test]
    fn zero_byte_snapshot_of_an_exiting_leader_with_a_live_member_keeps_the_read_wording() {
        use crate::process::cold_view_tests::ColdLeaderSubject;
        use crate::process::leader_exit::LeaderExitReadBudget;
        let group = ColdLeaderSubject::spawn(1);
        let pid = group.pid();
        let worker = group.tids[0];
        assert!(
            !crate::process::process_is_zombie(pid),
            "the leader is still alive"
        );
        assert!(
            std::fs::metadata(format!("/proc/{pid}/task/{worker}")).is_ok(),
            "the member is live"
        );
        assert!(
            !std::fs::read_to_string(format!("/proc/{pid}/maps"))
                .expect("TGID maps are readable")
                .is_empty(),
            "a live leader shows nonempty TGID maps: the emptiness below is scripted"
        );
        let view =
            ProcessView::open(ProcessViewId(76), pid).expect("a view opens on the live group");
        assert_eq!(
            view.original_exited(),
            Ok(false),
            "the pin proves the group alive"
        );
        assert!(
            view.retained_pin().pidfd().is_ok(),
            "a pidfd-backed pin, not the fallback"
        );
        assert!(
            !zero_read_names_exit_with(
                &view,
                || true,
                &mut LeaderExitReadBudget::for_final_exit_proof()
            ),
            "an exiting leader with a live member keeps the read wording"
        );
    }

    /// Tier-3 review I1 helper twin ("exhausted budget"): an exhausted
    /// exit-proof budget answers Unresolved — never alive, never exited —
