    /// No-table suppression, partial-read arm: a data mapping that yields
    /// bytes and then hits the zero-byte stop still truncates its module —
    /// the per-mapping partial row stays, but the verified-absence marker
    /// must not claim a complete scan from a truncated snapshot.
    #[test]
    fn partial_snapshot_followed_by_a_zero_read_keeps_no_verified_absence_row() {
        let mut f = BracketFixture::new(8, false);
        let code = f
            .maps_a
            .lines()
            .find(|line| line.contains(" r-xp ") && line.contains("provider.so"))
            .expect("the fixture still maps provider code")
            .to_string();
        let data_line = f
            .maps_a
            .lines()
            .find(|line| line.contains(" rw-p ") && line.contains("provider.so"))
            .expect("the fixture still carries the rw-p range");
        let identity = data_line
            .split_once("00002000 ")
            .expect("the rw-p offset still pins the identity")
            .1;
        let huge_maps = format!("{code}\n4000-204000 rw-p 00002000 {identity}\n");
        f.maps_a = huge_maps.clone();
        f.maps_b = huge_maps;
        f.mem.set_len(0x5000).unwrap();
        let identity = crate::discovery::identity::FileIdentity { dev: 37, ino: 9 };
        f.mapped = Some((identity, identity));
        let outcome = f
            .run(&mut CaptureWorkBudget::default())
            .expect("a partial scan names its gaps, it does not error");
        let reasons: Vec<&str> = outcome
            .skipped()
            .iter()
            .map(|skip| skip.reason.as_str())
            .collect();
        assert!(
            reasons
                .iter()
                .any(|reason| reason.contains("read 4096 of 2097152 bytes")),
            "the partial zero-stop names its shortfall: {reasons:?}"
        );
        assert!(
            reasons
                .iter()
                .all(|reason| !reason.contains(NO_TABLE_FOUND_MARKER)),
            "a truncated snapshot claims no verified absence: {reasons:?}"
        );
    }

    #[test]
    fn a_pointer_into_data_or_nowhere_rejects_the_whole_candidate() {
        let maps = parse_maps(
            b"1000-2000 r-xp 00000000 08:01 7 /lib/provider.so\n\
              2000-3000 rw-p 00001000 08:01 7 /lib/provider.so\n",
        )
        .unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let build = |bad: u64| {
            let mut snapshot = vec![0u8; 8 + 68 * 8];
            snapshot[..8].copy_from_slice(&0x2802u64.to_ne_bytes());
            for slot in 0..68 {
                let at = 8 + slot * 8;
                snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_ne_bytes());
            }
            snapshot[8..16].copy_from_slice(&bad.to_ne_bytes());
            snapshot
        };
        assert_eq!(
            detect_tables(
                &build(0x1600),
                0x2000,
                &map_index,
                &mut CaptureWorkBudget::default()
            )
            .0
            .len(),
            1
        );
        assert!(
            detect_tables(
                &build(0x2500),
                0x2000,
                &map_index,
                &mut CaptureWorkBudget::default()
            )
            .0
            .is_empty()
        ); // rw- data
        assert!(
            detect_tables(
                &build(0x9000),
                0x2000,
                &map_index,
                &mut CaptureWorkBudget::default()
            )
            .0
            .is_empty()
        ); // unmapped
        // Every slot NULL: a zeroed page is not a table.
        assert!(
            detect_tables(
                &vec![0u8; 8 + 68 * 8],
                0x2000,
                &map_index,
                &mut CaptureWorkBudget::default()
            )
            .0
            .is_empty()
        );
        // One NULL slot among live ones is legitimate evidence, not a rejection.
        let mut with_null = build(0x1600);
        with_null[16..24].copy_from_slice(&0u64.to_ne_bytes());
        let (tables, _) = detect_tables(
            &with_null,
            0x2000,
            &map_index,
            &mut CaptureWorkBudget::default(),
        );
        assert_eq!(tables[0].null_entries.len(), 1);
        assert_eq!(tables[0].entries.len(), 67);
    }

    #[test]
    fn exact_table_addresses_keep_non_null_fields_in_canonical_order() {
        let mut snapshot = vec![0u8; 8 + 68 * 8];
        snapshot[..8].copy_from_slice(&0x2802u64.to_ne_bytes());
        snapshot[8..16].copy_from_slice(&0x1110u64.to_ne_bytes());
        snapshot[16..24].copy_from_slice(&0u64.to_ne_bytes());
        snapshot[24..32].copy_from_slice(&0x3330u64.to_ne_bytes());

        assert_eq!(
            exact_table_addresses(&snapshot, LinuxLayout::Lp64).unwrap(),
            [0x1110, 0x3330]
        );
    }

    #[test]
    fn cgroup_shared_control_stops_actual_scan_charge() {
        let control = crate::scope::inventory_cgroup::CollectionControl::new(None);
        let checked = control.clone();
        let mut budget = CaptureWorkBudget::default();
        budget.set_collection_work(CollectionWork::new(move |_| checked.check().is_ok()));
        assert!(budget.charge(1));
        control.cancel();
        assert!(
            !budget.charge(1),
            "a stopped collection cannot continue decoded-record work"
        );
    }

    #[test]
    fn cgroup_shared_control_stops_actual_scan_and_maps_reads() {
        let control = crate::scope::inventory_cgroup::CollectionControl::new(None);
        let checked = control.clone();
        let mut budget = CaptureWorkBudget::default();
        budget.set_collection_work(CollectionWork::new(move |_| checked.check().is_ok()));
        assert_eq!(budget.allowed_io(0, 10), 10);
        struct StopAfterRead {
            control: crate::scope::inventory_cgroup::CollectionControl,
            reads: Arc<std::sync::atomic::AtomicUsize>,
            bytes: std::io::Cursor<Vec<u8>>,
        }
        impl std::io::Read for StopAfterRead {
            fn read(&mut self, out: &mut [u8]) -> std::io::Result<usize> {
                self.reads.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                let read = self.bytes.read(out)?;
                self.control.cancel();
                Ok(read)
            }
        }
        let reads = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let reader = StopAfterRead {
            control: control.clone(),
            reads: reads.clone(),
            bytes: std::io::Cursor::new(b"1000-2000 r-xp 00000000 08:01 7 /lib/a.so\n".to_vec()),
        };
        let result = read_maps_checked(
            reader,
            &mut budget,
            MapsReadLimits {
                max_bytes: 1024,
                max_entries: 10,
                chunk: 8,
            },
            || Some(1),
            &mut MapsReadBuffers::default(),
        );
        assert!(
            result.is_err(),
            "the production maps read loop must stop after cancellation"
        );
        assert_eq!(
            reads.load(std::sync::atomic::Ordering::SeqCst),
            1,
            "no second read after the checkpoint observes cancellation"
        );
        assert_eq!(
            budget.allowed_io(0, 10),
            0,
            "the deep scan read boundary must poll control"
        );
        assert_eq!(
            budget.allowed_capture_io(10),
            0,
            "the maps sweep read boundary must poll control"
        );
    }

