    #[test]
    fn deadline_polling_uses_the_local_window_boundary_after_variable_work() {
        let maps = parse_maps(b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n").unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let second_offset = 4095 * WORD;
        let mut snapshot = vec![0u8; second_offset + 8 + 104 * WORD];
        for offset in [0, second_offset] {
            snapshot[offset..offset + 8].copy_from_slice(&0x0203u64.to_ne_bytes());
            for slot in 0..104 {
                let at = offset + 8 + slot * WORD;
                snapshot[at..at + WORD].copy_from_slice(&0x1500u64.to_ne_bytes());
            }
        }
        let mut budget = CaptureWorkBudget::default();
        budget.set_deadline(Some(10));
        let mut polls = 0;
        let (tables, skipped) = detect_tables_with_clock(
            LinuxLayout::Lp64,
            &snapshot,
            0x7000,
            &map_index,
            &mut budget,
            None,
            &[],
            || {
                polls += 1;
                Some(if polls == 1 { 0 } else { 10 })
            },
        );
        assert_eq!(polls, 2, "initial and next local 4096-window boundary");
        assert!(
            tables
                .iter()
                .any(|table| table.address == 0x7000 + second_offset as u64)
        );
        assert_eq!(skipped, vec![SCAN_DEADLINE_REASON]);
    }

    #[test]
    fn maps_reader_distinguishes_eof_byte_entry_io_and_deadline_bounds() {
        use std::io::Cursor;

        let run = |input: &[u8], max_bytes, max_entries, total_bytes, clock: Vec<Option<u64>>| {
            let mut budget = CaptureWorkBudget::new(ScanLimits {
                per_object_bytes: u64::MAX,
                total_bytes,
            });
            budget.set_deadline(Some(5));
            let mut clock = clock.into_iter();
            read_maps_with_limits(
                Cursor::new(input),
                &mut budget,
                max_bytes,
                max_entries,
                4,
                || clock.next().unwrap_or(Some(0)),
            )
            .unwrap()
        };

        let (_, reasons) = run(b"aa\nbb\n", 6, 10, 100, vec![Some(0), Some(0), Some(0)]);
        assert!(
            reasons.is_empty(),
            "exact EOF is not a byte cut: {reasons:?}"
        );

        let (bytes, reasons) = run(b"aa\nbb\n", 5, 10, 100, vec![Some(0), Some(0), Some(0)]);
        assert_eq!(bytes, b"aa\n");
        assert!(reasons.contains(&MAPS_CEILING_REASON));

        let (bytes, reasons) = run(b"aa\nbb\n", 100, 1, 100, vec![Some(0), Some(0), Some(0)]);
        assert_eq!(bytes, b"aa\n");
        assert!(reasons.contains(&MAPS_ENTRY_CEILING_REASON));

        let (bytes, reasons) = run(b"aa\nbb\n", 100, 10, 3, vec![Some(0), Some(0), Some(0)]);
        assert_eq!(bytes, b"aa\n");
        assert!(reasons.contains(&IO_CEILING_REASON));

        let (bytes, reasons) = run(b"aa\nbb\n", 5, 1, 100, vec![Some(0), Some(0), Some(10)]);
        assert_eq!(bytes, b"aa\n");
        assert!(reasons.contains(&MAPS_CEILING_REASON));
        assert!(reasons.contains(&MAPS_ENTRY_CEILING_REASON));
    }

    #[test]
    fn budgeted_elf_reader_never_overspends_or_reads_after_deadline() {
        let short = tempfile::tempfile().unwrap();
        short.set_len(8).unwrap();
        let mut budget = CaptureWorkBudget::new(ScanLimits {
            per_object_bytes: 8,
            total_bytes: 7,
        });
        let mut requests = Vec::new();
        let error = read_elf_snapshot_with(
            &short,
            &mut budget,
            |_| None,
            |file, bytes, offset| {
                requests.push(bytes.len());
                file.read_at(bytes, offset)
            },
        )
        .unwrap_err();
        assert!(error.contains(IO_CEILING_REASON), "{error}");
        assert_eq!(
            requests,
            [7],
            "the underlying reader sees only admitted bytes"
        );
        assert_eq!(budget.attempted_io_bytes(), 7);

        let mut budget = CaptureWorkBudget::default();
        let mut reads = 0;
        let error = read_elf_snapshot_with(
            &short,
            &mut budget,
            |_| Some(SCAN_DEADLINE_REASON),
            |file, bytes, offset| {
                reads += 1;
                file.read_at(bytes, offset)
            },
        )
        .unwrap_err();
        assert!(error.contains(SCAN_DEADLINE_REASON), "{error}");
        assert_eq!(
            reads, 0,
            "an expired deadline refuses before the first read"
        );
        assert_eq!(budget.attempted_io_bytes(), 0);

        let long = tempfile::tempfile().unwrap();
        long.set_len((READ_CHUNK + 1) as u64).unwrap();
        let mut budget = CaptureWorkBudget::default();
        let mut polls = 0;
        let mut reads = 0;
        let error = read_elf_snapshot_with(
            &long,
            &mut budget,
            |_| {
                polls += 1;
                (polls == 2).then_some(SCAN_DEADLINE_REASON)
            },
            |file, bytes, offset| {
                reads += 1;
                file.read_at(bytes, offset)
            },
        )
        .unwrap_err();
        assert!(error.contains(SCAN_DEADLINE_REASON), "{error}");
        assert_eq!(polls, 2);
        assert_eq!(reads, 1, "expiry between chunks prevents the next read");
        assert_eq!(budget.attempted_io_bytes(), READ_CHUNK as u64);
    }

    #[test]
    fn maps_reader_trims_incomplete_lines_on_deadline_and_clock_failure() {
        use std::io::Cursor;

        for (clock, reason) in [
            (vec![Some(0), Some(10)], SCAN_DEADLINE_REASON),
            (vec![Some(0), None], SCAN_CLOCK_REASON),
        ] {
            let mut budget = CaptureWorkBudget::new(ScanLimits::default());
            budget.set_deadline(Some(5));
            let mut clock = clock.into_iter();
            let (bytes, reasons) =
                read_maps_with_limits(Cursor::new(b"aa\nbb\n"), &mut budget, 100, 10, 4, || {
                    clock.next().unwrap_or(Some(0))
                })
                .unwrap();
            assert_eq!(bytes, b"aa\n");
            assert!(reasons.contains(&reason), "{reasons:?}");
        }
    }

    /// Task 11 fix round 2 (csf_ce5962b root closure): the live engine's
    /// per-record snapshot is refused whole — never trimmed — at the byte,
    /// entry, and total-I/O ceilings and at the batch deadline; an already
    /// expired deadline refuses before a byte is read, on every read of the
    /// stopped batch, not only the once the reader reports it.
    #[test]
    fn live_maps_snapshot_is_refused_whole_at_every_bound() {
        use std::io::Cursor;

        let line: &[u8] = b"7f0000000000-7f0000001000 r-xp 00000000 08:01 12345 /opt/p.so\n";
        let snapshot = |budget: &mut CaptureWorkBudget, input: &[u8], clock: Vec<Option<u64>>| {
            let mut clock = clock.into_iter();
            read_maps_or_refuse(Cursor::new(input), budget, || {
                clock.next().unwrap_or(Some(0))
            })
        };

        // Lines long enough that the byte ceiling lands before the entry ceiling.
        let long_line = [&line[..line.len() - 1], &[b'p'; 64][..], b"\n"].concat();
        let oversized =
            long_line.repeat(usize::try_from(MAX_MAPS_BYTES).unwrap() / long_line.len() + 1);
        assert!(u64::try_from(oversized.len()).unwrap() > MAX_MAPS_BYTES);
        let mut budget = CaptureWorkBudget::default();
        assert_eq!(
            snapshot(&mut budget, &oversized, vec![]).err(),
            Some(MAPS_CEILING_REASON.into()),
            "one byte over the byte ceiling is refused, not trimmed"
        );

        let short_line: &[u8] = b"0-1 ---p 0 0:0 0\n";
        let mut budget = CaptureWorkBudget::default();
        assert_eq!(
            snapshot(&mut budget, &short_line.repeat(MAX_MAP_ENTRIES + 1), vec![]).err(),
            Some(MAPS_ENTRY_CEILING_REASON.into()),
            "one entry over the entry ceiling is refused, not trimmed"
        );

        let mut budget = CaptureWorkBudget::new(ScanLimits {
            per_object_bytes: u64::MAX,
            total_bytes: 8,
        });
        assert_eq!(
            snapshot(&mut budget, &line.repeat(2), vec![]).err(),
            Some(IO_CEILING_REASON.into()),
            "the capture's total-I/O ceiling refuses the snapshot"
        );

        let mut budget = CaptureWorkBudget::default();
        budget.set_deadline(Some(5));
        assert_eq!(
            snapshot(
                &mut budget,
                &line.repeat(2),
                vec![Some(0), Some(0), Some(10)]
            )
            .err(),
            Some(SCAN_DEADLINE_REASON.into()),
            "a deadline reached during the read refuses the snapshot"
        );

        let mut budget = CaptureWorkBudget::default();
        budget.set_deadline(Some(5));
        for attempt in 1..=2 {
            assert_eq!(
                snapshot(&mut budget, line, vec![Some(10)]).err(),
                Some(SCAN_DEADLINE_REASON.into()),
                "read {attempt} of a stopped batch is refused"
            );
            assert_eq!(
                budget.attempted_io_bytes(),
                0,
                "read {attempt} read nothing"
            );
        }

        let mut budget = CaptureWorkBudget::default();
        let entries = snapshot(&mut budget, line, vec![]).unwrap();
        assert_eq!(entries.len(), 1);
        assert_eq!(
            budget.attempted_io_bytes(),
            u64::try_from(line.len()).unwrap(),
            "a complete snapshot is charged to the capture's I/O total"
        );
    }

    /// The buffer-reusing maps read returns exactly what the fresh-buffer
    /// read returns: the same entries on success, the same refusal at the
    /// byte, entry and total-I/O ceilings and at the batch deadline
    /// (including an already-expired one), and the same I/O charge. One
    /// shared buffer serves every case in sequence, including a small read
    /// right after the oversized one, so cross-read reuse is covered too.
    #[test]
    fn reused_maps_buffers_match_fresh_reads_at_every_ceiling() {
        use std::io::Cursor;

        enum BudgetKind {
            Default,
            CappedTotal(u64),
            Deadline(u64),
        }
        fn make_budget(kind: &BudgetKind) -> CaptureWorkBudget {
            match *kind {
                BudgetKind::Default => CaptureWorkBudget::default(),
                BudgetKind::CappedTotal(total_bytes) => CaptureWorkBudget::new(ScanLimits {
                    per_object_bytes: u64::MAX,
                    total_bytes,
                }),
                BudgetKind::Deadline(at) => {
                    let mut budget = CaptureWorkBudget::default();
                    budget.set_deadline(Some(at));
                    budget
                }
            }
        }

        let line: &[u8] = b"7f0000000000-7f0000001000 r-xp 00000000 08:01 12345 /opt/p.so\n";
        let long_line = [&line[..line.len() - 1], &[b'p'; 64][..], b"\n"].concat();
        let oversized =
            long_line.repeat(usize::try_from(MAX_MAPS_BYTES).unwrap() / long_line.len() + 1);
        assert!(u64::try_from(oversized.len()).unwrap() > MAX_MAPS_BYTES);
        let short_line: &[u8] = b"0-1 ---p 0 0:0 0\n";
        let many_entries = short_line.repeat(MAX_MAP_ENTRIES + 1);
        let two_lines = line.repeat(2);

        struct Case<'a> {
            name: &'static str,
            input: &'a [u8],
            kind: BudgetKind,
            script: Vec<Option<u64>>,
        }
        let cases = vec![
            Case {
                name: "complete",
                input: line,
                kind: BudgetKind::Default,
                script: vec![],
            },
            Case {
                name: "byte ceiling",
                input: &oversized,
                kind: BudgetKind::Default,
                script: vec![],
            },
            Case {
                name: "complete after oversized",
                input: line,
                kind: BudgetKind::Default,
                script: vec![],
            },
            Case {
                name: "entry ceiling",
                input: &many_entries,
                kind: BudgetKind::Default,
                script: vec![],
            },
            Case {
                name: "total-I/O ceiling",
                input: &two_lines,
                kind: BudgetKind::CappedTotal(8),
                script: vec![],
            },
            Case {
                name: "deadline during read",
                input: &two_lines,
                kind: BudgetKind::Deadline(5),
                script: vec![Some(0), Some(0), Some(10)],
            },
            Case {
                name: "expired deadline",
                input: line,
                kind: BudgetKind::Deadline(5),
                script: vec![Some(10)],
            },
        ];

        let mut bufs = MapsReadBuffers::default();
        for case in &cases {
            let mut fresh_budget = make_budget(&case.kind);
            let mut fresh_clock = case.script.clone().into_iter();
            let fresh = read_maps_or_refuse(Cursor::new(case.input), &mut fresh_budget, || {
                fresh_clock.next().unwrap_or(Some(0))
            });
            let fresh_io = fresh_budget.attempted_io_bytes();

            let mut reused_budget = make_budget(&case.kind);
            let mut reused_clock = case.script.clone().into_iter();
            let reused = read_maps_or_refuse_with_buffers(
                Cursor::new(case.input),
                &mut reused_budget,
                || reused_clock.next().unwrap_or(Some(0)),
                &mut bufs,
            );
            let reused_io = reused_budget.attempted_io_bytes();

            assert_eq!(
                reused, fresh,
                "{}: the reused-buffer read differs from the fresh read",
                case.name
            );
            assert_eq!(
                reused_io, fresh_io,
                "{}: the reused-buffer read charges different I/O",
                case.name
            );
        }
    }

    /// A maps buffer reused across reads is truncated between them: the
    /// second read sees only its own bytes, and neither allocation grows.
    /// (Mutation: dropping the truncate makes the short read return the
    /// long one's entries plus its own.)
    #[test]
    fn reused_maps_buffer_is_truncated_between_reads() {
        use std::io::Cursor;

        let long: &[u8] = b"7f0000000000-7f0000001000 r-xp 00000000 08:01 11 /a.so\n7f0000001000-7f0000002000 r--p 00001000 08:01 11 /a.so\n7f0000002000-7f0000003000 rw-p 00002000 00:00 0\n";
        let short: &[u8] = b"400000-401000 r-xp 00000000 08:01 22 /b\n";

        let mut bufs = MapsReadBuffers::default();
        let mut budget = CaptureWorkBudget::default();
        let first =
            read_maps_or_refuse_with_buffers(Cursor::new(long), &mut budget, || Some(0), &mut bufs)
                .unwrap();
        assert_eq!(first.len(), 3);
        let (bytes_cap, chunk_cap) = (bufs.bytes.capacity(), bufs.chunk.capacity());

        let mut budget = CaptureWorkBudget::default();
        let second = read_maps_or_refuse_with_buffers(
            Cursor::new(short),
            &mut budget,
            || Some(0),
            &mut bufs,
        )
        .unwrap();

        let mut budget = CaptureWorkBudget::default();
        let fresh = read_maps_or_refuse(Cursor::new(short), &mut budget, || Some(0)).unwrap();
        assert_eq!(
            second, fresh,
            "the reused buffer leaked the previous read into this one"
        );
        assert_eq!(second.len(), 1);
        assert_eq!(
            bufs.bytes.capacity(),
            bytes_cap,
            "the bytes buffer reallocated between reads"
        );
        assert_eq!(
            bufs.chunk.capacity(),
            chunk_cap,
            "the chunk buffer reallocated between reads"
        );
    }

    /// Heap allocations per 1,000 maps reads, fresh vs reused buffers (C7
    /// A2 measurement; the counter is per thread, so this runs in the
    /// default suite; `--nocapture` prints the counts). Counts the
    /// byte-read level only, so the delta is exactly the scratch reuse;
    /// parsing allocates identically on identical bytes. The reused
    /// buffers allocate once each, on the first read, and never again.
    #[test]
    fn maps_reuse_allocation_count_per_thousand_reads() {
        use std::io::Cursor;

        let line: &[u8] = b"7f0000000000-7f0000001000 r-xp 00000000 08:01 12345 /opt/p.so\n";
        let input = line.repeat(40);
        let read_fresh = || {
            let mut budget = CaptureWorkBudget::default();
            let (bytes, reasons) = read_maps_with_limits(
                Cursor::new(input.as_slice()),
                &mut budget,
                MAX_MAPS_BYTES,
                MAX_MAP_ENTRIES,
                64 * 1024,
                || Some(0),
            )
            .unwrap();
            assert!(reasons.is_empty());
            assert_eq!(bytes.len(), input.len());
        };
        let (_, fresh_allocs, fresh_bytes) = crate::test_alloc::count_allocs_during(|| {
            for _ in 0..1000 {
                read_fresh();
            }
        });

        let mut bufs = MapsReadBuffers::default();
        let (_, reused_allocs, reused_bytes) = crate::test_alloc::count_allocs_during(|| {
            for _ in 0..1000 {
                let mut budget = CaptureWorkBudget::default();
                let reasons = read_maps_bytes_with_buffers(
                    Cursor::new(input.as_slice()),
                    &mut budget,
                    MAX_MAPS_BYTES,
                    MAX_MAP_ENTRIES,
                    64 * 1024,
                    || Some(0),
                    &mut bufs,
                )
                .unwrap();
                assert!(reasons.is_empty());
                assert_eq!(bufs.bytes.len(), input.len());
            }
        });

        println!("fresh per 1000 reads: {fresh_allocs} allocs, {fresh_bytes} bytes");
        println!("reused per 1000 reads: {reused_allocs} allocs, {reused_bytes} bytes");
        assert!(
            fresh_allocs >= 2000,
            "a fresh read allocates its bytes and its chunk: {fresh_allocs}"
        );
        assert!(
            reused_allocs <= 2,
            "reused buffers allocate only on the first read: {reused_allocs}"
        );
    }

    /// Indicative wall time per 1,000 maps reads, fresh vs reused buffers
    /// (a criterion-free loop, not a benchmark; run single-threaded:
    /// `test -- --ignored maps_reuse_timing --test-threads=1 --nocapture`).
    #[test]
    #[ignore = "manual: indicative maps-reuse timing loop, no pass/fail bar; run by hand single-threaded"]
    fn maps_reuse_timing_per_thousand_reads() {
        use std::io::Cursor;
        use std::time::Instant;

        let line: &[u8] = b"7f0000000000-7f0000001000 r-xp 00000000 08:01 12345 /opt/p.so\n";
        let input = line.repeat(40);
        let fresh_once = || {
            let mut budget = CaptureWorkBudget::default();
            let (bytes, _) = read_maps_with_limits(
                Cursor::new(input.as_slice()),
                &mut budget,
                MAX_MAPS_BYTES,
                MAX_MAP_ENTRIES,
                64 * 1024,
                || Some(0),
            )
            .unwrap();
            assert_eq!(bytes.len(), input.len());
        };
        fresh_once();
        let start = Instant::now();
        for _ in 0..1000 {
            fresh_once();
        }
        let fresh = start.elapsed();

        let mut bufs = MapsReadBuffers::default();
        let start = Instant::now();
        for _ in 0..1000 {
            let mut budget = CaptureWorkBudget::default();
            let reasons = read_maps_bytes_with_buffers(
                Cursor::new(input.as_slice()),
                &mut budget,
                MAX_MAPS_BYTES,
                MAX_MAP_ENTRIES,
                64 * 1024,
                || Some(0),
                &mut bufs,
            )
            .unwrap();
            assert!(reasons.is_empty());
            assert_eq!(bufs.bytes.len(), input.len());
        }
        let reused = start.elapsed();

        println!(
            "fresh per 1000 reads: {fresh:?} ({:.1} ns/read)",
            fresh.as_nanos() as f64 / 1000.0
        );
        println!(
            "reused per 1000 reads: {reused:?} ({:.1} ns/read)",
            reused.as_nanos() as f64 / 1000.0
        );
    }

    #[derive(Debug)]
    enum ReaderStep {
        Bytes(Vec<u8>),
        Error(std::io::ErrorKind),
        Eof,
    }

    #[derive(Debug)]
    struct RecordingReader {
        steps: std::collections::VecDeque<ReaderStep>,
        requests: Vec<usize>,
    }

    impl RecordingReader {
        fn new(steps: impl IntoIterator<Item = ReaderStep>) -> Self {
            Self {
                steps: steps.into_iter().collect(),
                requests: Vec::new(),
            }
        }
    }

    impl Read for &mut RecordingReader {
        fn read(&mut self, buffer: &mut [u8]) -> std::io::Result<usize> {
            self.requests.push(buffer.len());
            match self.steps.pop_front().unwrap_or(ReaderStep::Eof) {
                ReaderStep::Bytes(bytes) => {
                    assert!(bytes.len() <= buffer.len());
                    buffer[..bytes.len()].copy_from_slice(&bytes);
                    Ok(bytes.len())
                }
                ReaderStep::Error(kind) => Err(std::io::Error::from(kind)),
                ReaderStep::Eof => Ok(0),
            }
        }
    }

    #[test]
    fn mountinfo_reader_ignores_small_per_object_legs_and_refuses_past_the_absolute_cap() {
        // Small per-object legs still read small tables: the mount table
        // is per-scan overhead (read once, cached, window-charged), so
        // gating it on the per-object leg would make small-but-legitimate
        // legs unusable on mount-heavy hosts.
        let mut exact =
            RecordingReader::new([ReaderStep::Bytes(b"abc\n".to_vec()), ReaderStep::Eof]);
        let mut budget = CaptureWorkBudget::new(ScanLimits {
            per_object_bytes: 4,
            total_bytes: 5,
        });
        assert_eq!(
            read_mountinfo_with(&mut exact, &mut budget, 8, |_| None).unwrap(),
            "abc\n"
        );
        assert_eq!(exact.requests, [5, 1], "the final request is EOF lookahead");
        assert_eq!(budget.attempted_io_bytes(), 4);

        // Past the absolute byte cap, the read refuses with the excess
        // byte charged. Eight full 8 MiB reads fill the cap; the ninth
        // single byte trips it.
        let mut steps = Vec::new();
        for _ in 0..8 {
            steps.push(ReaderStep::Bytes(vec![b'x'; 8 << 20]));
        }
        steps.push(ReaderStep::Bytes(vec![b'x'; 1]));
        let mut excess = RecordingReader::new(steps);
        let mut budget = CaptureWorkBudget::new(ScanLimits {
            per_object_bytes: 4,
            total_bytes: u64::MAX,
        });
        assert_eq!(
            read_mountinfo_with(&mut excess, &mut budget, 8 << 20, |_| None).unwrap_err(),
            MOUNTINFO_CEILING_REASON
        );
        assert_eq!(
            budget.attempted_io_bytes(),
            MAX_MOUNTINFO_BYTES + 1,
            "the excess byte is charged"
        );
    }

    #[test]
    fn mountinfo_reader_charges_lines_and_reused_aggregate_budget() {
        let exact_lines = vec![b'\n'; MAX_MOUNTINFO_ENTRIES];
        let mut exact = RecordingReader::new([ReaderStep::Bytes(exact_lines), ReaderStep::Eof]);
        let mut budget = CaptureWorkBudget::default();
        assert!(read_mountinfo_with(&mut exact, &mut budget, 2 * 1024 * 1024, |_| None).is_ok());
        let first_bytes = budget.attempted_io_bytes();
        assert_eq!(exact.requests.len(), 2);

        let mut excess =
            RecordingReader::new([ReaderStep::Bytes(vec![b'\n'; MAX_MOUNTINFO_ENTRIES + 1])]);
        assert_eq!(
            read_mountinfo_with(&mut excess, &mut budget, 2 * 1024 * 1024, |_| None).unwrap_err(),
            MOUNTINFO_ENTRY_CEILING_REASON
        );
        assert_eq!(
            budget.attempted_io_bytes(),
            first_bytes + u64::try_from(MAX_MOUNTINFO_ENTRIES + 1).unwrap()
        );
    }

    #[test]
    fn mountinfo_reader_retries_interrupted_reads_but_refuses_other_partial_errors() {
        let mut interrupted = RecordingReader::new([
            ReaderStep::Bytes(b"17 ".to_vec()),
            ReaderStep::Error(std::io::ErrorKind::Interrupted),
            ReaderStep::Bytes(b"1\n".to_vec()),
            ReaderStep::Eof,
        ]);
        let mut budget = CaptureWorkBudget::default();
        assert_eq!(
            read_mountinfo_with(&mut interrupted, &mut budget, 3, |_| None).unwrap(),
            "17 1\n"
        );
        assert_eq!(interrupted.requests.len(), 4, "EINTR and EOF are attempts");
        assert_eq!(budget.attempted_io_bytes(), 5);
        assert_eq!(
            budget.work_units_count(),
            5,
            "four attempts plus one observed line"
        );

        let mut failed = RecordingReader::new([
            ReaderStep::Bytes(b"17 1 8:1 /".to_vec()),
            ReaderStep::Error(std::io::ErrorKind::Other),
        ]);
        let mut budget = CaptureWorkBudget::default();
        assert!(read_mountinfo_with(&mut failed, &mut budget, 32, |_| None).is_err());
        assert_eq!(failed.requests.len(), 2);
        assert_eq!(budget.attempted_io_bytes(), 10);
    }

    #[test]
    fn mountinfo_reader_never_reads_after_exhaustion_and_rechecks_deadline_before_publish() {
        for mut budget in [
            CaptureWorkBudget::new(ScanLimits {
                per_object_bytes: 0,
                total_bytes: 8,
            }),
            CaptureWorkBudget::new(ScanLimits {
                per_object_bytes: 8,
                total_bytes: 0,
            }),
        ] {
            let mut reader = RecordingReader::new([ReaderStep::Bytes(b"x".to_vec())]);
            assert!(read_mountinfo_with(&mut reader, &mut budget, 8, |_| None).is_err());
            assert!(reader.requests.is_empty());
        }

        let mut aggregate_exact =
            RecordingReader::new([ReaderStep::Bytes(b"abc\n".to_vec()), ReaderStep::Eof]);
        let mut budget = CaptureWorkBudget::new(ScanLimits {
            per_object_bytes: 4,
            total_bytes: 4,
        });
        assert_eq!(
            read_mountinfo_with(&mut aggregate_exact, &mut budget, 8, |_| None).unwrap_err(),
            IO_CEILING_REASON
        );
        assert_eq!(
            aggregate_exact.requests,
            [4],
            "aggregate exhaustion refuses without an EOF probe"
        );
        assert_eq!(budget.attempted_io_bytes(), 4);

        let mut budget = CaptureWorkBudget::default();
        assert!(!budget.charge(u64::MAX));
        let mut stopped = RecordingReader::new([ReaderStep::Bytes(b"x".to_vec())]);
        assert_eq!(
            read_mountinfo_with(&mut stopped, &mut budget, 8, |_| None).unwrap_err(),
            WORK_CEILING_REASON
        );
        assert!(stopped.requests.is_empty());

        let mut deadline =
            RecordingReader::new([ReaderStep::Bytes(b"17 1\n".to_vec()), ReaderStep::Eof]);
        let mut budget = CaptureWorkBudget::default();
        let mut polls = 0;
        let error = read_mountinfo_with(&mut deadline, &mut budget, 8, |_| {
            polls += 1;
            (polls == 3).then_some(SCAN_DEADLINE_REASON)
        })
        .unwrap_err();
        assert_eq!(error, SCAN_DEADLINE_REASON);
        assert_eq!(deadline.requests.len(), 2);
        assert_eq!(polls, 3, "before each read and after EOF publication");

        let mut between = RecordingReader::new([
            ReaderStep::Bytes(b"17 ".to_vec()),
            ReaderStep::Bytes(b"1\n".to_vec()),
        ]);
        let mut budget = CaptureWorkBudget::default();
        let mut polls = 0;
        assert_eq!(
            read_mountinfo_with(&mut between, &mut budget, 3, |_| {
                polls += 1;
                (polls == 2).then_some(SCAN_DEADLINE_REASON)
            })
            .unwrap_err(),
            SCAN_DEADLINE_REASON
        );
        assert_eq!(between.requests.len(), 1, "expiry prevents the next chunk");
    }

    /// Fix A: admission charges each unique table once. Byte-identical
    /// repeats skip the candidate charge but still decode (per-view results
    /// are never served from a cache); byte-different tables charge again.
    #[test]
    fn repeat_table_bytes_skip_the_candidate_charge_but_still_decode() {
        fn table_snapshot(version: u64, fields: usize) -> Vec<u8> {
            let mut snapshot = vec![0u8; 8 + fields * 8];
            snapshot[..8].copy_from_slice(&version.to_le_bytes());
            for slot in 0..fields {
                let at = 8 + slot * 8;
                snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_le_bytes());
            }
            snapshot
        }

        let maps = parse_maps(
            b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n\
              7000-9000 r--p 00001000 08:01 7 /lib/provider.so\n",
        )
        .unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let mut budget = CaptureWorkBudget::default();

        let first_snapshot = table_snapshot(0x0203, 104);
        let first = decode_exact_table(
            &first_snapshot,
            0x7000,
            LinuxLayout::Lp64,
            &map_index,
            &mut budget,
            None,
        )
        .expect("a valid table decodes")
        .expect("all slots walkable");
        assert_eq!(budget.table_candidates_count(), 1);

        let repeat = decode_exact_table(
            &first_snapshot,
            0x7000,
            LinuxLayout::Lp64,
            &map_index,
            &mut budget,
            None,
        )
        .expect("a valid table decodes")
        .expect("the repeat decodes too, never from a cache");
        assert_eq!(repeat, first);
        assert_eq!(
            budget.table_candidates_count(),
            1,
            "byte-identical repeats must not burn another candidate"
        );

        let other_snapshot = table_snapshot(0x0003, 92);
        let other = decode_exact_table(
            &other_snapshot,
            0x7000,
            LinuxLayout::Lp64,
            &map_index,
            &mut budget,
            None,
        )
        .expect("a valid table decodes")
        .expect("different bytes decode");
        assert_ne!(other.version, first.version);
        assert_eq!(
            budget.table_candidates_count(),
            2,
            "byte-different tables burn again"
        );
    }

    // Two scans, one file: authored maps reference a real copied binary so the
    // ELF-snapshot read has real bytes to charge. Executable mapping only: the
    // group carries code (candidate_groups keeps it) but no readable data
    // pages, so no target-memory reads pollute the per-scan I/O delta.
    struct ElfExportFactsFixture {
        _dir: tempfile::TempDir,
        path: PathBuf,
        maps: String,
        mem: File,
        next_view: u32,
    }

    impl ScanIo for ElfExportFactsFixture {
        type Memory = File;
        fn open_maps(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<Box<dyn Read>> {
            Ok(Box::new(std::io::Cursor::new(
                self.maps.clone().into_bytes(),
            )))
        }
        fn open_mem(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<File> {
            self.mem.try_clone()
        }
        fn final_generation(
            &mut self,
            view: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> Result<(), String> {
            view.run_while_same(|| ())
        }
    }

    impl ElfExportFactsFixture {
        fn new() -> Self {
            let dir = tempfile::tempdir().unwrap();
            let path = dir.path().join("provider.so");
            std::fs::copy("/bin/sh", &path).unwrap();
            Self::wrap(dir, path)
        }

        /// A real hook-exporting provider, so sparse tests pin facts — not
        /// just the absence of facts — on files past the old whole-size gate.
        fn new_provider() -> Self {
            let dir = tempfile::tempdir().unwrap();
            let c = dir.path().join("provider.c");
            let path = dir.path().join("provider.so");
            std::fs::write(
                &c,
                "unsigned long C_GetFunctionList(void **p){(void)p;return 0;}\n\
                 unsigned long NSC_GetFunctionList(void **p){(void)p;return 0;}\n",
            )
            .unwrap();
            let ok = std::process::Command::new("gcc")
                .args(["-shared", "-fPIC", "-o"])
                .arg(&path)
                .arg(&c)
                .status()
                .unwrap()
                .success();
            assert!(ok, "gcc failed for the provider fixture");
            Self::wrap(dir, path)
        }

        fn wrap(dir: tempfile::TempDir, path: PathBuf) -> Self {
            let view = ProcessView::open(ProcessViewId(71), std::process::id()).unwrap();
            let file = File::open(&path).unwrap();
            let key = crate::discovery::identity::retained_object_key(
                &view,
                &file,
                &mut CaptureWorkBudget::default(),
            )
            .unwrap();
            let maps = format!(
                "1000-2000 r-xp 00000000 {:x}:{:x} {} {}\n",
                key.device.major,
                key.device.minor,
                key.inode,
                path.display(),
            );
            let mem = tempfile::tempfile().unwrap();
            mem.set_len(0x2000).unwrap();
            Self {
                _dir: dir,
                path,
                maps,
                mem,
                next_view: 72,
            }
        }

        fn scan(&mut self, budget: &mut CaptureWorkBudget) -> ScanOutcome {
            let id = self.next_view;
            self.next_view += 1;
            let view = ProcessView::open(ProcessViewId(id), std::process::id()).unwrap();
            let hints = [self.path.clone()];
            let hooks = HookRegistry::builtin();
            scan_process_view_with_io(
                &ScanRequest {
                    pid: view.pid(),
                    hints: &hints,
                    hooks: &hooks,
                },
                &view,
                budget,
                self,
            )
            .unwrap()
        }
    }

    #[test]
    fn second_view_of_same_file_reads_no_elf_bytes() {
        let mut fixture = ElfExportFactsFixture::new();
        let file_len = std::fs::metadata(&fixture.path).unwrap().len();
        assert!(file_len > 0, "the fixture must have bytes worth caching");
        let mut budget = CaptureWorkBudget::default();

        // First scan reads the sparse ELF tables (plus maps and the mount table).
        let first = fixture.scan(&mut budget);
        let charged_first = budget.attempted_io_bytes();
        assert!(
            charged_first < file_len,
            "first scan charges sparse ELF tables, not the whole file: \
             {charged_first} < {file_len}"
        );
        assert_eq!(first.modules().len(), 1, "skipped: {:?}", first.skipped());

        // Second scan of the same file: maps/mountinfo bytes only, no ELF re-read.
        let second = fixture.scan(&mut budget);
        let charged_second = budget.attempted_io_bytes() - charged_first;
        assert_eq!(second.modules().len(), 1, "skipped: {:?}", second.skipped());
        assert_eq!(
            second.modules()[0].decoder_abi,
            first.modules()[0].decoder_abi,
            "both scans report the same ABI"
        );
        assert_eq!(
            second.modules()[0].exports,
            first.modules()[0].exports,
            "both scans report the same export names"
        );
        assert!(
            charged_second < file_len,
            "second scan must not re-read {file_len} ELF bytes (charged {charged_second})"
        );
        assert!(
            charged_second < charged_first,
            "the cache hit charges no ELF bytes: {charged_second} < {charged_first}"
        );
    }

    #[test]
    fn changed_file_rereads_elf() {
        use std::io::Write as _;

        let mut fixture = ElfExportFactsFixture::new();
        let mut budget = CaptureWorkBudget::default();
        let first = fixture.scan(&mut budget);
        assert_eq!(first.modules().len(), 1, "skipped: {:?}", first.skipped());
        let charged_first = budget.attempted_io_bytes();

        // A size-changing rewrite between scans (same path and inode).
        let mut rewritten = std::fs::OpenOptions::new()
            .append(true)
            .open(&fixture.path)
            .unwrap();
        rewritten.write_all(&[0; 1024]).unwrap();
        drop(rewritten);
        let new_len = std::fs::metadata(&fixture.path).unwrap().len();

        // A changed file misses the cache: the ELF tables are read and charged again.
        let second = fixture.scan(&mut budget);
        let charged_second = budget.attempted_io_bytes() - charged_first;
        assert!(
            charged_second < new_len,
            "changed file is re-read sparsely: {charged_second} < {new_len}"
        );
        assert_eq!(second.modules().len(), 1, "skipped: {:?}", second.skipped());

        // A third scan hits the new pin: strictly fewer bytes than the re-read.
        let third = fixture.scan(&mut budget);
        let charged_third = budget.attempted_io_bytes() - charged_first - charged_second;
        assert_eq!(third.modules().len(), 1, "skipped: {:?}", third.skipped());
        assert!(
            charged_third < charged_second,
            "the re-read tables are cached again: {charged_third} < {charged_second}"
        );

        // The reported facts come from the new bytes, not the cached read.
        let file = File::open(&fixture.path).unwrap();
        let snapshot = ElfSnapshot::read(&file).unwrap();
        let hooks = HookRegistry::builtin();
        let wanted = hooks.names();
        let expected: Vec<String> = snapshot
            .exports_matching(&wanted)
            .unwrap()
            .into_iter()
            .map(|(name, _)| name)
            .collect();
        assert_eq!(second.modules()[0].decoder_abi, Some(snapshot.abi()));
        assert_eq!(second.modules()[0].exports, expected);
    }

    #[test]
    fn oversize_file_exports_are_checked_sparsely() {
        // A hook-exporting provider sparsely extended past the
        // per-operation allowance (the libxul shape): the export check
        // still reports facts, charging tables rather than the file.
        // Explicit small limits keep the fixture fast.
        let mut fixture = ElfExportFactsFixture::new_provider();
        let oversize = 2 * 1024 * 1024;
        std::fs::OpenOptions::new()
            .write(true)
            .open(&fixture.path)
            .unwrap()
            .set_len(oversize)
            .unwrap();
        let file_len = std::fs::metadata(&fixture.path).unwrap().len();
        let limits = ScanLimits {
            per_object_bytes: 1024 * 1024,
            total_bytes: u64::MAX,
        };
        assert!(file_len > limits.per_object_bytes);

        let mut budget = CaptureWorkBudget::new(limits);
        let outcome = fixture.scan(&mut budget);
        assert_eq!(
            outcome.modules().len(),
            1,
            "skipped: {:?}",
            outcome.skipped()
        );
        assert!(
            !outcome.modules()[0].exports.is_empty(),
            "hook exports must be reported past the per-object cap"
        );
        assert!(
            outcome
                .skipped()
                .iter()
                .all(|skip| !skip.reason.contains("too_large")),
            "no whole-size gate on the export check: {:?}",
            outcome.skipped()
        );
        assert!(
            budget.attempted_io_bytes() < file_len,
            "charged bytes must be tables, not the {file_len}-byte file: {}",
            budget.attempted_io_bytes()
        );
    }

    #[test]
    fn sparse_read_charges_bounded_bytes() {
        // A 2 MiB provider: a whole-file read would charge megabytes, while
        // the export tables cost kilobytes.
        let mut fixture = ElfExportFactsFixture::new_provider();
        std::fs::OpenOptions::new()
            .write(true)
            .open(&fixture.path)
            .unwrap()
            .set_len(2 * 1024 * 1024)
            .unwrap();

        let mut budget = CaptureWorkBudget::default();
        let outcome = fixture.scan(&mut budget);
        assert_eq!(
            outcome.modules().len(),
            1,
            "skipped: {:?}",
            outcome.skipped()
        );
        assert!(
            !outcome.modules()[0].exports.is_empty(),
            "hook exports must be reported"
        );
        assert!(
            budget.attempted_io_bytes() < 1024 * 1024,
            "first scan must charge ELF tables, not the 2 MiB file: {}",
            budget.attempted_io_bytes()
        );
    }

    #[test]
    fn retained_export_reads_preserve_getter_facts_and_refuse_exhausted_budgets() {
        let fixture = ElfExportFactsFixture::new_provider();
        let file = File::open(&fixture.path).unwrap();
        let size = file.metadata().unwrap().len();
        let wanted = ["C_GetFunctionList", "NSC_GetFunctionList", "not_exported"];
        let (abi, exports, _) = p11scope_manifest::elf::read_export_facts(&file, &wanted).unwrap();
        assert_eq!(exports.len(), 2, "standard and vendor getter controls");

        let mut budget = CaptureWorkBudget::new(ScanLimits {
            per_object_bytes: size,
            total_bytes: size,
        });
        assert_eq!(
            read_retained_export_facts_budgeted(&file, &wanted, &mut budget).unwrap(),
            (abi, exports.clone())
        );
        assert_eq!(budget.attempted_io_bytes(), size);

        let mut bounded = CaptureWorkBudget::new(ScanLimits {
            per_object_bytes: size,
            total_bytes: size - 1,
        });
        let error = read_retained_export_facts_budgeted(&file, &wanted, &mut bounded).unwrap_err();
        assert!(error.contains(IO_CEILING_REASON), "{error}");
        assert_eq!(bounded.attempted_io_bytes(), size - 1);

        let mut expired = CaptureWorkBudget::default();
        expired.set_deadline(Some(0));
        let error = read_retained_export_facts_budgeted(&file, &wanted, &mut expired).unwrap_err();
        assert!(error.contains(SCAN_DEADLINE_REASON), "{error}");
        assert_eq!(expired.attempted_io_bytes(), 0);

        let mut inventory = CaptureWorkBudget::for_inventory(inventory_limits(size, 2, 1, 1, 1, 1));
        assert!(read_retained_export_facts_budgeted(&file, &wanted, &mut inventory).is_err());
        assert_eq!(inventory.attempted_io_bytes(), 0, "no active scan");
        let window = inventory.begin_window(WindowId::new(1), u64::MAX).unwrap();
        let scan = inventory.checkpoint(window.clone()).unwrap();
        assert_eq!(
            read_retained_export_facts_budgeted(&file, &wanted, &mut inventory).unwrap(),
            (abi, exports)
        );
        assert_eq!(inventory.attempted_io_bytes(), size);
        let error =
            read_retained_export_facts_budgeted(&file, &wanted, &mut inventory).unwrap_err();
        assert!(error.contains(IO_CEILING_REASON), "{error}");
        assert_eq!(inventory.attempted_io_bytes(), size);
        inventory.finish_scan(scan).unwrap();
        inventory.finish_window(window).unwrap();
    }

    #[test]
    fn sparse_export_charge_applies_capture_ceiling_post_hoc() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("provider.so");
        std::fs::copy("/bin/sh", &path).unwrap();
        let file = File::open(&path).unwrap();
        let hooks = HookRegistry::builtin();
        let wanted = hooks.names();

        // No room for even the ELF header: the identical ceiling skip today's
        // mid-read abort produces, with the budget saturated as today.
        let mut budget = CaptureWorkBudget::new(ScanLimits {
            per_object_bytes: u64::MAX,
            total_bytes: 10,
        });
        let error = read_export_facts_budgeted(&file, &wanted, &mut budget).unwrap_err();
        assert_eq!(error, format!("read failed: {IO_CEILING_REASON}"));
        assert_eq!(budget.attempted_io_bytes(), 10);

        // Room for the tables: bounded bytes charged, facts equal the oracle.
        let mut budget = CaptureWorkBudget::new(ScanLimits {
            per_object_bytes: u64::MAX,
            total_bytes: u64::MAX,
        });
        let (abi, exports) = read_export_facts_budgeted(&file, &wanted, &mut budget).unwrap();
        let charged = budget.attempted_io_bytes();
        assert!(
            charged > 0 && charged < 1024 * 1024,
            "the tables must cost bounded bytes: {charged}"
        );
        let snapshot = ElfSnapshot::read(&file).unwrap();
        assert_eq!(abi, snapshot.abi());
        assert_eq!(exports, snapshot.exports_matching(&wanted).unwrap());
    }

    /// A3-M1 hardening: a failed post-read re-pin refuses with the pin's own
    /// I/O message — never folded into the changed-file retry. `before` and
    /// the mismatching pin are real `pin_of` values from two files (distinct
    /// inodes, so deterministically unequal); the I/O error carries `pin_of`'s
    /// verbatim `fstat failed` shape. (An end-to-end injection would need an
    /// fd-closing hook — racy under parallel tests — or a `pin_of` seam, so
    /// the decision itself is pinned here; the call-site wiring is enforced
    /// by the dead-code lint denying an uncalled helper.)
    #[test]
    fn post_read_pin_io_error_reports_its_own_message() {
        let dir = tempfile::tempdir().unwrap();
        let first = dir.path().join("first.so");
        let second = dir.path().join("second.so");
        std::fs::copy("/bin/sh", &first).unwrap();
        std::fs::copy("/bin/sh", &second).unwrap();
        let before = pin_of(&File::open(&first).unwrap()).unwrap();
        let other = pin_of(&File::open(&second).unwrap()).unwrap();
        assert_ne!(other, before, "distinct files pin distinctly");

        // The I/O arm: a failed re-pin reports its own message, still refused.
        let io = "fstat failed: simulated I/O failure".to_string();
        assert_eq!(
            check_pin_after_read(Err(io.clone()), &before),
            Err(io),
            "a pin I/O error must not be misdescribed as a change"
        );
        // The refusal arm: a changed file keeps the retry message.
        assert_eq!(
            check_pin_after_read(Ok(other), &before),
            Err("file changed while it was being scanned - retry".to_string())
        );
        // The stable arm: an unchanged file passes with no refusal.
        assert_eq!(check_pin_after_read(Ok(before), &before), Ok(()));
    }

    /// SYSPLAN E07: a saturated table budget must still recognize unchanged
    /// repeats. 512 distinct candidate tables sharing one endpoint set fill
    /// the ceiling; an unchanged rescan of two of them must decode both with
    /// no new charges and no exhaustion evidence — budget-limited absence
    /// must never look like the tables disappeared.
    #[test]
    fn e07_saturated_table_budget_still_recognizes_unchanged_repeats() {
        let maps = parse_maps(
            b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n\
              7000-80000 r--p 00001000 08:01 7 /lib/provider.so\n",
        )
        .unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let table_len = 8 + 104 * 8;
        let mut snapshot = vec![0u8; 512 * table_len];
        for table in 0..512 {
            let base = table * table_len;
            snapshot[base..base + 8].copy_from_slice(&0x0203u64.to_ne_bytes());
            for slot in 0..104 {
                let at = base + 8 + slot * 8;
                snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_ne_bytes());
            }
        }
        let mut budget = CaptureWorkBudget::default();
        let (tables, skipped) = detect_tables(&snapshot, 0x7000, &map_index, &mut budget);
        assert_eq!(tables.len(), 512, "all distinct candidates decode");
        assert!(
            skipped.is_empty(),
            "exactly filling the ceiling refuses nothing: {skipped:?}"
        );
        assert_eq!(budget.table_candidates_count(), 512);
        assert!(
            tables
                .windows(2)
                .all(|pair| pair[0].entries == pair[1].entries),
            "512 candidate tables share few endpoints"
        );

        // An unchanged rescan of two of the same tables at their own
        // addresses: repeats, recognized under the saturated cap.
        let rescan = snapshot[..2 * table_len].to_vec();
        let (repeated, rescan_skipped) = detect_tables(&rescan, 0x7000, &map_index, &mut budget);
        assert_eq!(
            repeated.len(),
            2,
            "an unchanged rescan under a saturated cap still decodes its repeats"
        );
        assert_eq!(repeated[0], tables[0]);
        assert_eq!(repeated[1], tables[1]);
        assert_eq!(
            budget.table_candidates_count(),
            512,
            "repeats must not burn new candidates"
        );
        assert!(
            rescan_skipped.is_empty(),
            "nothing new was refused, so no exhaustion evidence is owed: {rescan_skipped:?}"
        );
    }

    /// SYSPLAN E09: one unchanged interface rescanned 513 times charges the
    /// 512-record lifetime allowance once. Attempted I/O and work accrue on
    /// every rescan — uniqueness deduplicates cardinality, never work.
    #[test]
    fn e09_repeated_interface_rescans_charge_once_but_work_every_time() {
        let maps = parse_maps(
            b"0-1000 r--p 00000000 08:01 7 /lib/provider.so\n\
              1000-3000 r-xp 00001000 08:01 7 /lib/provider.so\n\
              7000-9000 r--p 00002000 08:01 7 /lib/provider.so\n",
        )
        .unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let name_file = tempfile::NamedTempFile::new().unwrap();
        std::fs::write(name_file.path(), b"_PKCS 11\0").unwrap();
        let mem = File::open(name_file.path()).unwrap();
        let table = ScannedTable {
            version: (2, 40),
            walk: "full",
            entries: Vec::new(),
            null_entries: Vec::new(),
            unpinned: Vec::new(),
            address: 0x7000,
            file_offset: Some(0x2000),
            live_return: false,
            manifest_supported: false,
            extension_impossible: false,
        };
        let mut snapshot = vec![0u8; INTERFACE_BYTES];
        snapshot[..WORD].copy_from_slice(&1u64.to_ne_bytes());
        snapshot[WORD..2 * WORD].copy_from_slice(&table.address.to_ne_bytes());
        let key = ObjectKey::of(&maps[0]);
        let mut budget = CaptureWorkBudget::default();

        let mut first_io = 0;
        for scan in 0..513 {
            let mut operation_bytes = 0;
            let (interfaces, skipped) = scan_interfaces(
                &snapshot,
                &mem,
                std::slice::from_ref(&table),
                &map_index,
                key,
                &mut budget,
                &mut operation_bytes,
            );
            assert_eq!(
                interfaces.len(),
                1,
                "rescan {scan}: the unchanged interface still decodes"
            );
            assert_eq!(interfaces[0].name_class, "exact_standard");
            assert!(
                skipped.is_empty(),
                "rescan {scan}: a repeat refuses nothing: {skipped:?}"
            );
            if scan == 0 {
                first_io = budget.attempted_io_bytes();
                assert!(first_io > 0, "the name read charges attempted I/O");
            }
        }
        assert_eq!(
            budget.interface_records_count(),
            1,
            "513 rescans of one interface consume one lifetime record"
        );
        assert_eq!(
            budget.attempted_io_bytes(),
            513 * first_io,
            "attempted I/O accrues per rescan, independent of uniqueness"
        );
        assert_eq!(
            budget.work_units_count(),
            513,
            "work accrues per rescan, independent of uniqueness"
        );
    }

    /// SYSPLAN E09 countercontrol: a changed table at a reused address is a
    /// new interface, not a repeat — while a genuine repeat across processes
    /// sharing one provider inode stays free.
    #[test]
    fn e09_changed_table_at_a_reused_address_charges_again() {
        let maps = parse_maps(
            b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n\
              7000-9000 r--p 00001000 08:01 7 /lib/provider.so\n",
        )
        .unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let table_v2 = ScannedTable {
            version: (2, 3),
            walk: "full",
            entries: Vec::new(),
            null_entries: Vec::new(),
            unpinned: Vec::new(),
            address: 0x7000,
            file_offset: Some(0),
            live_return: false,
            manifest_supported: false,
            extension_impossible: false,
        };
        let mut table_v3 = table_v2.clone();
        table_v3.version = (3, 2);
        let mut snapshot = vec![0u8; INTERFACE_BYTES];
        snapshot[WORD..2 * WORD].copy_from_slice(&0x7000u64.to_ne_bytes());
        let mem = tempfile::tempfile().unwrap();
        let key = ObjectKey::of(&maps[0]);
        let mut budget = CaptureWorkBudget::default();
        let mut operation_bytes = 0;

        let (first, skipped) = scan_interfaces(
            &snapshot,
            &mem,
            std::slice::from_ref(&table_v2),
            &map_index,
            key,
            &mut budget,
            &mut operation_bytes,
        );
        assert_eq!(first.len(), 1);
        assert!(skipped.is_empty());
        assert_eq!(budget.interface_records_count(), 1);

        // Same address, changed table: a new interface, charged again.
        let (changed, skipped) = scan_interfaces(
            &snapshot,
            &mem,
            std::slice::from_ref(&table_v3),
            &map_index,
            key,
            &mut budget,
            &mut operation_bytes,
        );
        assert_eq!(changed.len(), 1, "the changed table still decodes");
        assert!(skipped.is_empty());
        assert_eq!(
            budget.interface_records_count(),
            2,
            "a changed table at a reused address is not a false repeat"
        );

        // The original table again: a genuine repeat, free.
        let (repeat, skipped) = scan_interfaces(
            &snapshot,
            &mem,
            std::slice::from_ref(&table_v2),
            &map_index,
            key,
            &mut budget,
            &mut operation_bytes,
        );
        assert_eq!(repeat.len(), 1);
        assert!(skipped.is_empty());
        assert_eq!(
            budget.interface_records_count(),
            2,
            "a genuine repeat must not burn another record"
        );
    }

    /// SYSPLAN E09 runtime countercontrol: anonymous tables have no stable
    /// file owner, so their interfaces are scoped to one process generation
    /// and sensitive to content — a freed slot reallocated with different
    /// entries at a reused address charges again.
    #[test]
    fn e09_runtime_interface_repeats_are_view_scoped_and_content_sensitive() {
        let maps = parse_maps(
            b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n\
              7000-9000 rw-p 00000000 00:00 0\n",
        )
        .unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let entry = |file_offset: u64| ScannedEntry {
            name: function_name(0).unwrap(),
            object: ObjectKey::of(&maps[0]),
            object_path: "/lib/provider.so".to_string(),
            file_offset,
        };
        let table = ScannedTable {
            version: (2, 3),
            walk: "full",
            entries: vec![entry(0x100)],
            null_entries: vec![function_name(1).unwrap()],
            unpinned: Vec::new(),
            address: 0x7000,
            file_offset: None,
            live_return: false,
            manifest_supported: false,
            extension_impossible: false,
        };
        let mut changed = table.clone();
        changed.entries = vec![entry(0x200)];
        let mut snapshot = vec![0u8; INTERFACE_BYTES];
        snapshot[WORD..2 * WORD].copy_from_slice(&0x7000u64.to_ne_bytes());
        let mem = tempfile::tempfile().unwrap();
        let key = ObjectKey::of(&maps[0]);
        let mut budget = CaptureWorkBudget::default();
        let mut operation_bytes = 0;
        let scan = |budget: &mut CaptureWorkBudget,
                    operation_bytes: &mut u64,
                    tables: &[ScannedTable],
                    view: ProcessViewId|
         -> usize {
            let (interfaces, skipped) = scan_interfaces_for_layout(
                LinuxLayout::Lp64,
                &snapshot,
                0,
                &mem,
                tables,
                &map_index,
                key,
                budget,
                operation_bytes,
                Some(view),
            );
            assert_eq!(interfaces.len(), 1, "every scan still decodes");
            assert!(skipped.is_empty(), "{skipped:?}");
            budget.interface_records_count()
        };

        assert_eq!(
            scan(
                &mut budget,
                &mut operation_bytes,
                std::slice::from_ref(&table),
                ProcessViewId(0)
            ),
            1
        );
        assert_eq!(
            scan(
                &mut budget,
                &mut operation_bytes,
                std::slice::from_ref(&table),
                ProcessViewId(0)
            ),
            1,
            "an unchanged repeat in the same generation is free"
        );
        assert_eq!(
            scan(
                &mut budget,
                &mut operation_bytes,
                std::slice::from_ref(&table),
                ProcessViewId(1)
            ),
            2,
            "a new process generation is not a repeat"
        );
        assert_eq!(
            scan(
                &mut budget,
                &mut operation_bytes,
                &[changed],
                ProcessViewId(1)
            ),
            3,
            "changed entries at a reused address charge again"
        );
    }

    /// The scan-to-live-candidate boundary: only verified absence is benign.
    /// Every bounded/incomplete outcome — ceilings, stops, refusals, partial
    /// reads — truncates, and unknown future reasons fail closed.
    #[test]
    fn no_table_skip_reason_ends_with_the_discover_action() {
        assert_eq!(
            no_table_found_reason("/usr/lib64/pkcs11/libsofthsm2.so", false),
            "no function table was found in its file-backed data; a table built at run time in \
             .bss or on the heap is outside the memory scan's reach; to observe it, run \
             p11scope-discover --module /usr/lib64/pkcs11/libsofthsm2.so -o <manifest.json> and \
             pass --manifest <manifest.json>"
        );
        let hinted = no_table_found_reason("/opt/p11.so", true);
        assert!(
            hinted.starts_with("matched a --module hint; "),
            "{hinted:?} must keep the hint prefix"
        );
        assert!(
            hinted.ends_with(
                "; to observe it, run p11scope-discover --module /opt/p11.so -o <manifest.json> \
                 and pass --manifest <manifest.json>"
            ),
            "{hinted:?} must end with the action naming its own path"
        );
        assert!(!hinted.contains('\n'), "{hinted:?} must stay one line");
    }

    #[test]
    fn no_table_found_reason_quotes_paths_needing_shell_quoting() {
        let spaced = no_table_found_reason("/opt/my providers/p11.so", false);
        assert!(
            spaced.ends_with(
                "; to observe it, run p11scope-discover --module '/opt/my providers/p11.so' -o \
                 <manifest.json> and pass --manifest <manifest.json>"
            ),
            "{spaced:?} must quote a path with spaces"
        );
        assert!(!spaced.contains('\n'), "{spaced:?} must stay one line");
        let quoted = no_table_found_reason("/opt/p11's;rm/x.so", false);
        assert!(
            quoted.contains("--module '/opt/p11'\\''s;rm/x.so' -o"),
            "{quoted:?} must escape the quote and stay one shell word"
        );
    }

    #[test]
    fn scan_skip_truncation_classifier_marks_only_verified_absence_benign() {
        let mut budget = CaptureWorkBudget::default();
        let table_reason = budget.table_exhaustion_reason().unwrap();
        let interface_reason = budget.interface_exhaustion_reason().unwrap();
        let undecoded_reason = undecoded_file_reason(&budget);
        let truncating = [
            IO_CEILING_REASON,
            WORK_CEILING_REASON,
            SCAN_DEADLINE_REASON,
            SCAN_CLOCK_REASON,
            MAPS_CEILING_REASON,
            MAPS_ENTRY_CEILING_REASON,
            MOUNTINFO_CEILING_REASON,
            MOUNTINFO_ENTRY_CEILING_REASON,
            table_reason.as_str(),
            interface_reason.as_str(),
            undecoded_reason.as_str(),
            "too_large (123 bytes; per-object cap is 456)",
            MAPPING_CHANGED_REASON,
            "memory scan refused: final mapping validation unavailable: gone",
            "memory scan refused: initial mapping validation unavailable: gone",
            "memory scan refused: process generation changed during acquisition: gone",
            "file changed while it was being scanned - retry",
            "partial snapshot of one data mapping: read 3 of 9 bytes: the read failed: gone",
            // Owner rule 2026-11-09 (data-always): a deleted mapping may
            // still carry executable code, so it truncates — never
            // verified absence.
            "deleted mapping",
            REPLACED_PROVIDER_REASON,
            // Owner-approved 2026-09-27: F-14's version skip is retired, so
            // its constant is gone; fail-closed coverage stays via the
            // unknown-reason entry below.
            "some future reason",
        ];
        for reason in truncating {
            assert!(
                scan_skip_truncates(reason),
                "{reason:?} must truncate the scan it came from"
            );
        }
        let plain = no_table_found_reason("/opt/p11.so", false);
        let hinted = no_table_found_reason("/opt/p11.so", true);
        let benign = [
            plain.as_str(),
            hinted.as_str(),
            "not mapped in the target",
            "no absolute pathname in /proc/<pid>/maps",
            "ambiguous \\012 pathname",
            "non-UTF-8 pathname",
        ];
        for reason in benign {
            assert!(
                !scan_skip_truncates(reason),
                "{reason:?} is verified absence, not truncation"
            );
        }
    }

    /// The replaced-file reason stays neutral: the scan skipped before it
    /// opened the file, so it must not claim the mapping is (or is not) a
    /// provider. Pinned byte-exactly; renderers match this text.
    #[test]
    fn replaced_provider_reason_stays_neutral_and_truncating() {
        assert_eq!(
            REPLACED_PROVIDER_REASON,
            "replaced on disk while running; not examined, calls not counted"
        );
        assert!(
            scan_skip_truncates(REPLACED_PROVIDER_REASON),
            "the neutral wording must still truncate coverage"
        );
    }

    /// Scripted maps for the `--module`-names-a-replaced-copy shape: one
    /// executable group rendering `<hint> (deleted)`. Memory reads stay
    /// off; the flag is about the mapping pass, not `/proc/<pid>/mem`.
    struct DeletedHintFixture {
        maps: Vec<u8>,
    }

    struct DeletedHintMemory;

    impl ScanMemory for DeletedHintMemory {
        fn read_memory_at(&self, _bytes: &mut [u8], _offset: u64) -> std::io::Result<usize> {
            Err(std::io::Error::other("memory not scripted"))
        }
    }

    impl ScanIo for DeletedHintFixture {
        type Memory = DeletedHintMemory;

        fn open_maps(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<Box<dyn Read>> {
            Ok(Box::new(std::io::Cursor::new(self.maps.clone())))
        }

        fn open_mem(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<DeletedHintMemory> {
            Err(std::io::Error::other("mem not scripted"))
        }

        fn final_generation(
            &mut self,
            view: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> Result<(), String> {
            view.run_while_same(|| ())
        }
    }

    /// A `--module` hint naming the replaced copy matches its still-mapped
    /// `<path> (deleted)` group: the scan names the replaced-file gap and
    /// never reports the hint as "not mapped in the target". The group is
    /// still never opened or attached.
    #[test]
    fn module_hint_naming_a_replaced_copy_names_the_gap_not_a_miss() {
        let dir = tempfile::tempdir().unwrap();
        let hint = dir.path().join("libtok.so");
        std::fs::write(&hint, b"provider bytes").unwrap();
        let maps = format!(
            "7f0000000000-7f0000001000 r-xp 00000000 08:01 4242 {} (deleted)\n",
            hint.display()
        );
        let mut fixture = DeletedHintFixture {
            maps: maps.into_bytes(),
        };
        let view = ProcessView::open(ProcessViewId(502), std::process::id()).unwrap();
        let mut budget = CaptureWorkBudget::default();
        let (outcome, _, hints_examined, _) = scan_view_with_examined(
            &ScanRequest {
                pid: view.pid(),
                hints: std::slice::from_ref(&hint),
                hooks: &HookRegistry::builtin(),
            },
            &view,
            &mut budget,
            &mut fixture,
            false,
        )
        .expect("the scan must complete, not error");
        assert!(hints_examined, "the scan reached the hint loop");
        assert!(
            outcome.modules().is_empty(),
            "a replaced copy is never attached, got {:?}",
            outcome.modules()
        );
        let reasons: Vec<(&str, &str)> = outcome
            .skipped()
            .iter()
            .map(|skip| (skip.subject.as_str(), skip.reason.as_str()))
            .collect();
        assert!(
            reasons
                .iter()
                .any(|(subject, reason)| subject.ends_with(" (deleted)")
                    && *reason == REPLACED_PROVIDER_REASON),
            "the hint names the replaced-file gap, got {reasons:?}"
        );
        assert!(
            !reasons
                .iter()
                .any(|(_, reason)| *reason == HINT_NOT_MAPPED_REASON),
            "the replaced copy is mapped, never missed, got {reasons:?}"
        );
    }

    /// Non-UTF-8 twin of the replaced-copy hint match: `mapped_path`
    /// classifies `\012`-free paths ending in ` (deleted)` as a deleted
    /// mapping before the UTF-8 check, so the stripped comparison must run
    /// in the OsStr/bytes domain — never through `str` — or the hint is
    /// misreported as not mapped.
    #[test]
    fn non_utf8_hint_naming_a_replaced_copy_names_the_gap_not_a_miss() {
        use std::os::unix::ffi::{OsStrExt as _, OsStringExt as _};
        let dir = tempfile::tempdir().unwrap();
        let hint = dir
            .path()
            .join(std::ffi::OsString::from_vec(b"libtok\xff.so".to_vec()));
        std::fs::write(&hint, b"provider bytes").unwrap();
        let mut maps = b"7f0000000000-7f0000001000 r-xp 00000000 08:01 4242 ".to_vec();
        maps.extend_from_slice(hint.as_os_str().as_bytes());
        maps.extend_from_slice(b" (deleted)\n");
        let mut fixture = DeletedHintFixture { maps };
        let view = ProcessView::open(ProcessViewId(502), std::process::id()).unwrap();
        let mut budget = CaptureWorkBudget::default();
        let (outcome, _, hints_examined, _) = scan_view_with_examined(
            &ScanRequest {
                pid: view.pid(),
                hints: std::slice::from_ref(&hint),
                hooks: &HookRegistry::builtin(),
            },
            &view,
            &mut budget,
            &mut fixture,
            false,
        )
        .expect("the scan must complete, not error");
        assert!(hints_examined, "the scan reached the hint loop");
        assert!(
            outcome.modules().is_empty(),
            "a replaced copy is never attached, got {:?}",
            outcome.modules()
        );
        let reasons: Vec<(&str, &str)> = outcome
            .skipped()
            .iter()
            .map(|skip| (skip.subject.as_str(), skip.reason.as_str()))
            .collect();
        assert!(
            reasons
                .iter()
                .any(|(subject, reason)| subject.ends_with(" (deleted)")
                    && *reason == REPLACED_PROVIDER_REASON),
            "the hint names the replaced-file gap, got {reasons:?}"
        );
        assert!(
            !reasons
                .iter()
                .any(|(_, reason)| *reason == HINT_NOT_MAPPED_REASON),
            "the replaced copy is mapped, never missed, got {reasons:?}"
        );
    }

    // Owner-approved 2026-09-27: `unsupported_version_of` and its matrix
    // test are retired with F-14's version skip — future minors walk now,
    // so there is no version refusal to classify. The version matrix lives
    // on as `future_minor_version_words_walk_the_known_prefix` above.

    // Owner-approved 2026-09-27: F-14's version skip is retired. Future
    // minors now walk as known prefixes (see the tests below), so a
    // version-shaped word that decodes nothing is data, not a refused
    // table — the sweep stays silent and the render vocabulary keeps the
    // legacy reason only so old captures still validate.
    #[test]
    fn short_future_minor_word_is_data_not_a_refused_table() {
        let maps = parse_maps(b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n").unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let mut snapshot = vec![0u8; 64];
        snapshot[..8].copy_from_slice(&0x2902u64.to_ne_bytes());
        snapshot[16..24].copy_from_slice(&0x2902u64.to_ne_bytes());
        let mut budget = CaptureWorkBudget::default();
        let (tables, skipped) = detect_tables(&snapshot, 0x7000, &map_index, &mut budget);
        assert!(tables.is_empty(), "64 bytes cannot hold a 68-slot table");
        assert!(
            skipped.is_empty(),
            "no version skip is emitted: {skipped:?}"
        );
        // The public mapping still renders the legacy reason, finite
        // vocabulary: old captures validate unchanged.
        let out = crate::render::capture_skipped_out(&Skipped {
            subject: "discovery subject".into(),
            reason: "unsupported function-table version; the scanner does not walk this layout"
                .into(),
        });
        assert_eq!(
            out.reason,
            "unsupported function-table version; the scanner does not walk this layout"
        );
    }

    // Owner-approved 2026-09-27: the scanner follows the same versioning
    // rule as the helper/manifest path — any minor of a known major (2.x,
    // 3.x) walks, newer minors as the known prefix; only a new major
    // refuses. `tables_for` bounds every minor to its known prefix (68 /
    // 104 slots), so no upper minor bound is needed here.
    #[test]
    fn future_minor_version_words_walk_the_known_prefix() {
        for (word, version, slots) in [
            (0x2902u64, (2u8, 41u8), 68usize),
            (0xff02, (2, 255), 68),
            (0x0303, (3, 3), 104),
            (0x0903, (3, 9), 104),
            (0xff03, (3, 255), 104),
        ] {
            let (decoded, spans, walk) = spans_for(word).expect("future minor walks");
            assert_eq!((decoded, walk), (version, "known_prefix"), "{word:#x}");
            assert_eq!(
                spans.iter().map(|span| span.fields().len()).sum::<usize>(),
                slots,
                "{version:?} walks its known-prefix slot count"
            );
        }
        // A new major stays refused: unknown layout, walk nothing.
        for word in [
            0x0004u64,
            0x0204,
            0x0304,
            0x0000,
            0xffff,
            0x1_0000,
            u64::MAX,
        ] {
            assert!(spans_for(word).is_none(), "{word:#x} must not be a table");
        }
    }

    // Owner-approved 2026-09-27: a complete future-minor table decodes and
    // attaches as its known prefix — the [3,9] interface table as the
    // 104-slot 3.2 layout, the [2,41] legacy table as the 68-slot layout —
    // with no version skip.
    #[test]
    fn future_minor_tables_decode_as_known_prefix_without_a_version_skip() {
        let maps = parse_maps(b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n").unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        for (word, version, slots) in [(0x0903u64, (3u8, 9u8), 104usize), (0x2902, (2, 41), 68)] {
            let mut snapshot = vec![0u8; 8 + slots * 8];
            snapshot[..8].copy_from_slice(&word.to_ne_bytes());
            for slot in 0..slots {
                let at = 8 + slot * 8;
                snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_ne_bytes());
            }
            let mut budget = CaptureWorkBudget::default();
            let (tables, skipped) = detect_tables(&snapshot, 0x7000, &map_index, &mut budget);
            assert_eq!(tables.len(), 1, "{version:?}: one table");
            assert_eq!(tables[0].version, version);
            assert_eq!(tables[0].walk, "known_prefix");
            assert_eq!(
                tables[0].entries.len() + tables[0].null_entries.len(),
                slots,
                "{version:?}: the known-prefix slots"
            );
            assert!(
                skipped
                    .iter()
                    .all(|reason| !reason.contains("unsupported function-table")),
                "{version:?}: no version skip: {skipped:?}"
            );
        }
    }

    // Owner-approved 2026-09-27: a new major ([4,0]) is refused — and the
    // refusal is silent at the scan gate, exactly like the manifest path's
    // `TableSet::Refuse` (empty walk, no skip): a version-shaped word for
    // an unknown layout is data, not a table.
    #[test]
    fn new_major_version_word_is_refused_without_a_skip() {
        assert!(spans_for(0x0004).is_none());
        let maps = parse_maps(b"1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n").unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let mut snapshot = vec![0u8; 64];
        snapshot[..8].copy_from_slice(&0x0004u64.to_ne_bytes());
        let mut budget = CaptureWorkBudget::default();
        let (tables, skipped) = detect_tables(&snapshot, 0x7000, &map_index, &mut budget);
        assert!(tables.is_empty());
        assert!(
            skipped.is_empty(),
            "a refused major leaves no skip: {skipped:?}"
        );
    }

    fn inventory_limits(
        window_io: u64,
        window_work: u64,
        decoded_tables: usize,
        decoded_entries: usize,
        interfaces: usize,
        retained_tables: usize,
    ) -> InventoryDiscoveryLimits {
        InventoryDiscoveryLimits::new(
            window_io,
            InventoryWindowLimits::new(
                window_io,
                window_work,
                decoded_tables,
                decoded_entries,
                interfaces,
            )
            .unwrap(),
            InventoryRetainedLimits::new(
                retained_tables,
                retained_tables,
                retained_tables,
                4,
                4,
                64 * 1024,
            )
            .unwrap(),
        )
        .unwrap()
    }

    /// Inventory limits with the usual four-entry file caches but a chosen
    /// accounted-byte ceiling, for carried-cache byte-edge tests.
    fn tight_export_limits(cache_bytes: u64) -> InventoryDiscoveryLimits {
        InventoryDiscoveryLimits::new(
            8 << 20,
            InventoryWindowLimits::new(8 << 20, 1 << 20, 4096, 32768, 4096).unwrap(),
            InventoryRetainedLimits::new(512, 512, 512, 4, 4, cache_bytes).unwrap(),
        )
        .unwrap()
    }

    fn table_identity(index: u64) -> TableIdentity {
        TableIdentity {
            device: Device { major: 8, minor: 1 },
            inode: index + 1,
            file_offset: index * 8,
            version_word: 0x2802,
            usable: 68,
        }
    }

    #[test]
    fn inventory_limits_are_checked_and_detailed_legacy_stays_the_default() {
        assert!(InventoryWindowLimits::new(0, 1, 1, 1, 1).is_err());
        assert!(InventoryWindowLimits::new(1, 0, 1, 1, 1).is_err());
        assert!(InventoryRetainedLimits::new(0, 1, 1, 1, 1, 1).is_err());
        let window = InventoryWindowLimits::new(8, 1, 1, 1, 1).unwrap();
        let retained = InventoryRetainedLimits::new(1, 1, 1, 1, 1, 1).unwrap();
        assert!(InventoryDiscoveryLimits::new(0, window, retained).is_err());
        assert!(InventoryDiscoveryLimits::new(9, window, retained).is_err());

        let mut detailed = CaptureWorkBudget::default();
        assert_eq!(detailed.policy(), DiscoveryPolicy::DetailedLegacy);
        for _ in 0..MAX_TABLE_CANDIDATES {
            assert!(detailed.admit_table(1));
        }
        assert!(!detailed.admit_table(1));
        assert!(
            detailed.begin_window(WindowId::new(1), 10).is_err(),
            "DetailedLegacy does not silently opt into renewable inventory work"
        );
    }

    #[test]
    fn inventory_windows_renew_work_io_and_decode_but_keep_evidence_and_keys() {
        let limits = inventory_limits(4, 2, 1, 68, 1, 4);
        let mut budget = CaptureWorkBudget::for_inventory(limits);
        assert!(budget.remaining_window_io().is_err());
        assert!(!budget.charge(1), "inventory work needs an active window");

        let first = budget.begin_window(WindowId::new(1), 100).unwrap();
        let first_scan = budget.checkpoint(first.clone()).unwrap();
        assert!(budget.charge(1));
        assert!(budget.admit_decoded_table(68));
        let identity = table_identity(1);
        assert!(budget.note_table_admitted(identity));
        assert!(budget.charge(1));
        assert!(!budget.charge(1));
        // Owner-approved 2026-09-27: F-14's version-refusal counter is
        // retired with the skip (future minors walk now); stickiness of
        // prior loss stays covered by the work-units assertion below.
        budget.finish_scan(first_scan).unwrap();
        let first_receipt = budget.finish_window(first.clone()).unwrap();
        assert_eq!(first_receipt.work_units(), 2);
        assert_eq!(first_receipt.stop_reason(), Some(WORK_CEILING_REASON));
        assert_eq!(budget.retained_counts().0, 1);
        assert!(
            budget.checkpoint(first.clone()).is_err(),
            "finished token is stale"
        );
        assert!(
            budget.begin_window(WindowId::new(1), 200).is_err(),
            "window IDs are monotonic"
        );

        let second = budget.begin_window(WindowId::new(2), 200).unwrap();
        let second_scan = budget.checkpoint(second.clone()).unwrap();
        assert!(budget.charge(1), "work allowance renews");
        assert!(budget.admit_decoded_table(68), "decode allowance renews");
        assert!(
            budget.note_table_admitted(identity),
            "a repeat remains valid"
        );
        assert!(budget.charge(1));
        assert_eq!(
            budget.retained_counts().0,
            1,
            "repeat key does not grow retention"
        );
        assert_eq!(
            budget.work_units_count(),
            4,
            "lifetime work evidence is cumulative"
        );
        budget.finish_scan(second_scan).unwrap();
        budget.finish_window(second).unwrap();
    }

    #[test]
    fn inventory_rejects_stale_missing_and_active_window_transitions() {
        let mut budget = CaptureWorkBudget::for_inventory(inventory_limits(8, 8, 2, 136, 2, 4));
        assert!(budget.remaining_window_io().is_err());
        let first = budget.begin_window(WindowId::new(7), 100).unwrap();
        let scan = budget.checkpoint(first.clone()).unwrap();
        let stale = scan.clone();
        let finished = scan.clone();
        assert!(
            budget.checkpoint(first.clone()).is_err(),
            "one scan owns the window"
        );
        assert!(budget.begin_window(WindowId::new(8), 200).is_err());
        assert!(budget.finish_window(first.clone()).is_err());
        budget.finish_scan(scan).unwrap();
        let current = budget.checkpoint(first.clone()).unwrap();
        assert!(
            budget.finish_scan(stale).is_err(),
            "scan A cannot finish scan B in the same window"
        );
        assert!(
            budget.finish_window(first.clone()).is_err(),
            "failed stale completion leaves scan B active"
        );
        assert!(
            budget.begin_window(WindowId::new(8), 200).is_err(),
            "failed stale completion cannot authorize renewal"
        );
        budget.finish_scan(current).unwrap();
        budget.finish_window(first.clone()).unwrap();
        assert!(budget.finish_scan(finished).is_err());
        assert!(budget.checkpoint(first.clone()).is_err());
        assert!(budget.begin_window(WindowId::new(6), 300).is_err());
        assert!(
            !budget.note_table_admitted(table_identity(99)),
            "retained inventory state cannot change outside an owned scan"
        );
    }

    #[test]
    fn inventory_tokens_are_bound_to_one_budget_domain() {
        let limits = inventory_limits(8, 8, 2, 136, 2, 4);
        let mut first_budget = CaptureWorkBudget::for_inventory(limits);
        let mut second_budget = CaptureWorkBudget::for_inventory(limits);
        let first = first_budget.begin_window(WindowId::new(1), 100).unwrap();
        let second = second_budget.begin_window(WindowId::new(1), 100).unwrap();

        assert!(
            second_budget.checkpoint(first.clone()).is_err(),
            "equal caller IDs do not transfer authority across budgets"
        );
        let scan = second_budget.checkpoint(second.clone()).unwrap();
        second_budget.finish_scan(scan).unwrap();
        second_budget.finish_window(second).unwrap();
        first_budget.finish_window(first).unwrap();
    }

