    #[test]
    fn inventory_window_deadline_survives_nested_deadline_clear() {
        let mut budget = CaptureWorkBudget::for_inventory(inventory_limits(8, 8, 2, 136, 2, 4));
        let first = budget.begin_window(WindowId::new(1), 10).unwrap();
        let scan = budget.checkpoint(first.clone()).unwrap();
        budget.set_deadline(Some(5));
        assert_eq!(budget.check_deadline(Some(5)), Some(SCAN_DEADLINE_REASON));
        budget.set_deadline(None);
        assert_eq!(
            budget.stopped_reason(),
            Some(SCAN_DEADLINE_REASON),
            "clearing a nested deadline cannot clear the window stop"
        );
        budget.finish_scan(scan).unwrap();
        budget.finish_window(first).unwrap();

        let second = budget.begin_window(WindowId::new(2), 20).unwrap();
        let scan = budget.checkpoint(second.clone()).unwrap();
        budget.set_deadline(Some(30));
        assert_eq!(budget.check_deadline(Some(19)), None);
        assert_eq!(budget.check_deadline(Some(20)), Some(SCAN_DEADLINE_REASON));
        budget.finish_scan(scan).unwrap();
        budget.finish_window(second).unwrap();
    }

    #[test]
    fn inventory_decoder_retains_513_candidates_and_charges_repeats_across_windows() {
        let table_len = 8 + 68 * 8;
        let table_end = 0x7000 + 514 * table_len as u64;
        let maps = parse_maps(
            format!(
                "1000-3000 r-xp 00000000 08:01 7 /lib/provider.so\n\
                 7000-{table_end:x} r--p 00001000 08:01 9 /lib/tables.so\n"
            )
            .as_bytes(),
        )
        .unwrap();
        let map_index = MapIndex::new(&maps).unwrap();
        let mut snapshot = vec![0u8; table_len];
        snapshot[..8].copy_from_slice(&0x2802u64.to_ne_bytes());
        for slot in 0..68 {
            let at = 8 + slot * 8;
            snapshot[at..at + 8].copy_from_slice(&0x1500u64.to_ne_bytes());
        }

        let limits = inventory_limits(8, 68, 1, 68, 1, 513);
        let mut budget = CaptureWorkBudget::for_inventory(limits);
        for index in 0..513u64 {
            let token = budget
                .begin_window(WindowId::new(index + 1), u64::MAX)
                .unwrap();
            let scan = budget.checkpoint(token.clone()).unwrap();
            let address = 0x7000 + index * table_len as u64;
            assert!(
                decode_exact_table(
                    &snapshot,
                    address,
                    LinuxLayout::Lp64,
                    &map_index,
                    &mut budget,
                    None,
                )
                .unwrap()
                .is_some(),
                "candidate {index} passes the actual decoder"
            );
            budget.finish_scan(scan).unwrap();
            budget.finish_window(token).unwrap();
        }
        assert_eq!(budget.retained_counts().0, 513);
        assert_eq!(budget.table_candidates_count(), 513);
        assert_eq!(budget.decoded_table_entries_count(), 513 * 68);
        assert_eq!(budget.work_units_count(), 513 * 68);
        assert_eq!(budget.refusal_counts(), (0, 0));

        let token = budget.begin_window(WindowId::new(514), u64::MAX).unwrap();
        let scan = budget.checkpoint(token.clone()).unwrap();
        assert!(
            decode_exact_table(
                &snapshot,
                0x7000,
                LinuxLayout::Lp64,
                &map_index,
                &mut budget,
                None,
            )
            .unwrap()
            .is_some(),
            "a repeat still traverses the actual decoder"
        );
        assert_eq!(budget.retained_counts().0, 513);
        assert_eq!(budget.table_candidates_count(), 514);
        assert_eq!(budget.decoded_table_entries_count(), 514 * 68);
        assert_eq!(budget.work_units_count(), 514 * 68);
        budget.finish_scan(scan).unwrap();
        budget.finish_window(token).unwrap();

        let token = budget.begin_window(WindowId::new(515), u64::MAX).unwrap();
        let scan = budget.checkpoint(token.clone()).unwrap();
        assert!(
            decode_exact_table(
                &snapshot,
                0x7000 + 513 * table_len as u64,
                LinuxLayout::Lp64,
                &map_index,
                &mut budget,
                None,
            )
            .is_err(),
            "the configured retained-key limit refuses one decoded candidate over"
        );
        assert_eq!(budget.retained_counts().0, 513);
        assert_eq!(budget.table_candidates_count(), 515);
        assert_eq!(budget.decoded_table_entries_count(), 515 * 68);
        assert_eq!(budget.work_units_count(), 515 * 68);
        assert_eq!(budget.refusal_counts(), (1, 0));
        budget.finish_scan(scan).unwrap();
        budget.finish_window(token).unwrap();
    }

    #[test]
    fn inventory_runtime_interface_and_cache_bounds_are_independent_and_exact() {
        let window = InventoryWindowLimits::new(1024, 32, 4, 512, 4).unwrap();
        let retained = InventoryRetainedLimits::new(2, 1, 1, 1, 1, u64::MAX).unwrap();
        let limits = InventoryDiscoveryLimits::new(1024, window, retained).unwrap();
        let mut budget = CaptureWorkBudget::for_inventory(limits);
        let token = budget.begin_window(WindowId::new(1), u64::MAX).unwrap();
        let scan = budget.checkpoint(token.clone()).unwrap();

        let runtime = |view| RuntimeTableIdentity {
            view: ProcessViewId(view),
            address: 0x1000,
            version_word: 0x2802,
            usable: 68,
            content: u64::from(view),
        };
        assert!(budget.note_runtime_table_admitted(runtime(1)));
        assert!(!budget.note_runtime_table_admitted(runtime(2)));

        let interface = |flags| InterfaceIdentity {
            table: InterfaceTableKey::File(table_identity(1)),
            name: InterfaceNameKey::Null,
            flags,
        };
        assert!(budget.note_interface_admitted(interface(1)));
        assert!(!budget.note_interface_admitted(interface(2)));

        let file = File::open("/bin/sh").unwrap();
        let inspected = p11scope_manifest::identity::inspect_file(&file).unwrap();
        let pin = pin_of(&file).unwrap();
        let fd_dev = file.metadata().unwrap().dev();
        let key = |inode| InspectedFileKey {
            device: Device { major: 8, minor: 1 },
            inode,
            pin,
            fd_dev,
        };
        assert!(budget.note_inspected_file(key(1), inspected.clone()));
        assert!(!budget.note_inspected_file(key(2), inspected));

        let facts = ElfExportFacts {
            abi: ElfAbi::Lp64,
            exports: vec![("C_GetFunctionList".into(), 7)],
            getter_present: false,
            witness_fault: false,
            excluded_anchor_ranges: Vec::new(),
        };
        assert!(budget.note_elf_export_facts(key(1), facts.clone()));
        assert!(!budget.note_elf_export_facts(key(2), facts));
        assert_eq!(budget.retained_counts().1, 1);
        assert_eq!(budget.retained_counts().2, 1);
        assert_eq!(budget.retained_counts().3, 1);
        assert_eq!(budget.retained_counts().4, 1);

        budget.finish_scan(scan).unwrap();
        budget.finish_window(token).unwrap();
        let next = budget.begin_window(WindowId::new(2), u64::MAX).unwrap();
        assert!(budget.inspected_file(&key(1)).is_some());
        assert!(budget.elf_export_facts_for(&key(1)).is_some());
        budget.finish_window(next).unwrap();
    }

    /// Capture scans (DetailedLegacy) refuse inspection/export cache growth
    /// past the capture entry ceilings: a long `--system` capture scanning
    /// thousands of distinct files must not retain every file's facts
    /// forever (pre-fix, all 4096 synthetic admissions below were kept).
    #[test]
    fn capture_file_caches_refuse_past_entry_ceilings() {
        let mut budget = CaptureWorkBudget::new(ScanLimits::default());
        let file = File::open("/bin/sh").unwrap();
        let inspected = p11scope_manifest::identity::inspect_file(&file).unwrap();
        let pin = pin_of(&file).unwrap();
        let fd_dev = file.metadata().unwrap().dev();
        let key = |inode| InspectedFileKey {
            device: Device { major: 8, minor: 1 },
            inode,
            pin,
            fd_dev,
        };
        let facts = ElfExportFacts {
            abi: ElfAbi::Lp64,
            exports: vec![("C_GetFunctionList".into(), 7)],
            getter_present: false,
            witness_fault: false,
            excluded_anchor_ranges: Vec::new(),
        };
        assert!(budget.note_inspected_file(key(0), inspected.clone()));
        assert!(budget.note_elf_export_facts(key(0), facts.clone()));
        for i in 1..4 * CAPTURE_INSPECTION_CACHE_ENTRIES {
            let inode = i as u64;
            budget.note_inspected_file(key(inode), inspected.clone());
            budget.note_elf_export_facts(key(inode), facts.clone());
        }
        let (_, _, _, inspected_len, exports_len, _) = budget.retained_counts();
        assert!(
            inspected_len <= CAPTURE_INSPECTION_CACHE_ENTRIES,
            "inspected cache grew past its ceiling: {inspected_len}"
        );
        assert!(
            exports_len <= CAPTURE_EXPORT_CACHE_ENTRIES,
            "export cache grew past its ceiling: {exports_len}"
        );
    }

    /// Capture scans refuse file-cache growth past the capture byte ceiling:
    /// a run of huge export lists (tens of thousands of symbols, as in big
    /// test binaries) must not retain tens of MiB each without bound.
    #[test]
    fn capture_file_caches_refuse_past_byte_ceiling() {
        let mut budget = CaptureWorkBudget::new(ScanLimits::default());
        let file = File::open("/bin/sh").unwrap();
        let pin = pin_of(&file).unwrap();
        let fd_dev = file.metadata().unwrap().dev();
        let key = |inode| InspectedFileKey {
            device: Device { major: 8, minor: 1 },
            inode,
            pin,
            fd_dev,
        };
        // ~1 MiB of export names per value: 200 values would retain ~200 MiB.
        let exports: Vec<(String, u64)> = (0..20_000u64)
            .map(|i| (format!("exported_symbol_{i:06}"), i))
            .collect();
        let facts = ElfExportFacts {
            abi: ElfAbi::Lp64,
            exports,
            getter_present: false,
            witness_fault: false,
            excluded_anchor_ranges: Vec::new(),
        };
        for i in 0..200 {
            budget.note_elf_export_facts(key(i), facts.clone());
        }
        let (_, _, _, _, exports_len, bytes) = budget.retained_counts();
        assert!(
            bytes <= CAPTURE_RETAINED_CACHE_BYTES,
            "export cache bytes grew past the ceiling: {bytes}"
        );
        assert!(
            exports_len < 200,
            "export cache admitted every huge value: {exports_len}"
        );
    }

    /// Capture scans refuse loader-facts growth past the export entry
    /// ceiling (the loader map shares it).
    #[test]
    fn capture_loader_cache_refuses_past_entry_ceiling() {
        let mut budget = CaptureWorkBudget::new(ScanLimits::default());
        let file = File::open("/bin/sh").unwrap();
        let pin = pin_of(&file).unwrap();
        let key = |device| LoaderFactsKey { device, pin };
        let facts = LoaderElfFacts {
            abi: ElfAbi::Lp64,
            hook: Ok(None),
            state_address: Ok(None),
        };
        assert!(budget.note_loader_elf_facts(key(0), facts.clone()));
        for device in 1..4 * CAPTURE_EXPORT_CACHE_ENTRIES as u64 {
            budget.note_loader_elf_facts(key(device), facts.clone());
        }
        assert!(
            budget.loader_cache_len() <= CAPTURE_EXPORT_CACHE_ENTRIES,
            "loader cache grew past its ceiling: {}",
            budget.loader_cache_len()
        );
    }

    /// Two different files in two Btrfs subvolumes render the same maps
    /// (device, inode) and the same whole Pin{ino,size,ctime} (39 of 40
    /// host tries), differing only in the held fd's st_dev. Neither
    /// inspection cache may hand one file's digest and exports to the
    /// other.
    #[test]
    fn btrfs_equal_pin_twins_never_share_an_inspection() {
        let window = InventoryWindowLimits::new(1024, 32, 4, 512, 4).unwrap();
        let retained = InventoryRetainedLimits::new(2, 1, 1, 1, 1, u64::MAX).unwrap();
        let limits = InventoryDiscoveryLimits::new(1024, window, retained).unwrap();
        let mut budget = CaptureWorkBudget::for_inventory(limits);
        let token = budget.begin_window(WindowId::new(1), u64::MAX).unwrap();
        let scan = budget.checkpoint(token.clone()).unwrap();

        let file = File::open("/bin/sh").unwrap();
        let inspected = p11scope_manifest::identity::inspect_file(&file).unwrap();
        let pin = pin_of(&file).unwrap();
        // Both twins render one maps key and one pin; only the held fd's
        // st_dev (the subvolume's anonymous device) tells them apart.
        let twin_a = InspectedFileKey {
            device: Device {
                major: 0,
                minor: 140,
            },
            inode: 257,
            pin,
            fd_dev: 82,
        };
        let twin_b = InspectedFileKey {
            device: Device {
                major: 0,
                minor: 140,
            },
            inode: 257,
            pin,
            fd_dev: 97,
        };
        let facts = ElfExportFacts {
            abi: ElfAbi::Lp64,
            exports: vec![("C_GetFunctionList".into(), 7)],
            getter_present: false,
            witness_fault: false,
            excluded_anchor_ranges: Vec::new(),
        };
        assert!(budget.note_inspected_file(twin_a, inspected));
        assert!(budget.note_elf_export_facts(twin_a, facts));
        assert_eq!(
            budget.inspected_file(&twin_b),
            None,
            "a different file with an equal maps key and pin must not reuse the cached inspection"
        );
        assert_eq!(
            budget.elf_export_facts_for(&twin_b),
            None,
            "a different file with an equal maps key and pin must not reuse the cached export facts"
        );

        budget.finish_scan(scan).unwrap();
        budget.finish_window(token).unwrap();
    }

    /// Healthy twin: the same file inspected twice reuses its cached
    /// inspection and export facts (the cache still serves the common case).
