    /// Full-scan fixture for one overlay-held provider file: scripted
    /// maps over a small real ELF (`/bin/true` copied under a `.so`
    /// name), zeroed memory, an overlayfs held identity whose
    /// `(dev, ino)` equals the maps key, and a witness that either
    /// delegates to the production original-file proof (which
    /// early-outs, kernel-free, under scoped collection) or serves a
    /// scripted verdict.
    struct OverlayPublishFixture {
        maps: Vec<u8>,
        held: MappedFile,
        scripted: Option<WitnessOutcome>,
    }

    struct OverlayPublishMemory;

    impl ScanMemory for OverlayPublishMemory {
        fn read_memory_at(&self, bytes: &mut [u8], _offset: u64) -> std::io::Result<usize> {
            bytes.fill(0);
            Ok(bytes.len())
        }
    }

    impl ScanIo for OverlayPublishFixture {
        type Memory = OverlayPublishMemory;

        fn open_maps(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<Box<dyn Read>> {
            Ok(Box::new(std::io::Cursor::new(self.maps.clone())))
        }

        fn open_mem(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<OverlayPublishMemory> {
            Ok(OverlayPublishMemory)
        }

        fn final_generation(
            &mut self,
            view: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> Result<(), String> {
            view.run_while_same(|| ())
        }

        fn held_identity(&mut self, _file: &File) -> Option<MappedFile> {
            Some(self.held)
        }

        fn range_identity(
            &mut self,
            _: &ProcessView,
            _: u64,
            _: u64,
            _: &mut CaptureWorkBudget,
        ) -> Result<std::io::Result<crate::discovery::identity::FileIdentity>, String> {
            Ok(Ok(self.held.identity))
        }

        fn prove_original_file_diagnosed(
            &mut self,
            view: &ProcessView,
            file: &File,
            held: &MappedFile,
            key: ObjectKey,
            range: (u64, u64),
            budget: &mut CaptureWorkBudget,
        ) -> WitnessOutcome {
            match self.scripted {
                Some(outcome) => outcome,
                None => {
                    prove_original_file_diagnosed(view.pid(), file, held, key, &[range], budget)
                }
            }
        }
    }

    /// Drive one full deep scan over the overlay fixture: `collection`
    /// installs the cgroup scoped-collection hook (the production
    /// witness then deactivates, kernel-free), `scripted` replaces the
    /// witness verdict instead of delegating to production.
    fn scan_overlay_provider(
        dir: &tempfile::TempDir,
        collection: bool,
        scripted: Option<WitnessOutcome>,
    ) -> (ScanOutcome, std::path::PathBuf) {
        use std::os::unix::fs::MetadataExt as _;
        let so_path = dir.path().join("libprov.so");
        // A small real ELF under a `.so` name (the test image itself is
        // hundreds of megabytes and would blow the fixture's budget).
        let exe = std::fs::read("/bin/true").expect("a small system ELF reads");
        std::fs::write(&so_path, &exe).expect("the fixture provider writes");
        // The maps key comes from the same production function the
        // opened-file guard validates against (on btrfs the stat
        // device differs from the mapped device).
        let view = ProcessView::open(ProcessViewId(701), std::process::id())
            .expect("the test process opens");
        let key_file = std::fs::File::open(&so_path).expect("the fixture provider opens");
        let mut mounts = MountTableCache::default();
        let mut key_budget = CaptureWorkBudget::default();
        let key = crate::discovery::identity::retained_object_key_cached(
            &view,
            &key_file,
            &mut mounts,
            &mut key_budget,
        )
        .expect("the fixture key resolves");
        let (major, minor, ino) = (key.device.major, key.device.minor, key.inode);
        let maps = format!(
            "7f1000000000-7f1000001000 r-xp 00000000 {major:02x}:{minor:02x} {ino} {}\n\
             7f1000001000-7f1000002000 r--p 00001000 {major:02x}:{minor:02x} {ino} {}\n\
             7f1000002000-7f1000003000 rw-p 00002000 {major:02x}:{minor:02x} {ino} {}\n",
            so_path.display(),
            so_path.display(),
            so_path.display(),
        );
        // The held identity is the file's own stat namespace (what
        // `map_files` reports), distinct from the maps key above.
        let meta = std::fs::metadata(&so_path).expect("the fixture provider stats");
        let held = MappedFile {
            identity: crate::discovery::identity::FileIdentity {
                dev: meta.dev(),
                ino: meta.ino(),
            },
            fs_magic: Some(K1_RED_OVERLAY_MAGIC),
        };
        let mut fixture = OverlayPublishFixture {
            maps: maps.into_bytes(),
            held,
            scripted,
        };
        let mut budget = CaptureWorkBudget::default();
        if collection {
            budget.set_collection_work(CollectionWork::new(|_| true));
        }
        let hooks = HookRegistry::builtin();
        let (outcome, _, _, _) = scan_view_with_examined(
            &ScanRequest {
                pid: view.pid(),
                hints: std::slice::from_ref(&so_path),
                hooks: &hooks,
            },
            &view,
            &mut budget,
            &mut fixture,
            true,
        )
        .expect("the scan must complete, not error");
        (outcome, so_path)
    }

    /// Cgroup inventory on an overlay rootfs: scoped collection
    /// deactivates the kernel witness, so the overlay provider refuses
    /// with the witness-unavailable gap — but the scan must still
    /// publish the found module with that named gap (PARTIAL coverage
    /// downstream), never an empty view. No proof is claimed: the
    /// tables scan never finishes on the degraded module.
    #[test]
    fn cgroup_scoped_scan_publishes_overlay_module_with_unproven_gap() {
        let dir = tempfile::tempdir().unwrap();
        let (outcome, so_path) = scan_overlay_provider(&dir, true, None);
        let modules = outcome.modules();
        assert_eq!(
            modules.len(),
            1,
            "scoped collection publishes the found overlay module, got {modules:?} with skips {:?}",
            outcome.skipped(),
        );
        assert_eq!(modules[0].path, so_path.display().to_string());
        assert!(
            !modules[0].tables_scan_finished,
            "the degraded module claims no finished tables scan"
        );
        assert!(
            outcome.skipped().iter().any(|skip| skip.reason
                == "original_file_unproven: kernel witness unavailable: \
                    scoped collection deactivates the kernel proof"),
            "the named unavailable gap stands, got {:?}",
            outcome.skipped(),
        );
    }

    /// Healthy twin: without scoped collection the witness proves the
    /// fresh mapping and the module joins with no unproven gap (the
    /// `--system`/`--pid` shape on overlayfs).
    #[test]
    fn unscoped_scan_with_proven_witness_joins_without_gap() {
        let dir = tempfile::tempdir().unwrap();
        let (outcome, so_path) = scan_overlay_provider(
            &dir,
            false,
            Some(WitnessOutcome {
                verdict: WitnessVerdict::SameFile,
                diagnosis: None,
            }),
        );
        let modules = outcome.modules();
        assert_eq!(
            modules.len(),
            1,
            "a proven overlay module joins, got {modules:?} with skips {:?}",
            outcome.skipped(),
        );
        assert_eq!(modules[0].path, so_path.display().to_string());
        assert!(
            outcome
                .skipped()
                .iter()
                .all(|skip| !skip.reason.contains("original_file_unproven")),
            "a proven join carries no unproven gap, got {:?}",
            outcome.skipped(),
        );
    }

    /// Soundness twin: a proven-another-file verdict still refuses,
    /// even under scoped collection — a stale lower mapping never
    /// publishes the fresh upper file's facts.
    #[test]
    fn cgroup_scoped_scan_refuses_proven_stale_overlay_module() {
        let dir = tempfile::tempdir().unwrap();
        let (outcome, _) = scan_overlay_provider(
            &dir,
            true,
            Some(WitnessOutcome {
                verdict: WitnessVerdict::OtherFile,
                diagnosis: None,
            }),
        );
        assert!(
            outcome.modules().is_empty(),
            "a proven-stale mapping never publishes, got {:?}",
            outcome.modules(),
        );
        assert!(
            outcome
                .skipped()
                .iter()
                .any(|skip| skip.reason.contains("original_file_unproven")),
            "the stale refusal carries the finite gap, got {:?}",
            outcome.skipped(),
        );
    }

    /// Boundary twins: budget exhaustion and anchor failure keep
    /// refusing under scoped collection — only the unavailable family
    /// (the witness never ran) degrades to publish-with-gap.
    #[test]
    fn cgroup_scoped_scan_refuses_exhausted_and_anchor_failures() {
        for verdict in [
            WitnessVerdict::Failed(WitnessFailure::BudgetExhausted),
            WitnessVerdict::Failed(WitnessFailure::AnchorBindingFailed),
        ] {
            let dir = tempfile::tempdir().unwrap();
            let (outcome, _) = scan_overlay_provider(
                &dir,
                true,
                Some(WitnessOutcome {
                    verdict,
                    diagnosis: None,
                }),
            );
            assert!(
                outcome.modules().is_empty(),
                "a {verdict:?} refusal never publishes, got {:?}",
                outcome.modules(),
            );
        }
    }

    /// Scope twin: without scoped collection an unavailable witness
    /// keeps refusing (the `--system`/`--pid` fail-closed shape where
    /// the proof substrate itself is broken) — only the
    /// userspace-only cgroup path degrades.
    /// How the fallback fixture answers a `map_files` open: serve a
    /// fixture file (cloned per open), or fail with a scripted errno.
    enum MapFilesScript {
        Serve(File),
        Fail(i32),
    }

    /// A scan fixture whose target-root open is scripted while its
    /// `map_files` range opens a real fixture file: the sandboxed-process
    /// shape (an unreachable root, a working `map_files` route), with the
    /// maps key, guards and ELF facts all real.
    struct MapFilesFallbackFixture {
        _dir: tempfile::TempDir,
        path: PathBuf,
        key: ObjectKey,
        view: ProcessView,
        maps: String,
        mem: File,
        log: std::rc::Rc<std::cell::RefCell<Vec<String>>>,
        /// Scripted target-root open failure; `None` performs the real
        /// open (the healthy route).
        root_failure: Option<MappedOpenError>,
        map_files: MapFilesScript,
        /// Scripted `vm_file` identities (held fd with its filesystem
        /// magic, target range).
        mapped: Option<(
            crate::discovery::identity::MappedFile,
            crate::discovery::identity::FileIdentity,
        )>,
        /// A held handle to the fixture file after its path was
        /// unlinked: the replaced-on-disk shape (the maps line reads
        /// `<path> (deleted)` while the running bytes stay open).
        deleted_held: Option<File>,
        /// Scripted mount-table emptiness for the exemption probe;
        /// `None` runs the live probe (this fixture's own table reads
        /// nonempty). `Some(false)` scripts both collapsed states at
        /// once: an unreadable and a nonempty table both keep the guard.
        mountinfo_empty: Option<bool>,
        /// Scripted re-stated key of the served file for the
        /// exempt-path maps-key check; `None` stats the live fd.
        restated: Option<ObjectKey>,
        /// Scripted re-stat failure for the exempt-path maps-key
        /// check; `Some` fails the re-stat instead of keying the fd.
        restated_err: Option<String>,
    }

    struct MapFilesFallbackMemory {
        file: File,
    }

    impl ScanMemory for MapFilesFallbackMemory {
        fn read_memory_at(&self, bytes: &mut [u8], offset: u64) -> std::io::Result<usize> {
            self.file.read_at(bytes, offset)
        }
    }

    impl ScanIo for MapFilesFallbackFixture {
        type Memory = MapFilesFallbackMemory;
        fn open_maps(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<Box<dyn Read>> {
            Ok(Box::new(std::io::Cursor::new(
                self.maps.as_bytes().to_vec(),
            )))
        }
        fn open_mem(
            &mut self,
            _: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> std::io::Result<MapFilesFallbackMemory> {
            Ok(MapFilesFallbackMemory {
                file: self.mem.try_clone()?,
            })
        }
        fn open_mapped_object(
            &mut self,
            view: &ProcessView,
            path: &str,
            budget: &mut CaptureWorkBudget,
        ) -> Result<File, MappedOpenError> {
            self.log.borrow_mut().push(format!("root open {path}"));
            match &self.root_failure {
                Some(failure) => Err(failure.clone()),
                // The healthy route: the real open, mirroring the
                // default (the fixture path exists under our own root).
                None => match view.with_filesystem(budget, |filesystem, _| {
                    Ok(filesystem.open_mapped_object(Path::new(path)))
                }) {
                    Ok(opened) => opened,
                    Err(reason) => Err(MappedOpenError {
                        reason,
                        foreign_target_root: None,
                        errno: None,
                    }),
                },
            }
        }
        fn open_map_files(
            &mut self,
            view: &ProcessView,
            start: u64,
            end: u64,
            _budget: &mut CaptureWorkBudget,
        ) -> std::io::Result<File> {
            self.log
                .borrow_mut()
                .push(format!("map_files {start:x}-{end:x} pid {}", view.pid()));
            match &self.map_files {
                MapFilesScript::Serve(file) => file.try_clone(),
                MapFilesScript::Fail(errno) => Err(std::io::Error::from_raw_os_error(*errno)),
            }
        }
        fn held_identity(&mut self, file: &File) -> Option<crate::discovery::identity::MappedFile> {
            match self.mapped {
                Some((held, _)) => Some(held),
                None => crate::discovery::identity::self_mapped_file(file).ok(),
            }
        }
        fn range_identity(
            &mut self,
            view: &ProcessView,
            start: u64,
            end: u64,
            _: &mut CaptureWorkBudget,
        ) -> Result<std::io::Result<crate::discovery::identity::FileIdentity>, String> {
            match self.mapped {
                Some((_, range)) => Ok(Ok(range)),
                None => view.run_while_same(|| {
                    crate::discovery::identity::map_files_identity(view.pid(), start, end)
                }),
            }
        }
        fn target_mountinfo_is_empty(
            &mut self,
            view: &ProcessView,
            mounts: &mut crate::process::MountTableCache,
            budget: &mut CaptureWorkBudget,
        ) -> bool {
            match self.mountinfo_empty {
                Some(scripted) => scripted,
                // The live probe, mirroring the default.
                None => matches!(
                    view.open_then_cached_mountinfo(|_| Ok(()), mounts, budget),
                    Ok(((), text)) if text.is_empty()
                ),
            }
        }
        fn restated_fd_key(&mut self, file: &File) -> std::io::Result<ObjectKey> {
            if let Some(reason) = &self.restated_err {
                return Err(std::io::Error::other(reason.clone()));
            }
            match self.restated {
                Some(key) => Ok(key),
                // The live re-stat, mirroring the default.
                None => file.metadata().map(|metadata| ObjectKey {
                    device: Device {
                        major: u64::from(libc::major(metadata.dev())),
                        minor: u64::from(libc::minor(metadata.dev())),
                    },
                    inode: metadata.ino(),
                }),
            }
        }
        fn final_generation(
            &mut self,
            view: &ProcessView,
            _: &mut CaptureWorkBudget,
        ) -> Result<(), String> {
            view.run_while_same(|| ())
        }
    }

    impl MapFilesFallbackFixture {
        fn new() -> Self {
            let dir = tempfile::tempdir().unwrap();
            let path = dir.path().join("libfixture.so");
            // Minimal independent x86-64 ELF header, mirroring
            // BracketFixture: parseable, exporting nothing wanted.
            let mut elf = vec![0u8; 64];
            elf[..7].copy_from_slice(&[0x7f, b'E', b'L', b'F', 2, 1, 1]);
            elf[16..18].copy_from_slice(&3u16.to_le_bytes());
            elf[18..20].copy_from_slice(&62u16.to_le_bytes());
            elf[20..24].copy_from_slice(&1u32.to_le_bytes());
            elf[52..54].copy_from_slice(&64u16.to_le_bytes());
            elf[54..56].copy_from_slice(&56u16.to_le_bytes());
            elf[58..60].copy_from_slice(&64u16.to_le_bytes());
            std::fs::write(&path, elf).unwrap();
            let view = ProcessView::open(ProcessViewId(72), std::process::id()).unwrap();
            let file = File::open(&path).unwrap();
            let key = crate::discovery::identity::retained_object_key(
                &view,
                &file,
                &mut CaptureWorkBudget::default(),
            )
            .unwrap();
            let identity = format!(
                "{:x}:{:x} {} {}",
                key.device.major,
                key.device.minor,
                key.inode,
                path.display()
            );
            let maps = format!(
                "1000-2000 r-xp 00000000 {identity}\n\
                 7000-8000 r--p 00004000 {identity}\n"
            );
            let mem = tempfile::tempfile().unwrap();
            mem.set_len(0xc000).unwrap();
            Self {
                _dir: dir,
                path,
                key,
                view,
                maps,
                mem,
                log: Default::default(),
                root_failure: None,
                map_files: MapFilesScript::Fail(libc::EPERM),
                mapped: None,
                deleted_held: None,
                mountinfo_empty: None,
                restated: None,
                restated_err: None,
            }
        }

        fn unreachable_root() -> MappedOpenError {
            MappedOpenError {
                reason: "opening object within retained target root: No such process (os error 3)"
                    .into(),
                foreign_target_root: Some("/proc/99999/fdinfo".into()),
                errno: Some(libc::ESRCH),
            }
        }

        /// The chrooted-daemon shape (rtkit-daemon: target root
        /// `/proc`, a foreign mount namespace, so no host fallback):
        /// an existing file the retained root cannot see.
        fn foreign_enoent() -> MappedOpenError {
            MappedOpenError {
                reason: "opening object within retained target root: No such file or directory (os error 2)"
                    .into(),
                foreign_target_root: Some("/proc".into()),
                errno: Some(libc::ENOENT),
            }
        }

        /// A genuinely missing file under the observer's own root:
        /// never a jail, never a fallback trigger.
        fn same_root_enoent() -> MappedOpenError {
            MappedOpenError {
                reason: "opening object within retained target root: No such file or directory (os error 2)"
                    .into(),
                foreign_target_root: None,
                errno: Some(libc::ENOENT),
            }
        }

        /// Re-render the fixture maps with the kernel's replaced-file
        /// marker: the group keeps its key while its path reads
        /// `<path> (deleted)`.
        fn render_deleted_maps(&mut self) {
            self.render_deleted_maps_with(&self.path.display().to_string());
        }

        /// The marker shape under an arbitrary displayed path (a memfd
        /// rendering keeps the fixture key).
        fn render_deleted_maps_with(&mut self, display: &str) {
            let identity = format!(
                "{:x}:{:x} {} {}",
                self.key.device.major, self.key.device.minor, self.key.inode, display
            );
            self.maps = format!(
                "1000-2000 r-xp 00000000 {identity} (deleted)\n\
                 7000-8000 r--p 00004000 {identity} (deleted)\n"
            );
        }

        /// The marker shape with the file still on disk: the scan
        /// branches on the suffix, not on the unlink.
        fn set_deleted_suffix(&mut self) {
            self.render_deleted_maps();
        }

        /// The faithful replaced-on-disk shape: the path is unlinked
        /// while a held handle keeps the running bytes (the guard and
        /// the ELF read below run live against the unlinked fd).
        fn set_deleted_unlinked(&mut self) {
            let held = File::open(&self.path).unwrap();
            std::fs::remove_file(&self.path).unwrap();
            self.render_deleted_maps();
            self.deleted_held = Some(held);
        }

        /// The held running bytes after [`Self::set_deleted_unlinked`],
        /// cloned for one `map_files` serve.
        fn deleted_served(&self) -> File {
            self.deleted_held
                .as_ref()
                .expect("set_deleted_unlinked first")
                .try_clone()
                .unwrap()
        }

        /// Scripted held identities model an ordinary filesystem, like
        /// BracketFixture: the magic is explicit.
        fn scripted_held(
            identity: crate::discovery::identity::FileIdentity,
        ) -> crate::discovery::identity::MappedFile {
            crate::discovery::identity::MappedFile {
                identity,
                fs_magic: Some(0xef53),
            }
        }

        /// Re-render the maps under an arbitrary key the fixture file
        /// cannot resolve to: the mount-table guard must refuse it,
        /// proving the guard ran.
        fn set_arbitrary_key(&mut self, major: u64, minor: u64, inode: u64, path: &str) {
            self.key = ObjectKey {
                device: Device { major, minor },
                inode,
            };
            let identity = format!("{major:x}:{minor:x} {inode} {path}");
            self.maps = format!(
                "1000-2000 r-xp 00000000 {identity}\n\
                 7000-8000 r--p 00004000 {identity}\n"
            );
        }

        fn run(
            &mut self,
            budget: &mut CaptureWorkBudget,
        ) -> Result<(ScanOutcome, Vec<ExaminedObject>, bool, BTreeSet<ObjectKey>), String> {
            self.run_with_hints(budget, &[])
        }

        fn run_with_hints(
            &mut self,
            budget: &mut CaptureWorkBudget,
            hints: &[PathBuf],
        ) -> Result<(ScanOutcome, Vec<ExaminedObject>, bool, BTreeSet<ObjectKey>), String> {
            let view = ProcessView::open(self.view.id(), self.view.pid()).unwrap();
            let hooks = HookRegistry::builtin();
            scan_view_with_examined(
                &ScanRequest {
                    pid: view.pid(),
                    hints,
                    hooks: &hooks,
                },
                &view,
                budget,
                self,
                true,
            )
        }
    }

    /// The sandboxed-process shape: the target-root open fails with
    /// `ESRCH` (an unreachable root, not an exit — the generation pin
    /// holds), while the VMA's `map_files` link opens the mapped file.
    /// The object must be examined, with no gap left behind.
    #[test]
    fn map_files_fallback_examines_object_when_target_root_is_unreachable() {
        use crate::discovery::identity::FileIdentity;
        let mut fixture = MapFilesFallbackFixture::new();
        let identity = FileIdentity { dev: 37, ino: 9 };
        fixture.root_failure = Some(MapFilesFallbackFixture::unreachable_root());
        fixture.map_files = MapFilesScript::Serve(File::open(fixture.path.clone()).unwrap());
        fixture.mapped = Some((MapFilesFallbackFixture::scripted_held(identity), identity));
        let (outcome, examined, _, _) = fixture.run(&mut CaptureWorkBudget::default()).unwrap();
        let subject = fixture.path.display().to_string();
        assert!(
            examined.iter().any(|object| object.key == fixture.key),
            "the map_files object must be examined, got examined={examined:?} skipped={:?}",
            outcome.skipped()
        );
        assert!(
            outcome.skipped().iter().all(|skip| skip.subject != subject),
            "no gap may remain for the examined object, got {:?}",
            outcome.skipped()
        );
        assert!(
            fixture
                .log
                .borrow()
                .iter()
                .any(|line| line.starts_with("map_files 1000-2000")),
            "the fallback must open the group's VMA range, got {:?}",
            fixture.log.borrow()
        );
    }

    /// Control twin: a reachable target root opens the object the
    /// ordinary way; `map_files` stays untouched.
    #[test]
    fn map_files_fallback_keeps_the_root_open_on_a_reachable_target() {
        use crate::discovery::identity::FileIdentity;
        let mut fixture = MapFilesFallbackFixture::new();
        let identity = FileIdentity { dev: 37, ino: 9 };
        fixture.root_failure = None;
        fixture.mapped = Some((MapFilesFallbackFixture::scripted_held(identity), identity));
        let (outcome, examined, _, _) = fixture.run(&mut CaptureWorkBudget::default()).unwrap();
        assert!(
            examined.iter().any(|object| object.key == fixture.key),
            "the root-opened object must be examined, got examined={examined:?} skipped={:?}",
            outcome.skipped()
        );
        assert!(
            outcome.skipped().is_empty(),
            "no gap may remain on the healthy route, got {:?}",
            outcome.skipped()
        );
        assert!(
            fixture
                .log
                .borrow()
                .iter()
                .all(|line| !line.starts_with("map_files")),
            "the healthy route must not touch map_files, got {:?}",
            fixture.log.borrow()
        );
    }

    /// Safety twin: the served file and the VMA's kernel identity
    /// disagree (the range was remapped after the maps read) — refuse
    /// with a named gap, never examine the wrong file.
    #[test]
    fn map_files_fallback_refuses_when_the_vma_identity_differs() {
        use crate::discovery::identity::FileIdentity;
        let mut fixture = MapFilesFallbackFixture::new();
        fixture.root_failure = Some(MapFilesFallbackFixture::unreachable_root());
        fixture.map_files = MapFilesScript::Serve(File::open(fixture.path.clone()).unwrap());
        fixture.mapped = Some((
            MapFilesFallbackFixture::scripted_held(FileIdentity { dev: 37, ino: 9 }),
            FileIdentity { dev: 37, ino: 10 },
        ));
        let (outcome, examined, _, _) = fixture.run(&mut CaptureWorkBudget::default()).unwrap();
        let subject = fixture.path.display().to_string();
        assert!(
            examined.iter().all(|object| object.key != fixture.key),
            "the mismatched object must stay unexamined, got {examined:?}"
        );
        assert!(
            outcome.modules().is_empty(),
            "the mismatched object must not join, got {:?}",
            outcome.modules()
        );
        assert!(
            outcome.skipped().iter().any(|skip| {
                skip.subject == subject
                    && skip.reason.contains("map_files")
                    && skip.reason.contains("refused")
            }),
            "the mismatch must refuse with a named map_files gap, got {:?}",
            outcome.skipped()
        );
    }

    /// The fallback attempt itself is recorded: when `map_files` stays
    /// unreadable, the original failure keeps its count and name, with
    /// the attempt beside it.
    #[test]
    fn map_files_fallback_keeps_a_named_gap_when_map_files_is_unreadable() {
        use crate::discovery::identity::FileIdentity;
        let mut fixture = MapFilesFallbackFixture::new();
        let identity = FileIdentity { dev: 37, ino: 9 };
        fixture.root_failure = Some(MapFilesFallbackFixture::unreachable_root());
        fixture.map_files = MapFilesScript::Fail(libc::EPERM);
        fixture.mapped = Some((MapFilesFallbackFixture::scripted_held(identity), identity));
        let (outcome, examined, _, _) = fixture.run(&mut CaptureWorkBudget::default()).unwrap();
        let subject = fixture.path.display().to_string();
        assert!(
            examined.iter().all(|object| object.key != fixture.key),
            "the unopenable object must stay unexamined, got {examined:?}"
        );
        let skip = outcome
            .skipped()
            .iter()
            .find(|skip| skip.subject == subject)
            .unwrap_or_else(|| panic!("a named gap must remain, got {:?}", outcome.skipped()));
        assert!(
            skip.reason.starts_with(
                "opening object within retained target root: No such process (os error 3)"
            ),
            "the original failure keeps its name, got {:?}",
            skip.reason
        );
        assert!(
            skip.reason.contains("(map_files fallback:"),
            "the attempt is recorded beside it, got {:?}",
            skip.reason
        );
        assert!(
            skip.reason
                .contains("(target root /proc/99999/fdinfo differs from the observer root)"),
            "the foreign root keeps its suffix, got {:?}",
            skip.reason
        );
    }

    /// The exemption needs a kernel-empty mount table: with a readable
    /// table (this fixture's own), the mount-table guard still runs for a
    /// map_files-proven file — even one whose identities would prove the
    /// key — and refuses the mismatch. The negative control that keeps the
    /// live exemption honest: proof alone never skips the guard.
    #[test]
    fn map_files_fallback_runs_the_mount_table_guard_when_mountinfo_is_available() {
        use crate::discovery::identity::{FileIdentity, MappedFile};
        let mut fixture = MapFilesFallbackFixture::new();
        fixture.set_arbitrary_key(8, 1, 999, "/libfixture-arbitrary.so");
        fixture.root_failure = Some(MapFilesFallbackFixture::unreachable_root());
        fixture.map_files = MapFilesScript::Serve(File::open(fixture.path.clone()).unwrap());
        let proven = FileIdentity {
            dev: libc::makedev(8, 1),
            ino: 999,
        };
        fixture.mapped = Some((
            MappedFile {
                identity: proven,
                fs_magic: Some(0xef53),
            },
            proven,
        ));
        let (outcome, examined, _, _) = fixture.run(&mut CaptureWorkBudget::default()).unwrap();
        assert!(
            examined.iter().all(|object| object.key != fixture.key),
            "the key-mismatched object must stay unexamined, got {examined:?}"
        );
        assert!(
            outcome.skipped().iter().any(|skip| {
                skip.subject == "/libfixture-arbitrary.so"
                    && skip.reason.contains("does not match mapped object")
            }),
            "the mount-table guard must refuse the mismatch, got {:?}",
            outcome.skipped()
        );
    }

    /// The exemption's positive half at runtime: a map_files-proven
    /// file under a kernel-empty mount table is examined even though
    /// the mount-table guard would refuse its key (the scripted twin
    /// of the live sandboxed shape). Fails if the exemption is
    /// disabled: the guard then refuses the arbitrary key.
    #[test]
    fn map_files_fallback_examines_proven_object_when_mountinfo_is_empty() {
        use crate::discovery::identity::{FileIdentity, MappedFile};
        let mut fixture = MapFilesFallbackFixture::new();
        fixture.set_arbitrary_key(8, 1, 999, "/libfixture-arbitrary.so");
        fixture.root_failure = Some(MapFilesFallbackFixture::unreachable_root());
        fixture.map_files = MapFilesScript::Serve(File::open(fixture.path.clone()).unwrap());
        let proven = FileIdentity {
            dev: libc::makedev(8, 1),
            ino: 999,
        };
        fixture.mapped = Some((
            MappedFile {
                identity: proven,
                fs_magic: Some(0xef53),
            },
            proven,
        ));
        // The exempt path binds the proven file to the maps key rather
        // than the guard: script the proven rendering at that key.
        fixture.restated = Some(fixture.key);
        fixture.mountinfo_empty = Some(true);
        let (outcome, examined, _, _) = fixture.run(&mut CaptureWorkBudget::default()).unwrap();
        assert!(
            examined.iter().any(|object| object.key == fixture.key),
            "the exempt proven object must be examined, got examined={examined:?} skipped={:?}",
            outcome.skipped()
        );
        assert!(
            outcome
                .skipped()
                .iter()
                .all(|skip| skip.subject != "/libfixture-arbitrary.so"),
            "no gap may remain for the exempt object, got {:?}",
            outcome.skipped()
        );
    }

    /// Safety twin: a scripted nonempty mount table keeps the guard —
